// keep disposable candidate databases beside the configured
// datadir (same filesystem capacity characteristics), not blindly under /tmp.
static std::filesystem::path candidateSandboxRootForDb(const std::string& dbPath) {
    std::filesystem::path livePath = std::filesystem::path(dbPath).lexically_normal();
    if (livePath.filename().empty() && livePath.has_parent_path()) {
        livePath = livePath.parent_path();
    }
    const std::string leaf = livePath.filename().empty()
        ? std::string("tru-data")
        : livePath.filename().string();
    return livePath.parent_path() / (leaf + ".08b3-sandboxes");
}

static void cleanupStaleCandidateSandboxesForDb(const std::string& dbPath) {
    const auto root = candidateSandboxRootForDb(dbPath);
    std::error_code ec;
    const bool exists = std::filesystem::exists(root, ec);
    if (ec) {
        Logger::log("[Patch08B.3b] WARNING: unable to inspect stale sandbox root " +
                    root.string() + ": " + ec.message());
        return;
    }
    if (!exists) return;
    const auto removed = std::filesystem::remove_all(root, ec);
    if (ec) {
        Logger::log("[Patch08B.3b] WARNING: unable to clean stale sandbox root " +
                    root.string() + ": " + ec.message());
    } else if (removed != 0) {
        Logger::log("[Patch08B.3b] Removed stale candidate sandbox filesystem entries=" +
                    std::to_string(removed));
    }
}

