static std::string rawBytesToHex(const std::string& raw) {
    static constexpr char kHex[] = "0123456789abcdef";

    if (raw.size() > std::numeric_limits<size_t>::max() / 2) {
        throw std::overflow_error("rawBytesToHex size overflow");
    }

    std::string out(raw.size() * 2, '0');
    for (size_t i = 0; i < raw.size(); ++i) {
        const unsigned char byte =
            static_cast<unsigned char>(raw[i]);
        out[2 * i] = kHex[(byte >> 4) & 0x0f];
        out[2 * i + 1] = kHex[byte & 0x0f];
    }
    return out;
}

static bool isEvenHexString(const std::string& value) {
    if ((value.size() & 1U) != 0U) return false;
    for (unsigned char c : value) {
        if (!std::isxdigit(c)) return false;
    }
    return true;
}

static std::string sha256HexRaw(const char* data, size_t size) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256(
        reinterpret_cast<const unsigned char*>(data),
        size,
        digest);

    static constexpr char kHex[] = "0123456789abcdef";
    std::string out(SHA256_DIGEST_LENGTH * 2, '0');
    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        out[2 * i] = kHex[(digest[i] >> 4) & 0x0f];
        out[2 * i + 1] = kHex[digest[i] & 0x0f];
    }
    return out;
}

static std::string sha256HexBytes(const std::string& data) {
    return sha256HexRaw(data.data(), data.size());
}

static bool parseChainWorkHexStrict(
    const std::string& text,
    ChainWork256& out) {

    if (text.size() != 64) return false;

    ChainWork256 value = 0;
    for (const unsigned char c : text) {
        unsigned int digit = 0;
        if (c >= '0' && c <= '9') {
            digit = static_cast<unsigned int>(c - '0');
        } else if (c >= 'a' && c <= 'f') {
            digit = 10U + static_cast<unsigned int>(c - 'a');
        } else {
            // Canonical marker encoding is lowercase fixed-width hex.
            return false;
        }

        value <<= 4;
        value += digit;
    }

    out = value;
    return true;
}

static std::string chainWorkHexFixed(const ChainWork256& work) {
    std::string hex = work.str(0, std::ios_base::hex);
    if (hex.size() > 64) {
        throw std::overflow_error("ChainWork256 hex rendering exceeded 64 chars");
    }
    if (hex.size() < 64) {
        hex.insert(hex.begin(), 64 - hex.size(), '0');
    }
    return hex;
}

static void appendFingerprintField(
    std::string& canonical,
    const std::string& field) {

    canonical += std::to_string(field.size());
    canonical.push_back(':');
    canonical.append(field);
}


// Patch 08B.4A v2 / 08B.4B.1 v2: authenticated reorg marker batching.
// Disconnect progress is batched with the rollback transition. CONNECT_PUBLISHED
// progress is batched with active-tip metadata after the candidate state batch.
static bool appendOptionalReorgMarkerToBatch(
    LevelDBStorage& storage,
    leveldb::WriteBatch& batch,
    const std::string* reorgMarkerPayload,
    std::string& reasonOut) {

    reasonOut.clear();
    if (reorgMarkerPayload == nullptr) return true;

    if (reorgMarkerPayload->empty() ||
        reorgMarkerPayload->size() > MAX_REORG_PENDING_RECORD_BYTES) {
        reasonOut = "reorg marker payload is empty/oversized";
        return false;
    }

    const std::string wrapped =
        storage.computeDataChecksum(*reorgMarkerPayload) + "|" +
        *reorgMarkerPayload;
    batch.Put(REORG_PENDING_KEY, wrapped);
    return true;
}

static std::string computeUndoBlockPayloadSha256(const Block& block) {
    // Do not use Block::serialize() directly here: tokenMetadata is an
    // unordered_map and its serialized iteration order is not guaranteed
    // across process restarts. Build an explicit canonical representation.
    std::string canonical;

    appendFingerprintField(canonical, block.header.serialize());
    appendFingerprintField(canonical, block.blockHash);
    appendFingerprintField(canonical, std::to_string(block.height));
    appendFingerprintField(canonical, std::to_string(block.transactions.size()));

    for (const auto& tx : block.transactions) {
        appendFingerprintField(canonical, tx.serialize());
    }

    std::map<std::string, std::string> sortedMetadata;
    for (const auto& [txid, metadata] : block.tokenMetadata) {
        sortedMetadata[txid] = metadata.dump();
    }

    appendFingerprintField(canonical, std::to_string(sortedMetadata.size()));
    for (const auto& [txid, metadataText] : sortedMetadata) {
        appendFingerprintField(canonical, txid);
        appendFingerprintField(canonical, metadataText);
    }

    return sha256HexBytes(canonical);
}

static bool rawMatchesHex(
    const std::string& raw,
    const std::string& hex) {

    if (raw.size() > std::numeric_limits<size_t>::max() / 2) return false;
    if (hex.size() != raw.size() * 2) return false;

    auto nibble = [](unsigned char c) -> int {
        if (c >= '0' && c <= '9') return static_cast<int>(c - '0');
        if (c >= 'a' && c <= 'f') return 10 + static_cast<int>(c - 'a');
        if (c >= 'A' && c <= 'F') return 10 + static_cast<int>(c - 'A');
        return -1;
    };

    for (size_t i = 0; i < raw.size(); ++i) {
        const int hi = nibble(static_cast<unsigned char>(hex[2 * i]));
        const int lo = nibble(static_cast<unsigned char>(hex[2 * i + 1]));
        if (hi < 0 || lo < 0) return false;
        const unsigned char expected =
            static_cast<unsigned char>((hi << 4) | lo);
        if (static_cast<unsigned char>(raw[i]) != expected) return false;
    }
    return true;
}

static UndoJournalProbe probeExistingUndoJournal(
    const LevelDBStorage& storage,
    const Block& block,
    std::vector<std::string>* affectedAddresses = nullptr,
    std::string* fingerprintCache = nullptr) {

    if (affectedAddresses) affectedAddresses->clear();
    if (block.height <= 1) return UndoJournalProbe::Absent;

    const std::string undoKey =
        std::string(UNDO_KEY_PREFIX) + block.blockHash;

    std::string rawJournal;
    bool found = false;
    if (!storage.getRaw(undoKey, rawJournal, found)) {
        Logger::log(
            "[Patch08B.1v4] ERROR: failed probing existing undo journal for " +
            block.blockHash);
        return UndoJournalProbe::Invalid;
    }
    if (!found) return UndoJournalProbe::Absent;

    // The raw existence test above distinguishes NotFound from corruption.
    // Now require the wrapper checksum to validate before trusting any fields.
    std::string payload;
    if (!storage.getWithDataChecksum(undoKey, payload)) {
        Logger::log(
            "[Patch08B.1v4] ERROR: existing undo journal failed checksum for " +
            block.blockHash);
        return UndoJournalProbe::Invalid;
    }

    try {
        const nlohmann::json journal = nlohmann::json::parse(payload);
        if (!journal.is_object()) {
            throw std::runtime_error("journal root is not an object");
        }

        if (!journal.contains("version") ||
            !journal["version"].is_string() ||
            journal["version"].get<std::string>() != UNDO_RULES_VERSION) {
            throw std::runtime_error(
                "journal version is not recoverable by P08B1-U4");
        }

        if (!journal.contains("blockHash") ||
            !journal["blockHash"].is_string() ||
            journal["blockHash"].get<std::string>() != block.blockHash) {
            throw std::runtime_error("journal blockHash mismatch");
        }

        if (!journal.contains("parentHash") ||
            !journal["parentHash"].is_string() ||
            journal["parentHash"].get<std::string>() != block.header.prevHash) {
            throw std::runtime_error("journal parentHash mismatch");
        }

        if (!journal.contains("height") ||
            !journal["height"].is_number_integer()) {
            throw std::runtime_error("journal height missing/invalid");
        }
        const uint64_t journalHeight = journal["height"].get<uint64_t>();
        if (journalHeight != static_cast<uint64_t>(block.height)) {
            throw std::runtime_error("journal height mismatch");
        }

        if (!journal.contains("blockPayloadSha256") ||
            !journal["blockPayloadSha256"].is_string()) {
            throw std::runtime_error("journal block payload fingerprint missing");
        }
        const std::string storedFingerprint =
            journal["blockPayloadSha256"].get<std::string>();

        std::string computedFingerprint;
        if (fingerprintCache && !fingerprintCache->empty()) {
            computedFingerprint = *fingerprintCache;
        } else {
            computedFingerprint = computeUndoBlockPayloadSha256(block);
            if (fingerprintCache) *fingerprintCache = computedFingerprint;
        }

        if (storedFingerprint.size() != 64 ||
            !isEvenHexString(storedFingerprint) ||
            storedFingerprint != computedFingerprint) {
            throw std::runtime_error("journal block payload fingerprint mismatch");
        }

        if (!journal.contains("entries") || !journal["entries"].is_array()) {
            throw std::runtime_error("journal entries missing/invalid");
        }
        if (!journal.contains("entryCount") ||
            !journal["entryCount"].is_number_integer()) {
            throw std::runtime_error("journal entryCount missing/invalid");
        }

        const uint64_t entryCount = journal["entryCount"].get<uint64_t>();
        if (entryCount == 0 || entryCount != journal["entries"].size()) {
            throw std::runtime_error("journal entryCount mismatch/empty");
        }

        std::unordered_set<std::string> recoveryAddressSet;
        std::unordered_set<std::string> seenKeys;
        static const std::string kAddressPrefix = "address:";
        static const std::string kTxCountSuffix = ":txCount";

        bool allPreState = true;
        bool allPostState = true;

        for (const auto& entry : journal["entries"]) {
            if (!entry.is_object() ||
                !entry.contains("key") || !entry["key"].is_string() ||
                !entry.contains("existed") || !entry["existed"].is_boolean() ||
                !entry.contains("postOp") || !entry["postOp"].is_string()) {
                throw std::runtime_error("journal entry structure invalid");
            }

            const std::string key = entry["key"].get<std::string>();
            const std::string postOp = entry["postOp"].get<std::string>();
            const bool existed = entry["existed"].get<bool>();

            if (key.empty() || key == undoKey) {
                throw std::runtime_error("journal entry key invalid");
            }
            if (!seenKeys.insert(key).second) {
                throw std::runtime_error("duplicate journal entry key");
            }
            if (postOp != "put" && postOp != "delete") {
                throw std::runtime_error("journal entry postOp invalid");
            }

            std::string oldRawHex;
            if (existed) {
                if (!entry.contains("oldRawHex") ||
                    !entry["oldRawHex"].is_string() ||
                    !isEvenHexString(entry["oldRawHex"].get<std::string>())) {
                    throw std::runtime_error("journal oldRawHex invalid");
                }
                oldRawHex = entry["oldRawHex"].get<std::string>();
            } else if (entry.contains("oldRawHex")) {
                throw std::runtime_error("journal has oldRawHex for absent pre-image");
            }

            std::string postRawSha256;
            if (postOp == "put") {
                if (!entry.contains("postRawSha256") ||
                    !entry["postRawSha256"].is_string()) {
                    throw std::runtime_error("journal postRawSha256 missing");
                }
                postRawSha256 = entry["postRawSha256"].get<std::string>();
                if (postRawSha256.size() != 64 ||
                    !isEvenHexString(postRawSha256)) {
                    throw std::runtime_error("journal postRawSha256 invalid");
                }
            } else if (entry.contains("postRawSha256")) {
                throw std::runtime_error("delete entry unexpectedly has postRawSha256");
            }

            // a valid journal proves what was atomically written
            // at commit time, but recovery may skip validation/apply ONLY if the
            // live DB still exactly matches that journaled POST-state. Also
            // recognize an exact PRE-state so a stale journal can be replaced
            // safely in the same re-apply batch. Any mixed state fails closed.
            std::string currentRaw;
            bool currentFound = false;
            if (!storage.getRaw(key, currentRaw, currentFound)) {
                throw std::runtime_error("failed reading live state for journal key");
            }

            const bool matchesPre =
                existed
                    ? (currentFound && rawMatchesHex(currentRaw, oldRawHex))
                    : !currentFound;

            const bool matchesPost =
                (postOp == "put")
                    ? (currentFound &&
                       sha256HexBytes(currentRaw) == postRawSha256)
                    : !currentFound;

            allPreState = allPreState && matchesPre;
            allPostState = allPostState && matchesPost;

            if (affectedAddresses &&
                key.rfind(kAddressPrefix, 0) == 0 &&
                key.size() > kAddressPrefix.size() + kTxCountSuffix.size() &&
                key.compare(
                    key.size() - kTxCountSuffix.size(),
                    kTxCountSuffix.size(),
                    kTxCountSuffix) == 0) {

                const size_t addrLen =
                    key.size() - kAddressPrefix.size() - kTxCountSuffix.size();
                recoveryAddressSet.insert(
                    key.substr(kAddressPrefix.size(), addrLen));
            }
        }

        if (affectedAddresses) {
            affectedAddresses->assign(
                recoveryAddressSet.begin(),
                recoveryAddressSet.end());
        }

        if (allPostState && !allPreState) {
            Logger::log(
                "[Patch08B.1v4] RECOVERY-WITNESS: exact post-block state verified for " +
                block.blockHash);
            return UndoJournalProbe::RecoverablePostState;
        }

        if (allPreState && !allPostState) {
            Logger::log(
                "[Patch08B.1v4] REAPPLY-WITNESS: exact pre-block state verified for stale journal " +
                block.blockHash);
            return UndoJournalProbe::ReapplyPreState;
        }

        throw std::runtime_error(
            allPreState && allPostState
                ? "journal state witness is ambiguous"
                : "live DB is mixed/neither exact journal PRE-state nor POST-state");
    } catch (const std::exception& e) {
        Logger::log(
            "[Patch08B.1v4] ERROR: existing undo journal is not safe for recovery/reapply block=" +
            block.blockHash + ": " + e.what());
        if (affectedAddresses) affectedAddresses->clear();
        return UndoJournalProbe::Invalid;
    }
}


//================================================================================
// TRU CORE RECOVERY CR-01A v1 - DIRECT-TIP STATE/PUBLICATION WITNESS
//================================================================================
struct DirectConnectPendingState {
    std::string phase;
    std::string blockHash;
    std::string parentHash;
    int height{0};
    uint32_t difficulty{0};
    std::string blockPayloadSha256;
    std::string blockRecordSha256;
    std::string blockKey;
    std::string undoKey;
    std::string markerSemantics;
    std::string exactPayload;
};

static bool cr01aIsLowerHex64(const std::string& value) {
    return value.size() == 64 &&
           std::all_of(
               value.begin(), value.end(), [](unsigned char c) {
                   return (c >= '0' && c <= '9') ||
                          (c >= 'a' && c <= 'f');
               });
}

static std::string buildDirectConnectPendingPayload(
    const Block& block,
    const std::string& serializedBlock) {

    if (block.height <= 1 || serializedBlock.empty() ||
        serializedBlock.size() > MAX_BLOCK_BYTES ||
        !cr01aIsLowerHex64(block.blockHash) ||
        !cr01aIsLowerHex64(block.header.prevHash)) {
        return {};
    }

    const std::string payloadSha =
        computeUndoBlockPayloadSha256(block);
    const std::string recordSha =
        sha256HexBytes(serializedBlock);
    if (!cr01aIsLowerHex64(payloadSha) ||
        !cr01aIsLowerHex64(recordSha)) {
        return {};
    }

    nlohmann::json marker = nlohmann::json::object();
    marker["version"] = DIRECT_CONNECT_RULES_VERSION;
    marker["phase"] = DIRECT_CONNECT_PHASE_STATE_COMMITTED;
    marker["blockHash"] = block.blockHash;
    marker["parentHash"] = block.header.prevHash;
    marker["height"] = block.height;
    marker["difficulty"] = block.header.bits;
    marker["blockPayloadSha256"] = payloadSha;
    marker["blockRecordSha256"] = recordSha;
    marker["blockKey"] = "block:" + block.blockHash;
    marker["undoKey"] =
        std::string(UNDO_KEY_PREFIX) + block.blockHash;
    marker["markerSemantics"] = DIRECT_CONNECT_MARKER_SEMANTICS;

    const std::string payload = marker.dump();
    if (payload.empty() ||
        payload.size() > MAX_DIRECT_CONNECT_PENDING_BYTES) {
        return {};
    }
    return payload;
}

static bool parseDirectConnectPendingPayload(
    const std::string& payload,
    DirectConnectPendingState& stateOut,
    std::string& reasonOut) {

    stateOut = DirectConnectPendingState{};
    reasonOut.clear();

    if (payload.empty() ||
        payload.size() > MAX_DIRECT_CONNECT_PENDING_BYTES) {
        reasonOut = "directconnect:pending payload is empty/oversized";
        return false;
    }

    try {
        const nlohmann::json marker = nlohmann::json::parse(payload);
        if (!marker.is_object()) {
            reasonOut = "directconnect:pending root is not an object";
            return false;
        }

        auto requireString = [&](const char* key, std::string& out) -> bool {
            if (!marker.contains(key) || !marker[key].is_string()) {
                reasonOut =
                    std::string("directconnect:pending missing/string field: ") + key;
                return false;
            }
            out = marker[key].get<std::string>();
            return true;
        };

        std::string version;
        if (!requireString("version", version) ||
            !requireString("phase", stateOut.phase) ||
            !requireString("blockHash", stateOut.blockHash) ||
            !requireString("parentHash", stateOut.parentHash) ||
            !requireString(
                "blockPayloadSha256", stateOut.blockPayloadSha256) ||
            !requireString(
                "blockRecordSha256", stateOut.blockRecordSha256) ||
            !requireString("blockKey", stateOut.blockKey) ||
            !requireString("undoKey", stateOut.undoKey) ||
            !requireString(
                "markerSemantics", stateOut.markerSemantics)) {
            return false;
        }

        if (version != DIRECT_CONNECT_RULES_VERSION ||
            stateOut.phase != DIRECT_CONNECT_PHASE_STATE_COMMITTED ||
            stateOut.markerSemantics != DIRECT_CONNECT_MARKER_SEMANTICS) {
            reasonOut = "directconnect:pending version/phase/semantics mismatch";
            return false;
        }

        if (!marker.contains("height") ||
            !marker["height"].is_number_integer()) {
            reasonOut = "directconnect:pending height missing/invalid";
            return false;
        }
        const long long height = marker["height"].get<long long>();
        if (height <= 1 || height > std::numeric_limits<int>::max()) {
            reasonOut = "directconnect:pending height out of range";
            return false;
        }
        stateOut.height = static_cast<int>(height);

        if (!marker.contains("difficulty") ||
            !(marker["difficulty"].is_number_unsigned() ||
              marker["difficulty"].is_number_integer())) {
            reasonOut = "directconnect:pending difficulty missing/invalid";
            return false;
        }
        const long long difficulty = marker["difficulty"].get<long long>();
        if (difficulty < 0 ||
            static_cast<unsigned long long>(difficulty) >
                std::numeric_limits<uint32_t>::max()) {
            reasonOut = "directconnect:pending difficulty out of range";
            return false;
        }
        stateOut.difficulty = static_cast<uint32_t>(difficulty);

        if (!cr01aIsLowerHex64(stateOut.blockHash) ||
            !cr01aIsLowerHex64(stateOut.parentHash) ||
            !cr01aIsLowerHex64(stateOut.blockPayloadSha256) ||
            !cr01aIsLowerHex64(stateOut.blockRecordSha256)) {
            reasonOut = "directconnect:pending hash encoding invalid";
            return false;
        }

        if (stateOut.blockKey != "block:" + stateOut.blockHash ||
            stateOut.undoKey !=
                std::string(UNDO_KEY_PREFIX) + stateOut.blockHash) {
            reasonOut = "directconnect:pending durable key identity mismatch";
            return false;
        }

        stateOut.exactPayload = payload;
        return true;
    } catch (const std::exception& e) {
        reasonOut =
            std::string("directconnect:pending parse failure: ") + e.what();
        return false;
    } catch (...) {
        reasonOut = "directconnect:pending parse failure";
        return false;
    }
}

static bool readDirectConnectPendingState(
    const LevelDBStorage& storage,
    DirectConnectPendingState& stateOut,
    bool& foundOut,
    std::string& reasonOut) {

    stateOut = DirectConnectPendingState{};
    foundOut = false;
    reasonOut.clear();

    std::string raw;
    bool found = false;
    if (!storage.getRaw(DIRECT_CONNECT_PENDING_KEY, raw, found)) {
        reasonOut = "raw LevelDB read failed for directconnect:pending";
        return false;
    }
    if (!found) return true;
    foundOut = true;

    // checksum hex + '|' + bounded payload
    if (raw.size() > MAX_DIRECT_CONNECT_PENDING_BYTES + 65ULL) {
        reasonOut = "directconnect:pending raw record exceeds hard size limit";
        return false;
    }

    std::string payload;
    if (!storage.getWithDataChecksum(
            DIRECT_CONNECT_PENDING_KEY, payload)) {
        reasonOut = "directconnect:pending checksum/authentication failed";
        return false;
    }

    return parseDirectConnectPendingPayload(
        payload, stateOut, reasonOut);
}

static bool loadDirectConnectDurableBlock(
    const LevelDBStorage& storage,
    const DirectConnectPendingState& state,
    Block& blockOut,
    std::string& reasonOut) {

    reasonOut.clear();
    std::string serialized;
    if (!storage.getWithDataChecksum(state.blockKey, serialized)) {
        reasonOut = "directconnect durable block missing/corrupt";
        return false;
    }
    if (serialized.empty() || serialized.size() > MAX_BLOCK_BYTES) {
        reasonOut = "directconnect durable block size invalid";
        return false;
    }
    if (sha256HexBytes(serialized) != state.blockRecordSha256) {
        reasonOut = "directconnect durable block record SHA-256 mismatch";
        return false;
    }

    try {
        Block block = Block::deserialize(serialized);
        if (block.blockHash != state.blockHash ||
            block.computeHash() != state.blockHash ||
            block.header.prevHash != state.parentHash ||
            static_cast<int>(block.height) != state.height ||
            block.header.bits != state.difficulty ||
            computeUndoBlockPayloadSha256(block) !=
                state.blockPayloadSha256) {
            reasonOut =
                "directconnect durable block identity/ancestry/fingerprint mismatch";
            return false;
        }
        blockOut = std::move(block);
        return true;
    } catch (const std::exception& e) {
        reasonOut =
            std::string("directconnect durable block deserialize failed: ") +
            e.what();
        return false;
    } catch (...) {
        reasonOut = "directconnect durable block deserialize failed";
        return false;
    }
}

static bool appendDirectConnectPendingToBatch(
    LevelDBStorage& storage,
    leveldb::WriteBatch& batch,
    const Block& block,
    std::string& reasonOut) {

    reasonOut.clear();
    if (block.height <= 1) return true;

    std::string raw;
    bool pendingFound = false;
    if (!storage.getRaw(
            DIRECT_CONNECT_PENDING_KEY, raw, pendingFound)) {
        reasonOut = "unable to inspect existing directconnect:pending";
        return false;
    }
    if (pendingFound) {
        reasonOut =
            "directconnect:pending already exists; refusing overlapping direct connect";
        return false;
    }

    bool reorgFound = false;
    if (!storage.getRaw(REORG_PENDING_KEY, raw, reorgFound)) {
        reasonOut = "unable to inspect reorg:pending before direct connect";
        return false;
    }
    if (reorgFound) {
        reasonOut =
            "reorg:pending exists; refusing overlapping direct-connect intent";
        return false;
    }

    const std::string serialized = block.serialize();
    if (serialized.empty() || serialized.size() > MAX_BLOCK_BYTES) {
        reasonOut = "direct-connect block serialization empty/oversized";
        return false;
    }

    const std::string marker =
        buildDirectConnectPendingPayload(block, serialized);
    if (marker.empty()) {
        reasonOut = "failed building directconnect:pending payload";
        return false;
    }

    // IMPORTANT: this helper is called only AFTER appendUndoJournalToBatch().
    // block:* and directconnect:pending therefore are publication evidence, not
    // reversible confirmed-state keys inside U4. Both are nevertheless durable
    // in the SAME Phase-5 WriteBatch as state + U4.
    batch.Put(
        "block:" + block.blockHash,
        storage.computeDataChecksum(serialized) + "|" + serialized);
    batch.Put(
        DIRECT_CONNECT_PENDING_KEY,
        storage.computeDataChecksum(marker) + "|" + marker);
    return true;
}


// authenticated U4 journal reader for a single
// active-tip disconnect. This reader never mutates state; it requires the
// current database to match the journal's exact POST-state before exposing
// PRE-images to rollbackBlock(). Multi-block reorg remains disabled.
struct UndoDisconnectEntry {
    std::string key;
    bool existed{false};
    std::string oldRaw;
};

static bool hexToRawBytesExact(
    const std::string& hex,
    std::string& raw) {

    raw.clear();
    if (!isEvenHexString(hex)) return false;

    auto nibble = [](unsigned char c) -> int {
        if (c >= '0' && c <= '9') return static_cast<int>(c - '0');
        if (c >= 'a' && c <= 'f') return 10 + static_cast<int>(c - 'a');
        if (c >= 'A' && c <= 'F') return 10 + static_cast<int>(c - 'A');
        return -1;
    };

    raw.resize(hex.size() / 2);
    for (size_t i = 0; i < raw.size(); ++i) {
        const int hi = nibble(static_cast<unsigned char>(hex[2 * i]));
        const int lo = nibble(static_cast<unsigned char>(hex[2 * i + 1]));
        if (hi < 0 || lo < 0) {
            raw.clear();
            return false;
        }
        raw[i] = static_cast<char>((hi << 4) | lo);
    }
    return true;
}


//================================================================================
// TRU CORE RECOVERY CR-01B v1 - INCIDENT-SPECIFIC HEIGHT-355 U4 RECOVERY
//================================================================================
struct CR01BLegacyUndoEntry {
    std::string key;
    bool existed{false};
    std::string oldRaw;
    std::string postOp;
    std::string postRawSha256;
};

struct CR01BLegacyUndoJournal {
    std::vector<CR01BLegacyUndoEntry> entries;
    std::string blockPayloadSha256;
    std::string spentInputOldRaw;
    bool sawAnchorChange{false};
    bool sawOrphanCoinbase{false};
    bool sawAnchorSpentInput{false};
    bool sawAnchorAddressIndex{false};
    bool durableBlockFound{false};
};

struct CR01BRecoveryMarkerState {
    std::string phase;
    std::string exactPayload;
};

static bool cr01bRecoveryArmed() {
    const char* value = std::getenv(CR01B_RECOVERY_ENV);
    return value != nullptr &&
           std::string(value) == CR01B_RECOVERY_MAGIC;
}

static std::string cr01bExpectedHashAtHeight(int height) {
    switch (height) {
        case 354: return CR01B_PARENT_354;
        case 355: return CR01B_ACTIVE_355;
        case 356: return CR01B_ACTIVE_356;
        case 357: return CR01B_ACTIVE_357;
        default: return {};
    }
}

static std::string cr01bExpectedParentAtHeight(int height) {
    switch (height) {
        case 355: return CR01B_PARENT_354;
        case 356: return CR01B_ACTIVE_355;
        case 357: return CR01B_ACTIVE_356;
        default: return {};
    }
}

static std::string cr01bExpectedCoinbaseAtHeight(int height) {
    switch (height) {
        case 355: return CR01B_COINBASE_355;
        case 356: return CR01B_COINBASE_356;
        case 357: return CR01B_COINBASE_357;
        default: return {};
    }
}

static std::string cr01bBuildRecoveryMarkerPayload(const std::string& phase) {
    if (phase != CR01B_PHASE_PREPARED &&
        phase != CR01B_PHASE_ORPHAN_CLEANED) {
        return {};
    }

    nlohmann::json marker = nlohmann::json::object();
    marker["version"] = CR01B_RECOVERY_VERSION;
    marker["phase"] = phase;
    marker["incident"] = "PRE_CR01A_HEIGHT355_PHASE5_WITHOUT_PUBLICATION";
    marker["orphanBlockHash"] = CR01B_ORPHAN_355;
    marker["parentHash"] = CR01B_PARENT_354;
    marker["expectedActive355"] = CR01B_ACTIVE_355;
    marker["expectedActive356"] = CR01B_ACTIVE_356;
    marker["expectedActive357"] = CR01B_ACTIVE_357;
    marker["anchorTxid"] = CR01B_ANCHOR_TXID;

    const std::string payload = marker.dump();
    if (payload.empty() || payload.size() > CR01B_MAX_MARKER_BYTES) {
        return {};
    }
    return payload;
}

static bool cr01bReadRecoveryMarker(
    const LevelDBStorage& storage,
    CR01BRecoveryMarkerState& stateOut,
    bool& foundOut,
    std::string& reasonOut) {

    stateOut = CR01BRecoveryMarkerState{};
    foundOut = false;
    reasonOut.clear();

    std::string raw;
    bool found = false;
    if (!storage.getRaw(CR01B_RECOVERY_KEY, raw, found)) {
        reasonOut = "unable to inspect CR-01B recovery marker";
        return false;
    }
    if (!found) return true;
    foundOut = true;

    if (raw.size() > CR01B_MAX_MARKER_BYTES + 65ULL) {
        reasonOut = "CR-01B recovery marker raw size exceeds bound";
        return false;
    }

    std::string payload;
    if (!storage.getWithDataChecksum(CR01B_RECOVERY_KEY, payload)) {
        reasonOut = "CR-01B recovery marker checksum/authentication failed";
        return false;
    }

    try {
        const nlohmann::json marker = nlohmann::json::parse(payload);
        if (!marker.is_object()) {
            reasonOut = "CR-01B recovery marker root is not object";
            return false;
        }

        auto requireExactString = [&](const char* key, const char* expected) -> bool {
            if (!marker.contains(key) || !marker[key].is_string() ||
                marker[key].get<std::string>() != expected) {
                reasonOut = std::string("CR-01B recovery marker mismatch field=") + key;
                return false;
            }
            return true;
        };

        if (!requireExactString("version", CR01B_RECOVERY_VERSION) ||
            !requireExactString(
                "incident", "PRE_CR01A_HEIGHT355_PHASE5_WITHOUT_PUBLICATION") ||
            !requireExactString("orphanBlockHash", CR01B_ORPHAN_355) ||
            !requireExactString("parentHash", CR01B_PARENT_354) ||
            !requireExactString("expectedActive355", CR01B_ACTIVE_355) ||
            !requireExactString("expectedActive356", CR01B_ACTIVE_356) ||
            !requireExactString("expectedActive357", CR01B_ACTIVE_357) ||
            !requireExactString("anchorTxid", CR01B_ANCHOR_TXID)) {
            return false;
        }

        if (!marker.contains("phase") || !marker["phase"].is_string()) {
            reasonOut = "CR-01B recovery marker phase missing";
            return false;
        }
        stateOut.phase = marker["phase"].get<std::string>();
        if (stateOut.phase != CR01B_PHASE_PREPARED &&
            stateOut.phase != CR01B_PHASE_ORPHAN_CLEANED) {
            reasonOut = "CR-01B recovery marker phase unsupported";
            return false;
        }

        stateOut.exactPayload = payload;
        return true;
    } catch (const std::exception& e) {
        reasonOut = std::string("CR-01B recovery marker parse failure: ") + e.what();
        return false;
    } catch (...) {
        reasonOut = "CR-01B recovery marker parse failure";
        return false;
    }
}

static bool cr01bPutRecoveryMarker(
    LevelDBStorage& storage,
    const std::string& phase,
    std::string& reasonOut) {

    reasonOut.clear();
    const std::string payload = cr01bBuildRecoveryMarkerPayload(phase);
    if (payload.empty()) {
        reasonOut = "failed building CR-01B recovery marker";
        return false;
    }

    leveldb::WriteBatch batch;
    batch.Put(
        CR01B_RECOVERY_KEY,
        storage.computeDataChecksum(payload) + "|" + payload);
    if (!storage.putBatch(batch, true)) {
        reasonOut = "failed synchronously persisting CR-01B recovery marker";
        return false;
    }

    CR01BRecoveryMarkerState check;
    bool found = false;
    if (!cr01bReadRecoveryMarker(storage, check, found, reasonOut) ||
        !found || check.phase != phase) {
        if (reasonOut.empty()) {
            reasonOut = "CR-01B recovery marker read-after-write mismatch";
        }
        return false;
    }
    return true;
}

static bool cr01bLoadLegacyOrphanJournal(
    const LevelDBStorage& storage,
    CR01BLegacyUndoJournal& out,
    bool requireExactPostState,
    std::string& reasonOut) {

    out = CR01BLegacyUndoJournal{};
    reasonOut.clear();

    const std::string undoKey =
        std::string(UNDO_KEY_PREFIX) + CR01B_ORPHAN_355;

    std::string rawJournal;
    bool found = false;
    if (!storage.getRaw(undoKey, rawJournal, found)) {
        reasonOut = "unable to inspect legacy orphan U4";
        return false;
    }
    if (!found) {
        reasonOut = "legacy orphan U4 is absent";
        return false;
    }
    if (rawJournal.size() > CR01B_MAX_LEGACY_U4_BYTES + 65ULL) {
        reasonOut = "legacy orphan U4 exceeds hard size bound";
        return false;
    }

    std::string payload;
    if (!storage.getWithDataChecksum(undoKey, payload)) {
        reasonOut = "legacy orphan U4 checksum/authentication failed";
        return false;
    }
    if (payload.empty() || payload.size() > CR01B_MAX_LEGACY_U4_BYTES) {
        reasonOut = "legacy orphan U4 payload size invalid";
        return false;
    }

    try {
        const nlohmann::json journal = nlohmann::json::parse(payload);
        if (!journal.is_object()) {
            throw std::runtime_error("legacy U4 root not object");
        }
        if (!journal.contains("version") || !journal["version"].is_string() ||
            journal["version"].get<std::string>() != UNDO_RULES_VERSION) {
            throw std::runtime_error("legacy U4 version mismatch");
        }
        if (!journal.contains("blockHash") || !journal["blockHash"].is_string() ||
            journal["blockHash"].get<std::string>() != CR01B_ORPHAN_355) {
            throw std::runtime_error("legacy U4 orphan blockHash mismatch");
        }
        if (!journal.contains("parentHash") || !journal["parentHash"].is_string() ||
            journal["parentHash"].get<std::string>() != CR01B_PARENT_354) {
            throw std::runtime_error("legacy U4 parentHash mismatch");
        }
        if (!journal.contains("height") || !journal["height"].is_number_integer() ||
            journal["height"].get<uint64_t>() != 355ULL) {
            throw std::runtime_error("legacy U4 height mismatch");
        }
        if (!journal.contains("blockPayloadSha256") ||
            !journal["blockPayloadSha256"].is_string()) {
            throw std::runtime_error("legacy U4 block fingerprint missing");
        }
        out.blockPayloadSha256 =
            journal["blockPayloadSha256"].get<std::string>();
        if (!cr01aIsLowerHex64(out.blockPayloadSha256)) {
            throw std::runtime_error("legacy U4 block fingerprint encoding invalid");
        }
        if (!journal.contains("entries") || !journal["entries"].is_array() ||
            !journal.contains("entryCount") ||
            !journal["entryCount"].is_number_integer()) {
            throw std::runtime_error("legacy U4 entries/count missing");
        }

        const uint64_t entryCount = journal["entryCount"].get<uint64_t>();
        if (entryCount == 0 ||
            entryCount != journal["entries"].size() ||
            entryCount > CR01B_MAX_LEGACY_U4_ENTRIES) {
            throw std::runtime_error("legacy U4 entryCount invalid/out of bound");
        }

        const std::string anchorChangeKey =
            "utxo:" + std::string(CR01B_ANCHOR_TXID) + ":" +
            std::to_string(CR01B_ANCHOR_CHANGE_VOUT);
        const std::string orphanCoinbaseKey =
            "utxo:" + std::string(CR01B_ORPHAN_COINBASE) + ":0";
        const std::string spentInputKey =
            "utxo:" + std::string(CR01B_ANCHOR_SPENT_TXID) + ":" +
            std::to_string(CR01B_ANCHOR_SPENT_VOUT);
        const std::string anchorAddressIndexKey =
            "address:TPPT2DWP45oZ5ivHVZ8MXzoKEAJtYt5kmh:tx:" +
            std::string(CR01B_ANCHOR_TXID);

        std::unordered_set<std::string> seenKeys;
        out.entries.reserve(static_cast<size_t>(entryCount));

        for (const auto& item : journal["entries"]) {
            if (!item.is_object() ||
                !item.contains("key") || !item["key"].is_string() ||
                !item.contains("existed") || !item["existed"].is_boolean() ||
                !item.contains("postOp") || !item["postOp"].is_string()) {
                throw std::runtime_error("legacy U4 entry structure invalid");
            }

            CR01BLegacyUndoEntry entry;
            entry.key = item["key"].get<std::string>();
            entry.existed = item["existed"].get<bool>();
            entry.postOp = item["postOp"].get<std::string>();

            if (entry.key.empty() || entry.key == undoKey ||
                !seenKeys.insert(entry.key).second) {
                throw std::runtime_error("legacy U4 entry key invalid/duplicate");
            }
            if (entry.postOp != "put" && entry.postOp != "delete") {
                throw std::runtime_error("legacy U4 postOp invalid");
            }

            if (entry.existed) {
                if (!item.contains("oldRawHex") || !item["oldRawHex"].is_string() ||
                    !hexToRawBytesExact(item["oldRawHex"].get<std::string>(), entry.oldRaw)) {
                    throw std::runtime_error("legacy U4 oldRawHex invalid");
                }
            } else if (item.contains("oldRawHex")) {
                throw std::runtime_error("legacy U4 absent pre-image has oldRawHex");
            }

            if (entry.postOp == "put") {
                if (!item.contains("postRawSha256") ||
                    !item["postRawSha256"].is_string()) {
                    throw std::runtime_error("legacy U4 postRawSha256 missing");
                }
                entry.postRawSha256 = item["postRawSha256"].get<std::string>();
                if (!cr01aIsLowerHex64(entry.postRawSha256)) {
                    throw std::runtime_error("legacy U4 postRawSha256 invalid");
                }
            } else if (item.contains("postRawSha256")) {
                throw std::runtime_error("legacy U4 delete entry has postRawSha256");
            }

            if (entry.key == anchorChangeKey) {
                if (entry.existed || entry.postOp != "put") {
                    throw std::runtime_error("legacy U4 anchor-change sentinel semantics mismatch");
                }
                out.sawAnchorChange = true;
            }
            if (entry.key == orphanCoinbaseKey) {
                if (entry.existed || entry.postOp != "put") {
                    throw std::runtime_error("legacy U4 orphan-coinbase sentinel semantics mismatch");
                }
                out.sawOrphanCoinbase = true;
            }
            if (entry.key == spentInputKey) {
                if (!entry.existed || entry.postOp != "delete" || entry.oldRaw.empty()) {
                    throw std::runtime_error("legacy U4 spent-input sentinel semantics mismatch");
                }
                out.sawAnchorSpentInput = true;
                out.spentInputOldRaw = entry.oldRaw;
            }
            if (entry.key == anchorAddressIndexKey) {
                if (entry.existed || entry.postOp != "put") {
                    throw std::runtime_error("legacy U4 anchor address-index sentinel mismatch");
                }
                out.sawAnchorAddressIndex = true;
            }

            if (requireExactPostState) {
                std::string currentRaw;
                bool currentFound = false;
                if (!storage.getRaw(entry.key, currentRaw, currentFound)) {
                    throw std::runtime_error("legacy U4 failed reading live POST-state key");
                }
                const bool matchesPost =
                    entry.postOp == "put"
                        ? (currentFound &&
                           sha256HexBytes(currentRaw) == entry.postRawSha256)
                        : !currentFound;
                if (!matchesPost) {
                    throw std::runtime_error(
                        "legacy U4 live DB is not exact POST-state for key=" +
                        entry.key);
                }
            }

            out.entries.push_back(std::move(entry));
        }

        if (!out.sawAnchorChange ||
            !out.sawOrphanCoinbase ||
            !out.sawAnchorSpentInput ||
            !out.sawAnchorAddressIndex) {
            throw std::runtime_error("legacy U4 fixed incident sentinels incomplete");
        }

        // If pre-CR-01A block bytes happen to survive, use them as an additional
        // decisive witness. Their absence is expected for this exact incident
        // because the stall occurred before saveChainState() persisted block:*.
        std::string rawBlock;
        bool blockFound = false;
        if (!storage.getRaw(
                "block:" + std::string(CR01B_ORPHAN_355),
                rawBlock,
                blockFound)) {
            throw std::runtime_error("failed inspecting optional orphan block record");
        }
        out.durableBlockFound = blockFound;
        if (blockFound) {
            std::string serialized;
            if (!storage.getWithDataChecksum(
                    "block:" + std::string(CR01B_ORPHAN_355),
                    serialized)) {
                throw std::runtime_error("optional orphan block record checksum failed");
            }
            if (serialized.empty() || serialized.size() > MAX_BLOCK_BYTES) {
                throw std::runtime_error("optional orphan block size invalid");
            }
            const Block orphan = Block::deserialize(serialized);
            if (orphan.blockHash != CR01B_ORPHAN_355 ||
                orphan.computeHash() != CR01B_ORPHAN_355 ||
                orphan.header.prevHash != CR01B_PARENT_354 ||
                orphan.height != 355 ||
                computeMerkleRoot(orphan.transactions) != orphan.header.merkleRoot ||
                computeUndoBlockPayloadSha256(orphan) != out.blockPayloadSha256) {
                throw std::runtime_error("optional orphan block identity/fingerprint mismatch");
            }
            bool anchorFound = false;
            bool coinbaseFound = false;
            for (const auto& tx : orphan.transactions) {
                anchorFound = anchorFound || tx.txid == CR01B_ANCHOR_TXID;
                coinbaseFound = coinbaseFound || tx.txid == CR01B_ORPHAN_COINBASE;
            }
            if (!anchorFound || !coinbaseFound) {
                throw std::runtime_error("optional orphan block lacks fixed incident txids");
            }
        }

        return true;
    } catch (const std::exception& e) {
        out = CR01BLegacyUndoJournal{};
        reasonOut = std::string("legacy orphan U4 verification failed: ") + e.what();
        return false;
    } catch (...) {
        out = CR01BLegacyUndoJournal{};
        reasonOut = "legacy orphan U4 verification failed";
        return false;
    }
}

static bool cr01bKeyExists(
    const LevelDBStorage& storage,
    const std::string& key,
    bool& foundOut,
    std::string& reasonOut) {

    std::string raw;
    if (!storage.getRaw(key, raw, foundOut)) {
        reasonOut = "raw LevelDB read failed for key=" + key;
        return false;
    }
    return true;
}

static bool readUndoJournalForDisconnect(
    LevelDBStorage& storage,
    const Block& block,
    std::vector<UndoDisconnectEntry>& entriesOut,
    std::vector<std::string>& affectedAddressesOut,
    std::string* fingerprintCache = nullptr) {

    entriesOut.clear();
    affectedAddressesOut.clear();

    // First require the exact U4 live POST-state witness. A missing journal,
    // exact PRE-state, or mixed/corrupt state is not disconnectable.
    const UndoJournalProbe initialProbe = probeExistingUndoJournal(
        storage,
        block,
        &affectedAddressesOut,
        fingerprintCache);

    if (initialProbe != UndoJournalProbe::RecoverablePostState) {
        const char* reason =
            initialProbe == UndoJournalProbe::Absent ? "journal absent" :
            initialProbe == UndoJournalProbe::ReapplyPreState ? "state already at PRE-image" :
            "journal/state witness invalid";
        Logger::log(
            "[Patch08B.2] REJECT disconnect journal for block " +
            block.blockHash + ": " + reason);
        return false;
    }

    const std::string undoKey =
        std::string(UNDO_KEY_PREFIX) + block.blockHash;

    std::string payload;
    if (!storage.getWithDataChecksum(undoKey, payload)) {
        Logger::log(
            "[Patch08B.2] ERROR: checksum-valid undo journal disappeared before disconnect read for " +
            block.blockHash);
        return false;
    }

    try {
        const nlohmann::json journal = nlohmann::json::parse(payload);
        if (!journal.is_object()) {
            throw std::runtime_error("journal root is not an object");
        }
        if (!journal.contains("version") ||
            !journal["version"].is_string() ||
            journal["version"].get<std::string>() != UNDO_RULES_VERSION) {
            throw std::runtime_error("journal version mismatch");
        }
        if (!journal.contains("blockHash") ||
            !journal["blockHash"].is_string() ||
            journal["blockHash"].get<std::string>() != block.blockHash) {
            throw std::runtime_error("journal blockHash mismatch");
        }
        if (!journal.contains("parentHash") ||
            !journal["parentHash"].is_string() ||
            journal["parentHash"].get<std::string>() != block.header.prevHash) {
            throw std::runtime_error("journal parentHash mismatch");
        }
        if (!journal.contains("height") ||
            !journal["height"].is_number_integer() ||
            journal["height"].get<uint64_t>() != static_cast<uint64_t>(block.height)) {
            throw std::runtime_error("journal height mismatch");
        }
        if (!journal.contains("blockPayloadSha256") ||
            !journal["blockPayloadSha256"].is_string()) {
            throw std::runtime_error("journal block fingerprint missing");
        }

        std::string computedFingerprint;
        if (fingerprintCache && !fingerprintCache->empty()) {
            computedFingerprint = *fingerprintCache;
        } else {
            computedFingerprint = computeUndoBlockPayloadSha256(block);
            if (fingerprintCache) *fingerprintCache = computedFingerprint;
        }
        if (journal["blockPayloadSha256"].get<std::string>() != computedFingerprint) {
            throw std::runtime_error("journal block fingerprint mismatch");
        }

        if (!journal.contains("entries") || !journal["entries"].is_array() ||
            !journal.contains("entryCount") ||
            !journal["entryCount"].is_number_integer()) {
            throw std::runtime_error("journal entries/count missing");
        }

        const uint64_t entryCount = journal["entryCount"].get<uint64_t>();
        if (entryCount == 0 || entryCount != journal["entries"].size()) {
            throw std::runtime_error("journal entryCount mismatch/empty");
        }

        std::unordered_set<std::string> seenKeys;
        entriesOut.reserve(static_cast<size_t>(entryCount));

        for (const auto& entry : journal["entries"]) {
            if (!entry.is_object() ||
                !entry.contains("key") || !entry["key"].is_string() ||
                !entry.contains("existed") || !entry["existed"].is_boolean() ||
                !entry.contains("postOp") || !entry["postOp"].is_string()) {
                throw std::runtime_error("journal entry structure invalid");
            }

            const std::string key = entry["key"].get<std::string>();
            const bool existed = entry["existed"].get<bool>();
            const std::string postOp = entry["postOp"].get<std::string>();

            if (key.empty() || key == undoKey || !seenKeys.insert(key).second) {
                throw std::runtime_error("journal entry key invalid/duplicate");
            }
            if (postOp != "put" && postOp != "delete") {
                throw std::runtime_error("journal postOp invalid");
            }
            if (postOp == "put") {
                if (!entry.contains("postRawSha256") ||
                    !entry["postRawSha256"].is_string() ||
                    entry["postRawSha256"].get<std::string>().size() != 64 ||
                    !isEvenHexString(entry["postRawSha256"].get<std::string>())) {
                    throw std::runtime_error("journal postRawSha256 invalid");
                }
            } else if (entry.contains("postRawSha256")) {
                throw std::runtime_error("delete entry unexpectedly has postRawSha256");
            }

            UndoDisconnectEntry decoded;
            decoded.key = key;
            decoded.existed = existed;

            if (existed) {
                if (!entry.contains("oldRawHex") ||
                    !entry["oldRawHex"].is_string() ||
                    !hexToRawBytesExact(
                        entry["oldRawHex"].get<std::string>(),
                        decoded.oldRaw)) {
                    throw std::runtime_error("journal oldRawHex invalid");
                }
            } else if (entry.contains("oldRawHex")) {
                throw std::runtime_error("absent PRE-image unexpectedly has oldRawHex");
            }

            entriesOut.push_back(std::move(decoded));
        }

        // Fail closed if anything changed while the journal was being decoded.
        // This second exact-POST probe also rechecks every postRawSha256 witness.
        std::vector<std::string> verifiedAddresses;
        if (probeExistingUndoJournal(
                storage,
                block,
                &verifiedAddresses,
                fingerprintCache) != UndoJournalProbe::RecoverablePostState) {
            throw std::runtime_error(
                "journal/live POST-state changed during disconnect preparation");
        }
        affectedAddressesOut = std::move(verifiedAddresses);

        Logger::log(
            "[Patch08B.2] Loaded authenticated undo journal block=" +
            block.blockHash + " entries=" + std::to_string(entriesOut.size()));
        return true;
    } catch (const std::exception& e) {
        entriesOut.clear();
        affectedAddressesOut.clear();
        Logger::log(
            "[Patch08B.2] ERROR: safe undo journal read failed for block=" +
            block.blockHash + ": " + e.what());
        return false;
    }
}

static bool appendUndoJournalToBatch(
    LevelDBStorage& storage,
    const Block& block,
    leveldb::WriteBatch& stateBatch) {

    if (block.height <= 1) {
        return true; // Genesis is not a disconnect candidate.
    }

    class FinalOperationCollector final
        : public leveldb::WriteBatch::Handler {
    public:
        // key -> {final operation, SHA-256 of exact final raw value for Put}.
        // Hash the Slice in-place so the collector does not retain another full
        // copy of every final LevelDB value while the WriteBatch is already live.
        std::map<std::string, std::pair<std::string, std::string>> finalOperation;

        void Put(
            const leveldb::Slice& key,
            const leveldb::Slice& value) override {
            finalOperation[key.ToString()] = {
                "put",
                sha256HexRaw(value.data(), value.size())};
        }

        void Delete(const leveldb::Slice& key) override {
            finalOperation[key.ToString()] = {"delete", std::string()};
        }
    } collector;

    const leveldb::Status iterateStatus =
        stateBatch.Iterate(&collector);
    if (!iterateStatus.ok()) {
        Logger::log(
            "[Patch08B.1v4] ERROR: unable to inspect state batch: " +
            iterateStatus.ToString());
        return false;
    }

    const std::string undoKey =
        std::string(UNDO_KEY_PREFIX) + block.blockHash;

    if (collector.finalOperation.count(undoKey) != 0) {
        Logger::log(
            "[Patch08B.1v4] ERROR: state batch touched its own undo key");
        return false;
    }

    std::string existingUndoRaw;
    bool undoAlreadyExists = false;
    if (!storage.getRaw(
            undoKey,
            existingUndoRaw,
            undoAlreadyExists)) {
        Logger::log(
            "[Patch08B.1v4] ERROR: failed checking existing undo journal");
        return false;
    }

    if (undoAlreadyExists) {
        // A journal may survive while the state is restored to its exact
        // pre-block image. Permit replacement ONLY after the U4 journal proves
        // the live DB is exactly that PRE-state. The replacement journal and
        // re-applied state then commit atomically in this same WriteBatch.
        const UndoJournalProbe existingState =
            probeExistingUndoJournal(storage, block);
        if (existingState != UndoJournalProbe::ReapplyPreState) {
            Logger::log(
                "[Patch08B.1v4] ERROR: duplicate undo journal reached apply path without exact PRE-state proof for block " +
                block.blockHash);
            return false;
        }

        Logger::log(
            "[Patch08B.1v4] SAFE-REAPPLY: replacing stale journal atomically with block state for " +
            block.blockHash);
    }

    nlohmann::json journal = nlohmann::json::object();
    journal["version"] = UNDO_RULES_VERSION;
    journal["blockHash"] = block.blockHash;
    journal["parentHash"] = block.header.prevHash;
    journal["height"] = block.height;
    journal["blockPayloadSha256"] = computeUndoBlockPayloadSha256(block);
    journal["entries"] = nlohmann::json::array();

    for (const auto& [key, finalState] : collector.finalOperation) {
        const std::string& operation = finalState.first;
        const std::string& finalRawSha256 = finalState.second;

        std::string oldRaw;
        bool existed = false;

        if (!storage.getRaw(key, oldRaw, existed)) {
            Logger::log(
                "[Patch08B.1v4] ERROR: failed reading pre-image for key " +
                key);
            return false;
        }

        nlohmann::json entry = nlohmann::json::object();
        entry["key"] = key;
        entry["existed"] = existed;
        entry["postOp"] = operation;

        if (existed) {
            entry["oldRawHex"] = rawBytesToHex(oldRaw);
        }
        if (operation == "put") {
            // Store only the digest of the final raw value; recovery can prove
            // the live DB still has the exact post-block bytes without doubling
            // journal storage by embedding the full post-image.
            entry["postRawSha256"] = finalRawSha256;
        }

        journal["entries"].push_back(std::move(entry));
    }

    journal["entryCount"] =
        static_cast<uint64_t>(collector.finalOperation.size());

    const std::string payload = journal.dump();
    stateBatch.Put(
        undoKey,
        storage.computeDataChecksum(payload) + "|" + payload);

    Logger::log(
        "[Patch08B.1v4] Prepared durable undo journal block=" +
        block.blockHash +
        " height=" + std::to_string(block.height) +
        " entries=" +
        std::to_string(collector.finalOperation.size()) +
        " bytes=" + std::to_string(payload.size()));

    return true;
}

static bool isValidSideSourceKey(const std::string& sourceKey) {
    if (sourceKey.empty() ||
        sourceKey.size() > tru_limits::MAX_SIDE_SOURCE_KEY_BYTES) {
        return false;
    }

    for (unsigned char c : sourceKey) {
        if (!(std::isalnum(c) || c == '.' || c == ':' || c == '_' || c == '-')) {
            return false;
        }
    }
    return true;
}

static bool isUntrustedSideSource(const std::string& sourceKey) {
    return sourceKey != SIDE_LOCAL_SOURCE;
}
static constexpr size_t BLOCK_ASSEMBLY_BYTES = tru_limits::BLOCK_ASSEMBLY_BYTES;
// FIX(overflow): max spendable value guard. 21,000,000 * 1e8 TRU atoms = TRU monetary cap.
static constexpr uint64_t MAX_MONEY = tru_limits::MAX_MONEY;  // shared invariant
static const uint64_t MAX_TARGET_64BIT = 0x00000000FFFF0000ULL;  // legacy telemetry only
static constexpr uint32_t TRU_POW_LIMIT_BITS = 0x1e00ffffU;

// strict compact-target + chainwork helpers.
static bool compactToTarget256Strict(uint32_t bits, ChainWork256& targetOut);
static uint32_t target256ToCompact(const ChainWork256& target);
static const ChainWork256& truPowLimitTarget256();
static ChainWork256 computeBlockWork256(uint32_t bits);
static bool addChainWorkChecked(
    const ChainWork256& parentWork,
    const ChainWork256& blockWork,
    ChainWork256& out);
static void target256ToLE32(const ChainWork256& target, unsigned char out[32]);

// coinbase height commitment.
// Accepted current miner encodings:
//   height:<H>|...
//   GPUHeight:<H>
//   TRU:<H>|CPU:...
//   TRU:<H>|AI-GPU...:
// Genesis is exempt because its historical script begins "GENESIS:".
static bool extractCommittedCoinbaseHeight(
    const Transaction& coinbase,
    uint64_t& heightOut)
{
    heightOut = 0;
    if (!coinbase.isCoinbase || coinbase.vin.size() != 1) return false;

    const std::string script(
        coinbase.vin[0].scriptSig.begin(),
        coinbase.vin[0].scriptSig.end());

    const char* prefixes[] = {"height:", "GPUHeight:", "TRU:"};
    for (const char* prefix : prefixes) {
        const std::string p(prefix);
        if (script.rfind(p, 0) != 0) continue;

        std::size_t pos = p.size();
        const std::size_t begin = pos;
        while (pos < script.size() &&
               std::isdigit(static_cast<unsigned char>(script[pos]))) {
            ++pos;
        }
        if (pos == begin) return false;
        if (pos < script.size() && script[pos] != '|') return false;

        try {
            const std::string digits = script.substr(begin, pos - begin);
            std::size_t consumed = 0;
            const unsigned long long parsed =
                std::stoull(digits, &consumed, 10);
            if (consumed != digits.size()) return false;
            heightOut = static_cast<uint64_t>(parsed);
            return true;
        } catch (...) {
            return false;
        }
    }
    return false;
}

// cheap structural transaction limits before BIP30
// lookups, txid hashing, or script execution. `blockInputs`/`blockOutputs` are
// cumulative for the candidate block.
static bool validateTxResourceShape(
    const Transaction& tx,
    size_t& blockInputs,
    size_t& blockOutputs,
    size_t& blockStateInitBytes,
    bool allowStatefulCalls,
    const char* logTag)
{
    if (tx.vin.empty() || tx.vout.empty()) {
        Logger::log(std::string(logTag) + " ERROR: transaction has empty inputs/outputs");
        return false;
    }
    if (tx.vin.size() > tru_limits::MAX_TX_INPUTS ||
        tx.vout.size() > tru_limits::MAX_TX_OUTPUTS) {
        Logger::log(std::string(logTag) + " ERROR: transaction input/output limit exceeded");
        return false;
    }
    if (tx.vin.size() > tru_limits::MAX_BLOCK_INPUTS - blockInputs ||
        tx.vout.size() > tru_limits::MAX_BLOCK_OUTPUTS - blockOutputs) {
        Logger::log(std::string(logTag) + " ERROR: block input/output budget exceeded");
        return false;
    }

    size_t txBytes = 0;
    try {
        txBytes = tx.serializeBinary().size();
    } catch (const std::exception& e) {
        Logger::log(std::string(logTag) + " ERROR: transaction serialization failed: " + e.what());
        return false;
    } catch (...) {
        Logger::log(std::string(logTag) + " ERROR: transaction serialization failed");
        return false;
    }
    if (txBytes == 0 || txBytes > tru_limits::MAX_CONSENSUS_TX_BYTES) {
        Logger::log(std::string(logTag) + " ERROR: transaction byte limit exceeded");
        return false;
    }

    for (const auto& vin : tx.vin) {
        if (vin.scriptSig.size() > tru_limits::MAX_SCRIPT_BYTES) {
            Logger::log(std::string(logTag) + " ERROR: scriptSig byte limit exceeded");
            return false;
        }
        if (!tx.isCoinbase &&
            (vin.txid.size() != 64 || !isValidHex(vin.txid) || vin.vout < 0)) {
            Logger::log(std::string(logTag) + " ERROR: malformed input outpoint");
            return false;
        }
    }
    for (const auto& vout : tx.vout) {
        if (vout.scriptPubKey.empty() ||
            (vout.scriptPubKey.size() & 1U) != 0 ||
            vout.scriptPubKey.size() / 2 > tru_limits::MAX_SCRIPT_BYTES ||
            !isValidHex(vout.scriptPubKey)) {
            Logger::log(std::string(logTag) + " ERROR: malformed/oversized output script");
            return false;
        }

    }

    // transaction-level activated stateful creation validation.
    // Canonical f751 anchors are classified by their strict TRUSTATE schema:
    // one-entry K/V V1 or canonical Voting V1. Other families remain closed.
    const auto stateCreation =
        tru_contract_call::ValidateStatefulCreationShape(tx);
    if (!stateCreation.valid) {
        Logger::log(
            std::string(logTag) +
            " ERROR: invalid stateful creation shape: " +
            stateCreation.reason);
        return false;
    }
    if (stateCreation.hasCallCandidate && !allowStatefulCalls) {
        Logger::log(
            std::string(logTag) +
            " ERROR: stateful continuation calls are disabled on side/index-only validation");
        return false;
    }
    if (stateCreation.hasCreation) {
        if (blockStateInitBytes >
                tru_contract_call::MAX_BLOCK_STATE_INIT_ACCOUNTED_BYTES ||
            stateCreation.accountedStateBytes >
                tru_contract_call::MAX_BLOCK_STATE_INIT_ACCOUNTED_BYTES -
                    blockStateInitBytes) {
            Logger::log(
                std::string(logTag) +
                " ERROR: block state-initialization byte budget exceeded");
            return false;
        }
        blockStateInitBytes += stateCreation.accountedStateBytes;
    }

    blockInputs += tx.vin.size();
    blockOutputs += tx.vout.size();
    return true;
}

static bool addScriptMetricsChecked(
    const ScriptResourceMetrics& a,
    const ScriptResourceMetrics& b,
    uint64_t& txOps,
    uint64_t& txSigOps,
    uint64_t& blockOps,
    uint64_t& blockSigOps)
{
    if (a.opCount > UINT64_MAX - b.opCount ||
        a.sigOpCost > UINT64_MAX - b.sigOpCost) return false;
    const uint64_t addOps = a.opCount + b.opCount;
    const uint64_t addSigOps = a.sigOpCost + b.sigOpCost;

    if (addOps > tru_limits::MAX_TX_SCRIPT_OPS - txOps ||
        addSigOps > tru_limits::MAX_TX_SIGOPS - txSigOps ||
        addOps > tru_limits::MAX_BLOCK_SCRIPT_OPS - blockOps ||
        addSigOps > tru_limits::MAX_BLOCK_SIGOPS - blockSigOps) {
        return false;
    }

    txOps += addOps;
    txSigOps += addSigOps;
    blockOps += addOps;
    blockSigOps += addSigOps;
    return true;
}

int Blockchain::getConnectedPeerCount() const {
    return node.getActivePeerCount();
}
//==================================================================================
//                              GET TRANSACTION
//==================================================================================
bool Blockchain::getTransaction(const std::string& txid, Transaction& tx) const {
    std::shared_lock<std::shared_mutex> lock(mtx);
    
    for (const auto& block : chain) {
        for (const auto& t : block.transactions) {
            if (t.txid == txid) {
                tx = t;
                return true;
            }
        }
    }
    return false;
}
//==================================================================================
//				GET BLOCK
//==================================================================================

Block Blockchain::getBlock(const std::string& hash) {
       auto it = blockIndex.find(hash);
       if (it != blockIndex.end()) {
           return it->second.block;
       }
       throw std::runtime_error("Block not found");
   }
//================================================================================
//                      Process Blocks
//================================================================================
void Blockchain::processBlocks() {
    Logger::log("[processBlocks] Thread started");
    
    while (!stopProcessing.load(std::memory_order_acquire)) {
        std::unique_lock<std::mutex> lock(queueMutex);
        // Wait with shorter timeout for more responsive shutdown
        bool gotSignal = queueCond.wait_for(lock, std::chrono::milliseconds(100), 
            [this] { 
                return !blockQueue.empty() || stopProcessing.load(std::memory_order_acquire); 
            });
        
        // Check shutdown flag FIRST before processing anything
        if (stopProcessing.load(std::memory_order_acquire)) {
            Logger::log("[processBlocks] Shutdown detected, breaking loop");
            break;
        }
        
        // Process blocks if available
        if (!blockQueue.empty()) {
            Block blk = blockQueue.front();
            blockQueue.pop();
            size_t remainingBlocks = blockQueue.size();
            lock.unlock();  // Release lock before processing
            
            Logger::log("[processBlocks] Processing block, " + std::to_string(remainingBlocks) + " blocks remaining in queue");
            
            // Final shutdown check before heavy processing
            if (stopProcessing.load(std::memory_order_acquire)) {
                Logger::log("[processBlocks] Shutdown detected before processing block, discarding");
                break;
            }
            
            try {
                // Use submitBlock for proper fork handling instead of direct addBlock
                if (!submitBlock(blk)) {
                    Logger::log("[processBlocks] Failed to submit block: " + blk.blockHash);
                }
            } catch (const std::exception& e) {
                Logger::log("[processBlocks] Error submitting block: " + std::string(e.what()));
            } catch (...) {
                Logger::log("[processBlocks] Unknown error submitting block");
            }
        }
    }
    
    // Clear any remaining blocks before exiting
    {
        std::lock_guard<std::mutex> lock(queueMutex);
        size_t remaining = blockQueue.size();
        if (remaining > 0) {
            Logger::log("[processBlocks] Clearing " + std::to_string(remaining) + " unprocessed blocks");
            while (!blockQueue.empty()) {
                blockQueue.pop();
            }
        }
    }
    
    Logger::log("[processBlocks] Thread exiting cleanly");
}
//==================================================================================
//                              STOP
//==================================================================================
void Blockchain::stop() {
    // Make shutdown idempotent - only run once.
    bool expected = false;
    if (!shutdownInitiated.compare_exchange_strong(expected, true)) {
        Logger::log("[Blockchain] Shutdown already initiated, skipping...");
        return;
    }

    Logger::log("[Blockchain] Starting shutdown sequence...");

    // shutdown is a lifetime barrier, not a best-effort
    // timeout. No Blockchain-owned worker may outlive stop().
    running_.store(false, std::memory_order_release);
    stopProcessing.store(true, std::memory_order_release);
    Logger::log("[Blockchain] Shutdown flags set: running_=false, stopProcessing=true");

    // Wake the condition variables ACTUALLY used by processBlocks() and
    // processQueue(). processBlocksCv is a legacy unused member and is not a
    // substitute for the file-scope queueCond used by processBlocks().
    Logger::log("[Blockchain] Waking block and transaction queue workers...");
    queueCond.notify_all();
    queueCond_.notify_all();
    acceptedTxRelay_.close();

    // blockQueue is owned by queueMutex at both producer and consumer sites.
    {
        std::lock_guard<std::mutex> lock(queueMutex);
        const size_t queueSize = blockQueue.size();
        while (!blockQueue.empty()) {
            blockQueue.pop();
        }
        if (queueSize > 0) {
            Logger::log(
                "[Blockchain] Cleared " + std::to_string(queueSize) +
                " pending blocks from queue");
        }
    }

    // Join Blockchain-owned workers deterministically. Detaching here would
    // permit them to access this object after shutdown/destruction continues.
    if (blockProcessor.joinable()) {
        Logger::log("[Blockchain] Waiting for processBlocks thread to terminate...");
        const auto start = std::chrono::steady_clock::now();
        blockProcessor.join();
        const auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - start).count();
        Logger::log(
            "[Blockchain] processBlocks thread terminated successfully after " +
            std::to_string(duration) + "ms");
    } else {
        Logger::log("[Blockchain] processBlocks thread was not joinable");
    }

    if (processorThread_.joinable()) {
        Logger::log("[Blockchain] Waiting for transaction processor thread to terminate...");
        const auto start = std::chrono::steady_clock::now();
        processorThread_.join();
        const auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::steady_clock::now() - start).count();
        Logger::log(
            "[Blockchain] transaction processor thread terminated successfully after " +
            std::to_string(duration) + "ms");
    } else {
        Logger::log("[Blockchain] transaction processor thread was not joinable");
    }

    if (acceptedTxRelayThread_.joinable()) acceptedTxRelayThread_.join();

    Logger::log("[Blockchain] Saving final chain state synchronously...");
    bool finalSaveOk = false;
    try {
        saveAllBlocksSync();
        finalSaveOk = true;
        Logger::log("[Blockchain] Chain state saved successfully");
    } catch (const std::exception& e) {
        Logger::log(
            "[Blockchain] ERROR saving final chain state: " +
            std::string(e.what()));
    }

    Logger::log("[Blockchain] ========== Shutdown Summary ==========");
    Logger::log("[Blockchain] Final chain height: " + std::to_string(bestTipHeight.load()));
    Logger::log("[Blockchain] Final best tip: " + bestTipHash);
    Logger::log("[Blockchain] Total blocks in memory: " + std::to_string(chain.size()));
    Logger::log("[Blockchain] Total blocks in index: " + std::to_string(blockIndex.size()));
    Logger::log(
        std::string("[Blockchain] Shutdown completed; durableSave=") +
        (finalSaveOk ? "PASS" : "FAIL"));
    Logger::log("[Blockchain] =====================================");
}

//================================================================================
//                      SYNC WITH PEERS
//================================================================================
void Blockchain::syncWithPeers(
    P2PNode& node,
    std::atomic<bool>& running,
    std::mutex* coutMutex,
    const std::function<void(const std::string&)>& statusCallback) {
    Logger::log("[MULTINODE-01B] Fork-aware sync thread starting");

    const auto publishStatus = [&](const std::string& status) {
        if (statusCallback) statusCallback(status);
    };

    const std::chrono::milliseconds responseTimeout(10000);
    const std::size_t batchSize = tru_limits::P2P_SYNC_BLOCK_REQUEST_BATCH;
    const int maxConsecutiveFailures = 5;
    int consecutiveFailures = 0;
    bool wasFullySynced = false;

    auto waitBriefly = [&](int milliseconds) {
        const int slices = std::max(1, milliseconds / 100);
        for (int i = 0; i < slices && running.load(std::memory_order_acquire); ++i) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    };

    auto requestPeerBlock = [&](const std::shared_ptr<PeerConnection>& peer,
                                uint64_t height,
                                Block& out) -> bool {
        try {
            auto future = peer->requestBlock(height);
            const auto status = future.wait_for(responseTimeout);
            if (status != std::future_status::ready) {
                peer->cancelBlockRequest(height);
                Logger::log(
                    "[MULTINODE-01B] Timeout requesting height " +
                    std::to_string(height) + " from " + peer->getIp());
                return false;
            }
            out = future.get();
            if (out.blockHash.empty() || out.height != height) {
                Logger::log(
                    "[MULTINODE-01B] Invalid peer block identity at height " +
                    std::to_string(height) + " from " + peer->getIp());
                return false;
            }
            if (out.computeHash() != out.blockHash) {
                Logger::log(
                    "[MULTINODE-01B] Peer block hash witness mismatch at height " +
                    std::to_string(height));
                return false;
            }
            return true;
        } catch (const std::exception& e) {
            Logger::log(
                "[MULTINODE-01B] Exception requesting height " +
                std::to_string(height) + ": " + e.what());
            return false;
        }
    };

    while (running.load(std::memory_order_acquire)) {
        try {
            auto peers = node.getPeersList();
            if (peers.empty()) {
                publishStatus("Waiting for peers...");
                if (coutMutex && !wasFullySynced) {
                    std::lock_guard<std::mutex> lock(*coutMutex);
                    std::cout << "\r[SYNC] Waiting for peers..." << std::flush;
                }
                waitBriefly(5000);
                continue;
            }

            // Ask every connected peer for height. Height chooses a download source
            // only; cumulative chainwork remains the sole reorganization authority.
            uint64_t highestPeerHeight = 0;
            std::shared_ptr<PeerConnection> bestPeer;
            for (const auto& peer : peers) {
                if (!running.load(std::memory_order_acquire)) goto exit_sync;
                peer->requestHeight();
                const auto start = std::chrono::steady_clock::now();
                while (std::chrono::steady_clock::now() - start < responseTimeout) {
                    if (!running.load(std::memory_order_acquire)) goto exit_sync;
                    const uint64_t peerHeight = peer->getPeerHeight();
                    if (peerHeight > 0) {
                        Logger::log(
                            "[MULTINODE-01B] Peer " + peer->getIp() + ":" +
                            std::to_string(peer->getPort()) + " height=" +
                            std::to_string(peerHeight));
                        if (!bestPeer || peerHeight > highestPeerHeight) {
                            highestPeerHeight = peerHeight;
                            bestPeer = peer;
                        }
                        break;
                    }
                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
                }
            }

            if (!bestPeer || highestPeerHeight == 0) {
                publishStatus("Connected peers have not reported usable heights");
                waitBriefly(3000);
                continue;
            }

            const uint64_t localHeight = static_cast<uint64_t>(getBestTipHeight());
            const uint64_t overlapHeight = std::min(localHeight, highestPeerHeight);
            uint64_t forkHeight = overlapHeight;
            bool diverged = false;

            // A height-only comparison is insufficient: equal-height competing
            // blocks are the common PoW race case. Compare exact block identity at
            // the overlap height and, if needed, walk backward to a common ancestor.
            if (overlapHeight > 0) {
                Block peerOverlap;
                if (!requestPeerBlock(bestPeer, overlapHeight, peerOverlap)) {
                    ++consecutiveFailures;
                    waitBriefly(2000);
                    continue;
                }

                const std::string localOverlapHash = getBlockHashByHeight(overlapHeight);
                if (localOverlapHash.empty()) {
                    Logger::log(
                        "[MULTINODE-01B] Local overlap hash unavailable at height " +
                        std::to_string(overlapHeight));
                    ++consecutiveFailures;
                    waitBriefly(2000);
                    continue;
                }

                if (peerOverlap.blockHash != localOverlapHash) {
                    diverged = true;
                    bool foundFork = false;
                    uint64_t probe = overlapHeight;
                    int walked = 0;

                    while (probe > 0 && walked <= MAX_SIDE_FORK_DEPTH) {
                        Block peerProbe;
                        if (!requestPeerBlock(bestPeer, probe, peerProbe)) break;
                        const std::string localHash = getBlockHashByHeight(probe);
                        if (!localHash.empty() && peerProbe.blockHash == localHash) {
                            forkHeight = probe;
                            foundFork = true;
                            break;
                        }
                        --probe;
                        ++walked;
                    }

                    if (!foundFork) {
                        Logger::log(
                            "[MULTINODE-01B] FAIL-CLOSED: no common ancestor within " +
                            std::to_string(MAX_SIDE_FORK_DEPTH) +
                            " blocks; no side activation attempted");
                        publishStatus("Fork exceeds bounded automatic-reorg discovery depth");
                        ++consecutiveFailures;
                        waitBriefly(5000);
                        continue;
                    }

                    Logger::log(
                        "[MULTINODE-01B] Divergence detected localHeight=" +
                        std::to_string(localHeight) + " peerHeight=" +
                        std::to_string(highestPeerHeight) + " forkHeight=" +
                        std::to_string(forkHeight));
                    publishStatus(
                        "Fork-aware sync: common ancestor height " +
                        std::to_string(forkHeight));
                }
            }

            // If block identities agree at the overlap and the peer is not ahead,
            // we are synchronized with this peer. Equal height is not enough unless
            // the exact overlap block hash matched above.
            if (!diverged && highestPeerHeight <= localHeight) {
                consecutiveFailures = 0;
                publishStatus("Fully synchronized at height " + std::to_string(localHeight));
                if (coutMutex && !wasFullySynced) {
                    std::lock_guard<std::mutex> lock(*coutMutex);
                    std::cout << "\r[SYNC] ✓ Fully synchronized at height "
                              << localHeight << "                    " << std::endl;
                }
                wasFullySynced = true;
                waitBriefly(5000);
                continue;
            }

            wasFullySynced = false;
            uint64_t currentHeight = diverged ? forkHeight + 1 : localHeight + 1;
            if (currentHeight > highestPeerHeight) {
                // A shorter divergent peer branch still gets indexed through its
                // advertised tip; existing 08B chainwork policy decides whether it
                // can ever be a strict winner. No height-based reorg decision here.
                currentHeight = forkHeight + 1;
            }

            std::string expectedPrev = getBlockHashByHeight(forkHeight);
            if (!diverged && localHeight > 0) {
                expectedPrev = getBlockHashByHeight(localHeight);
            }

            uint64_t processed = 0;
            const uint64_t branchStart = currentHeight;
            while (currentHeight <= highestPeerHeight &&
                   running.load(std::memory_order_acquire)) {
                const uint64_t batchEnd = std::min(
                    currentHeight + static_cast<uint64_t>(batchSize) - 1,
                    highestPeerHeight);

                for (uint64_t h = currentHeight;
                     h <= batchEnd && running.load(std::memory_order_acquire);
                     ++h) {
                    Block block;
                    if (!requestPeerBlock(bestPeer, h, block)) {
                        ++consecutiveFailures;
                        goto sync_cycle_end;
                    }

                    if (expectedPrev.empty() || block.header.prevHash != expectedPrev) {
                        Logger::log(
                            "[MULTINODE-01B] FAIL-CLOSED: remote branch ancestry mismatch "
                            "at height " + std::to_string(h) + " expectedPrev=" +
                            expectedPrev + " got=" + block.header.prevHash);
                        ++consecutiveFailures;
                        goto sync_cycle_end;
                    }

                    // Authoritative validation, bounded side indexing, chainwork
                    // comparison and any durable 08B reorg are owned by the existing
                    // sole block-acceptance pipeline. Sync never mutates UTXO state
                    // directly and never invents a second reorg executor.
                    if (!submitBlockFromNetwork(block, "peer:" + bestPeer->getIp())) {
                        Logger::log(
                            "[MULTINODE-01B] Authoritative block admission rejected height " +
                            std::to_string(h));
                        ++consecutiveFailures;
                        goto sync_cycle_end;
                    }

                    expectedPrev = block.blockHash;
                    ++processed;
                    consecutiveFailures = 0;

                    if (h % 10 == 0 || h == highestPeerHeight) {
                        publishStatus(
                            "Fork-aware sync progress " + std::to_string(h) + "/" +
                            std::to_string(highestPeerHeight));
                    }
                }
                currentHeight = batchEnd + 1;
            }

            if (processed > 0) {
                Logger::log(
                    "[MULTINODE-01B] Sync branch intake complete start=" +
                    std::to_string(branchStart) + " end=" +
                    std::to_string(highestPeerHeight) + " activeTip=" +
                    std::to_string(getBestTipHeight()));
                try {
                    validateChain();
                    saveChainState();
                } catch (const std::exception& e) {
                    Logger::log(
                        "[MULTINODE-01B] Post-sync validation failed: " +
                        std::string(e.what()));
                    ++consecutiveFailures;
                }
            }

sync_cycle_end:
            if (consecutiveFailures >= maxConsecutiveFailures) {
                Logger::log(
                    "[MULTINODE-01B] Repeated sync failures; rebuilding local indexes "
                    "without changing active-chain selection");
                rebuildChainState();
                consecutiveFailures = 0;
                waitBriefly(10000);
            } else {
                waitBriefly(2000);
            }
        } catch (const std::exception& e) {
            Logger::log("[MULTINODE-01B] Sync error: " + std::string(e.what()));
            ++consecutiveFailures;
            waitBriefly(3000);
        }
    }

exit_sync:
    Logger::log("[MULTINODE-01B] Sync thread terminating");
    if (running.load(std::memory_order_acquire)) {
        try { saveChainState(); }
        catch (const std::exception& e) {
            Logger::log("[MULTINODE-01B] Final save error: " + std::string(e.what()));
        }
    }
}

//==================================================================================
// 	 Invalidate BALANCE
//==================================================================================

void Blockchain::invalidateCachedBalance(const std::string& address) {
    {
        std::unique_lock<std::shared_mutex> lock(addressCacheMutex);
        ++addressCacheRevision; // EXPLORER-LOCK-01: reject stale warmup writes.
        addressCache.erase(address);
    }
    Logger::log("[Blockchain] Invalidated cached balance for " + address);
}
//==================================================================================
// 	 Invalidate Address
//==================================================================================
void Blockchain::invalidateAddressCache(const std::string& address) {
    {
        std::unique_lock<std::shared_mutex> lock(addressCacheMutex);
        ++addressCacheRevision; // EXPLORER-LOCK-01: reject stale warmup writes.
        addressCache.erase(address);
    }
    Logger::log("[Blockchain] Invalidated address cache for " + address);
}
//==================================================================================
// 	 Invalidate UTXO 
//==================================================================================
void Blockchain::invalidateUTXOCache() {
    {
        std::unique_lock<std::shared_mutex> lock(utxoCacheMutex);
        utxoCache.clear();
        cacheHeight = 0;
    }
    Logger::log("[Blockchain] Cleared entire UTXO cache");
}

//==================================================================================
// 	helper function for basic validation during sync
//==================================================================================
bool Blockchain::validateBlockBasic(const Block& block) {
    // Basic structural validation without fee checking
    if (block.transactions.empty()) return false;
    if (block.blockHash.empty()) return false;
    if (!block.transactions[0].isCoinbase) return false;
    
    // Verify block hash
    std::string computedHash = block.computeHash();
    if (computedHash != block.blockHash) return false;
    
    // Verify proof of work
    if (!verifyBlockDifficulty(block)) return false;
    
    // Verify merkle root
    std::string computedMerkleRoot = computeMerkleRoot(block.transactions);
    if (computedMerkleRoot != block.header.merkleRoot) return false;
    
    return true;
}
//==================================================================================
//			REBUILD CHAIN STATE
//==================================================================================
void Blockchain::rebuildChainState() {
    Logger::log("[rebuildChainState] Rebuilding chain state...");

    //
    // Serialize recovery with normal block submission. reloadBlocks() owns mtx
    // internally; pre-locking mtx here would self-deadlock shared_mutex.
    std::lock_guard<std::mutex> submissionLock(miningSubmitMutex);
    reloadBlocks();

    Logger::log("[rebuildChainState] Chain state rebuilt. Height: " +
                std::to_string(bestTipHeight.load()));
}

//=================================================================================
//			Validate Social Posts
//=================================================================================
bool Blockchain::validateSocialPost(const std::string& opReturnData, const Transaction& tx, int blockHeight) {
    if (opReturnData.size() < 10 || opReturnData.substr(0, 10) != "TRUSOCIAL|") {
        Logger::log("[validateSocialPost] Invalid prefix");
        return false;
    }
    std::string jsonStr = opReturnData.substr(10); // Skip prefix

    try {
        nlohmann::json post = nlohmann::json::parse(jsonStr);
        if (post["type"] != "SOCIAL_POST") {
            Logger::log("[validateSocialPost] Invalid type");
            return false;
        }

        std::string from = post["from"];
        std::string pubkeyHex = post["pubkey"];
        std::string signatureHex = post["signature"];
        std::string message = post["message"];

        if (message.size() > 280) { 
            Logger::log("[validateSocialPost] Message too long");
            return false;
        }

        std::string tokenIDKey = "didToToken:" + from;
        std::string tokenID;
        if (!dbStorage.get(tokenIDKey, tokenID)) {
            Logger::log("[validateSocialPost] DID not found");
            return false;
        }

        std::string ownerKey = "tokenOwner:" + tokenID;
        std::string ownerAddress;
        if (!dbStorage.get(ownerKey, ownerAddress)) {
            Logger::log("[validateSocialPost] Owner not found");
            return false;   
        }

        std::vector<unsigned char> pubkeyBytes = hexDecode(pubkeyHex);
        std::string computedAddress = pubkeyToAddress(pubkeyBytes);
        if (computedAddress != ownerAddress) {
            Logger::log("[validateSocialPost] Address mismatch");
            return false;
        }

        post.erase("signature");
        std::string dataToSign = post.dump();
        std::vector<unsigned char> sigBytes = hexDecode(signatureHex);
        if (!ECDSAKey::verify(pubkeyBytes, dataToSign, sigBytes)) {
            Logger::log("[validateSocialPost] Signature verification failed");
            return false;
        }

        Logger::log("[validateSocialPost] Post validated successfully");
        return true;
    } catch (const std::exception& e) {
        Logger::log("[validateSocialPost] Exception: " + std::string(e.what()));
        return false;
    }
}
//==================================================================================
//			VALIDATE CHAIN STATE
//==================================================================================
void Blockchain::validateChain() {
    Logger::log("[validateChain] Validating chain...");
    std::shared_lock<std::shared_mutex> lock(mtx); // Shared lock for reading
    if (chain.empty()) {
        Logger::log("[validateChain] Chain is empty, nothing to validate.");
        return;
    }
    for (size_t i = 1; i < chain.size(); ++i) {
        if (chain[i].header.prevHash != chain[i - 1].blockHash) {
            Logger::log("[validateChain] Chain invalid at height " + std::to_string(i + 1) +
                        ": prevHash mismatch");
            throw std::runtime_error("Chain validation failed");
        }
    }
    Logger::log("[validateChain] Chain validated successfully.");
}
//==================================================================================
//                    STORE DID MAPPING
//==================================================================================
void Blockchain::storeDIDMapping(const std::string& did, const std::string& address) {
    std::string key = "did::" + did + "::address";
    dbStorage.put(key, address);
    didToAddressMap[did] = address; // Update in-memory map
    Logger::log("Stored DID mapping: " + did + " -> " + address);

    // Store creation timestamp
    std::string createdKey = "did::" + did + "::created";
    auto now = std::chrono::system_clock::now();
    auto timestamp = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();
    dbStorage.put(createdKey, std::to_string(timestamp));
}

//==================================================================================
// DID-01 — IMMUTABLE SIGNED NETWORK DID REGISTRATION STORE
//==================================================================================
bool Blockchain::registerDIDMappingImmutable(
    const std::string& did,
    const std::string& address,
    bool& created,
    bool& conflict,
    std::string& existingAddress) {
    created = false;
    conflict = false;
    existingAddress.clear();

    // One chain-state lock covers check + durable write so concurrent public
    // registrations cannot race an absent DID into two different addresses.
    std::unique_lock<std::shared_mutex> lock(mtx);

    const std::string key = "did::" + did + "::address";
    std::string current;
    if (dbStorage.get(key, current)) {
        existingAddress = current;
        conflict = (current != address);
        if (!conflict) {
            didToAddressMap[did] = current;
        }
        return true; // same-address replay is intentionally idempotent
    }

    const std::string createdKey = "did::" + did + "::created";
    const auto now = std::chrono::system_clock::now();
    const auto timestamp = std::chrono::duration_cast<std::chrono::seconds>(
        now.time_since_epoch()).count();

    // Address + timestamp publish atomically and synchronously.
    leveldb::WriteBatch batch;
    batch.Put(key, address);
    batch.Put(createdKey, std::to_string(timestamp));
    if (!dbStorage.putBatch(batch, true)) {
        Logger::log("[DID-01] durable DID registration batch failed for " + did);
        return false;
    }

    didToAddressMap[did] = address;
    existingAddress = address;
    created = true;
    Logger::log("[DID-01] Registered immutable signed DID mapping: " + did + " -> " + address);
    return true;
}
//==================================================================================
//                   RESOLVE DID TO ADDRESS
//==================================================================================
std::string Blockchain::resolveDIDToAddress(const std::string& did) {
    std::string key = "did::" + did + "::address";
    std::string address;
    if (dbStorage.get(key, address)) {
        Logger::log("Resolved DID: " + did + " to address: " + address);
        return address;
    }
    Logger::log("DID not found: " + did);
    return "";
}
//================================================================================
//			TX COUNT 
//================================================================================
void Blockchain::incrementTxCount(const std::string& address, leveldb::WriteBatch* batch) {
    std::string key = "address:" + address + ":txCount";
    std::string value;
    int count = 0;
    if (dbStorage.get(key, value)) {
        count = std::stoi(value);
    }
    count++;
    if (batch) {
        batch->Put(key, std::to_string(count));
    } else {
        dbStorage.put(key, std::to_string(count));
    }
}
//================================================================================
//                     TX COUNT UPDATER
//================================================================================
void Blockchain::storeTxForAddress(const std::string& address, const std::string& txid, leveldb::WriteBatch* batch) {
    std::string key = "address:" + address + ":tx:" + txid;
    if (batch) {
        batch->Put(key, "1");
    } else {
        dbStorage.put(key, "1");
    }
}
//================================================================================
//                     TX for BLOCK HEIGHT
//================================================================================
int Blockchain::getTxBlockHeight(const std::string& txid) const {
    for (const auto& block : chain) {
        for (const auto& tx : block.transactions) {
            if (tx.txid == txid) {
                return block.height; // Return the block height if found
            }
        }
    }
    return -1; // Return -1 if the transaction is not in a block (e.g., in mempool)
}
//================================================================================
//
//================================================================================
std::string Blockchain::extractAddressFromTxInput(const TxIn& vin) const {
    Transaction prevTx;
    // Attempt to find the previous transaction using the txid from the input
    if (!findTransaction(vin.txid, prevTx)) {
        Logger::log("[extractAddressFromTxInput] Previous transaction not found: " + vin.txid);
        return ""; // Return empty string if the transaction isn't found
    }
    // Check if the vout index is valid
    if (vin.vout >= prevTx.vout.size()) {
        Logger::log("[extractAddressFromTxInput] Invalid vout index: " + std::to_string(vin.vout) + " for tx: " + vin.txid);
        return ""; // Return empty string if the output index is out of bounds
    }
    // Get the output referenced by this input
    const TxOut& prevOut = prevTx.vout[vin.vout];
    // Extract the address from the scriptPubKey of the previous output
    std::string address = extractAddressFromScriptPubKey(prevOut.scriptPubKey, vin.txid, vin.vout, this);
    return address; // Return the extracted address
}
//==================================================================================
// Helper for Explorer function to strip checksum from LevelDB values
//==================================================================================
std::string stripChecksum(const std::string& val, const std::string& key) {
    size_t delimPos = val.find('|');
    if (delimPos == std::string::npos) {
        Logger::log("[stripChecksum] Malformed payload for key: " + key);
        return "";
    }
    return val.substr(delimPos + 1);
}

//================================================================================
//
//================================================================================
bool Blockchain::validateTokenOutput(const ExtendedTokenData& tokenData, const std::string& owner) const {
    // Ensure tokenID, amount, and owner are valid
    if (tokenData.tokenID.empty() || tokenData.amount == 0 || owner.empty()) {
        Logger::log("[validateTokenOutput] ERROR: Invalid token data: tokenID=" + tokenData.tokenID +
                    ", amount=" + std::to_string(tokenData.amount) + ", owner=" + owner);
        return false;
    }
    // Additional checks (e.g., token registry, ownership rules)
    return true;
}
//================================================================================
//
//================================================================================
std::string Blockchain::calculateExpectedBits(
    const std::string& parentHash,
    int candidateHeight) const {

    //
    // Candidate ancestry remains Patch-07 anchored, but the retarget itself is
    // integer-only over the full 256-bit target. No float enters consensus.
    static constexpr uint64_t DESIRED_TIMESPAN =
        static_cast<uint64_t>(DIFFICULTY_RETARGET_INTERVAL) *
        DIFFICULTY_TARGET_SPACING;

    std::shared_lock<std::shared_mutex> lock(mtx);

    auto toHex = [](uint32_t bits) {
        std::ostringstream ss;
        ss << std::hex << bits;
        return ss.str();
    };

    if (candidateHeight <= 1) {
        return toHex(difficulty);
    }

    auto parentIt = blockIndex.find(parentHash);
    if (parentIt == blockIndex.end()) {
        throw std::runtime_error(
            "candidate parent not indexed for difficulty: " + parentHash);
    }

    const BlockIndexEntry* parent = &parentIt->second;
    const int expectedParentHeight = candidateHeight - 1;

    if (parent->height != expectedParentHeight ||
        static_cast<int>(parent->block.height) != expectedParentHeight) {
        throw std::runtime_error(
            "candidate parent height mismatch for difficulty: expected=" +
            std::to_string(expectedParentHeight) +
            " index=" + std::to_string(parent->height) +
            " block=" + std::to_string(parent->block.height));
    }

    if (parent->block.blockHash != parentHash) {
        throw std::runtime_error(
            "candidate parent hash/index mismatch for difficulty: " + parentHash);
    }

    const uint32_t parentBits = parent->block.header.bits;
    ChainWork256 parentTarget;
    if (!compactToTarget256Strict(parentBits, parentTarget) ||
        parentTarget > truPowLimitTarget256()) {
        throw std::runtime_error(
            "candidate parent has invalid/non-canonical difficulty bits");
    }

    // Preserve schedule: height 60 carries forward; first retarget is height 120.
    if (candidateHeight % DIFFICULTY_RETARGET_INTERVAL != 0 ||
        parent->height < DIFFICULTY_RETARGET_INTERVAL) {
        return toHex(parentBits);
    }

    const BlockIndexEntry* startEntry = parent;
    for (int depth = 0; depth < DIFFICULTY_RETARGET_INTERVAL - 1; ++depth) {
        if (startEntry->height <= 1) {
            throw std::runtime_error(
                "insufficient candidate ancestry for difficulty retarget");
        }

        const std::string& headerParent = startEntry->block.header.prevHash;
        auto ancestorIt = blockIndex.find(headerParent);
        if (ancestorIt == blockIndex.end()) {
            throw std::runtime_error(
                "missing candidate ancestor for difficulty: " + headerParent);
        }

        const BlockIndexEntry* ancestor = &ancestorIt->second;
        if (ancestor->height != startEntry->height - 1 ||
            static_cast<int>(ancestor->block.height) != ancestor->height ||
            ancestor->block.blockHash != headerParent) {
            throw std::runtime_error(
                "non-contiguous candidate ancestry while calculating difficulty");
        }

        startEntry = ancestor;
    }

    const int64_t signedSpan =
        static_cast<int64_t>(parent->block.header.timestamp) -
        static_cast<int64_t>(startEntry->block.header.timestamp);

    uint64_t actualTime =
        signedSpan > 0 ? static_cast<uint64_t>(signedSpan) : 1ULL;

    const uint64_t minTimespan = DESIRED_TIMESPAN / 2ULL;
    const uint64_t maxTimespan = DESIRED_TIMESPAN * 2ULL;
    if (actualTime < minTimespan) actualTime = minTimespan;
    if (actualTime > maxTimespan) actualTime = maxTimespan;

    boost::multiprecision::uint512_t scaled =
        boost::multiprecision::uint512_t(parentTarget) * actualTime;
    scaled /= DESIRED_TIMESPAN;

    const boost::multiprecision::uint512_t powLimit512(
        truPowLimitTarget256());

    ChainWork256 nextTarget;
    if (scaled > powLimit512) {
        nextTarget = truPowLimitTarget256();
    } else {
        nextTarget = static_cast<ChainWork256>(scaled);
    }

    if (nextTarget == 0) {
        throw std::runtime_error("retarget produced zero target");
    }

    const uint32_t nextBits = target256ToCompact(nextTarget);

    ChainWork256 roundTrip;
    if (!compactToTarget256Strict(nextBits, roundTrip) ||
        roundTrip > truPowLimitTarget256()) {
        throw std::runtime_error(
            "retarget produced non-canonical/out-of-range compact bits");
    }

    return toHex(nextBits);
}

//================================================================================
//                     CALCULATE SUBSIDY
//================================================================================
uint64_t Blockchain::calculateSubsidy(int height) const {
    uint64_t subsidy = 50ULL * 100000000ULL; // 50 TRU in TRU atoms
    int halvings = (height - 1) / 210000;   // Halving every 210,000 blocks, genesis at height 1
    for (int i = 0; i < halvings; ++i) {
        subsidy /= 2;
    }
    return subsidy;
}
//================================================================================
//                     IS ADDRESS VALID
//================================================================================
bool Blockchain::isValidAddress(const std::string& addr) const {
    try {
        std::vector<unsigned char> decoded = decodeBase58Check(addr);
        if (decoded.size() != 25) return false; // For P2PKH, should be 25 bytes
        if (decoded[0] != tru_network::MAINNET_P2PKH_VERSION) return false;   // TRU mainnet P2PKH
        return true;
    } catch (const std::exception& e) {
        Logger::log("[isValidAddress] Invalid address: " + std::string(e.what()));
        return false;
    }
}
//================================================================================
//			Compute SigHash
//================================================================================
std::vector<unsigned char> Blockchain::computeSighash(const Transaction& tx, size_t inputIndex, const std::vector<unsigned char>& scriptPubKey) const {
    Logger::log("[computeSighash] Computing sighash for tx: " + tx.txid + ", input: " + std::to_string(inputIndex));
    
    // Use the same method as Transaction::getSigHash to ensure consistency
    try {
        std::vector<unsigned char> sighash = tx.getSigHash(inputIndex, scriptPubKey);
        Logger::log("[computeSighash] Computed sighash: " + hexEncode(sighash));
        return sighash;
    } catch (const std::exception& e) {
        Logger::log("[computeSighash] ERROR: Failed to compute sighash: " + std::string(e.what()));
        return {};
    }
}
//================================================================================
//                     IS BLOCK VALID
//================================================================================
uint32_t Blockchain::getMedianTimePast(
    const std::string& parentHash,
    int candidateHeight) const {

    //
    // MTP must follow the candidate's parent links, not chain[] by height.
    // Preserve the existing early-chain behavior (MTP disabled through a
    // parent height of 11), then use the immediate parent plus its 10 ancestors.
    if (candidateHeight <= 1) return 0;

    std::shared_lock<std::shared_mutex> lock(mtx);

    auto parentIt = blockIndex.find(parentHash);
    if (parentIt == blockIndex.end()) {
        throw std::runtime_error(
            "candidate parent not indexed for MTP: " + parentHash);
    }

    const BlockIndexEntry* current = &parentIt->second;
    const int expectedParentHeight = candidateHeight - 1;

    if (current->height != expectedParentHeight ||
        static_cast<int>(current->block.height) != expectedParentHeight ||
        current->block.blockHash != parentHash) {
        throw std::runtime_error(
            "candidate parent height/hash mismatch for MTP");
    }

    if (current->height <= 11) return 0;

    std::vector<uint32_t> timestamps;
    timestamps.reserve(11);

    for (int count = 0; count < 11; ++count) {
        timestamps.push_back(current->block.header.timestamp);

        if (count == 10) break;
        if (current->height <= 1) {
            throw std::runtime_error(
                "insufficient candidate ancestry for MTP window");
        }

        const std::string& headerParent = current->block.header.prevHash;
        if (current->parentHash != headerParent) {
            throw std::runtime_error(
                "blockIndex/header parent mismatch while walking MTP ancestry");
        }

        auto ancestorIt = blockIndex.find(headerParent);
        if (ancestorIt == blockIndex.end()) {
            throw std::runtime_error(
                "missing candidate ancestor for MTP: " + headerParent);
        }

        const BlockIndexEntry* ancestor = &ancestorIt->second;
        if (ancestor->height != current->height - 1 ||
            static_cast<int>(ancestor->block.height) != ancestor->height ||
            ancestor->block.blockHash != headerParent) {
            throw std::runtime_error(
                "non-contiguous candidate ancestry while calculating MTP");
        }

        current = ancestor;
    }

    if (timestamps.size() != 11) {
        throw std::runtime_error("incomplete candidate MTP window");
    }

    std::sort(timestamps.begin(), timestamps.end());
    return timestamps[timestamps.size() / 2];
}

bool Blockchain::validateBlock(const Block& block) {
    Logger::log("[validateBlock] Starting validation for block: " + block.blockHash + ", height: " + std::to_string(block.height));

    // Step 1: Validate block structure
    if (block.transactions.empty()) {
        Logger::log("[validateBlock] ERROR: Block has no transactions");
        return false;
    }
    if (block.blockHash.empty() || block.blockHash.size() != 64 || !isValidHex(block.blockHash)) {
        Logger::log("[validateBlock] ERROR: Invalid block hash: " + block.blockHash);
        return false;
    }
    if (block.header.prevHash.size() != 64 || !isValidHex(block.header.prevHash)) {
        Logger::log("[validateBlock] ERROR: Invalid prevHash: " + block.header.prevHash);
        return false;
    }

    // enforce cheap byte/count limits before expensive
    // txid recomputation, BIP30 UTXO lookups, Merkle work, or script execution.
    size_t serializedBlockSize = 0;
    try {
        serializedBlockSize = block.serialize().size();
    } catch (const std::exception& e) {
        Logger::log(std::string("[validateBlock] ERROR: block serialization failed: ") + e.what());
        return false;
    } catch (...) {
        Logger::log("[validateBlock] ERROR: block serialization failed");
        return false;
    }
    if (serializedBlockSize > MAX_BLOCK_BYTES) {
        Logger::log("[validateBlock] ERROR: Block size (" +
                    std::to_string(serializedBlockSize) +
                    " bytes) exceeds limit (" + std::to_string(MAX_BLOCK_BYTES) + ")");
        return false;
    }

    size_t blockInputCount = 0;
    size_t blockOutputCount = 0;
    size_t blockStateInitBytes = 0;
    for (const auto& tx : block.transactions) {
        if (!validateTxResourceShape(
                tx, blockInputCount, blockOutputCount, blockStateInitBytes,
                true, "[validateBlock]")) {
            return false;
        }
    }

    // Step 2: Verify block hash
    std::string computedHash = block.computeHash();
    if (computedHash != block.blockHash) {
        Logger::log("[validateBlock] ERROR: Hash mismatch: computed=" + computedHash + ", expected=" + block.blockHash);
        return false;
    }

    // Step 3: Verify proof-of-work
    if (!verifyBlockDifficulty(block)) {
        Logger::log("[validateBlock] ERROR: Proof-of-work check failed for block: " + block.blockHash);
        return false;
    }

    // Step 4: Check previous block hash and height
    std::string prevHash = block.header.prevHash;
    {
        std::shared_lock<std::shared_mutex> lock(mtx);
        if (prevHash == std::string(64, '0')) {
            if (block.height != 1) {
                Logger::log("[validateBlock] ERROR: Genesis block must have height 1, got " + std::to_string(block.height));
                return false;
            }
        } else {
            auto it = blockIndex.find(prevHash);
            if (it == blockIndex.end()) {
                Logger::log("[validateBlock] ERROR: Previous block not found: " + prevHash);
                return false;
            }
            int expectedHeight = it->second.height + 1;
            if (block.height != expectedHeight) {
                Logger::log("[validateBlock] ERROR: Height mismatch: expected=" + std::to_string(expectedHeight) +
                            ", got=" + std::to_string(block.height));
                return false;
            }
        }
    }

    // Step 5: Validate timestamp
    //auto now = std::chrono::system_clock::now().time_since_epoch();
    //uint32_t currentTime = std::chrono::duration_cast<std::chrono::seconds>(now).count();
    //if (block.header.timestamp > currentTime + 7200) {
    //    Logger::log("[validateBlock] ERROR: Timestamp too far in the future: " + std::to_string(block.header.timestamp));
    //    return false;
    //}
    //if (block.height > bestTipHeight) {
    //    if (block.header.timestamp < currentTime - 86400) {
    //        Logger::log("[validateBlock] ERROR: Timestamp too old: " + std::to_string(block.header.timestamp));
    //        return false;
    //    }
    //}

    auto now = std::chrono::system_clock::now().time_since_epoch();
    uint32_t currentTime = std::chrono::duration_cast<std::chrono::seconds>(now).count();

    // Check not too far in future (2 hours)
    if (block.header.timestamp > currentTime + 7200) {
        Logger::log("[validateBlock] ERROR: Timestamp too far in future");
        return false;
    }

    // TRU Security Patch 07 + Smart Contract Patch 20 v2:
    // derive the candidate-parent MTP ONCE and use that exact value both for
    // header validation and every CLTV script executed in this block.
    uint32_t candidateParentMtp = 0;
    try {
        candidateParentMtp = getMedianTimePast(
            block.header.prevHash, static_cast<int>(block.height));
        if (block.header.timestamp <= candidateParentMtp) {
            Logger::log("[validateBlock] ERROR: Timestamp not greater than candidate-parent MTP");
            return false;
        }
    } catch (const std::exception& e) {
        Logger::log(std::string("[validateBlock] ERROR: candidate ancestry/MTP failure: ") + e.what());
        return false;
    }

    //
    // Never trust a transaction ID supplied by a peer or deserializer.  The
    // Merkle root below is built from tx.txid, so every claimed ID must first
    // be proven to match TRU's canonical computeTxId() result for the actual
    // transaction contents.
    //
    // Work on a copy because computeTxId() mutates txid and temporarily clears
    // fields while hashing.  validateBlock() must not modify the received block.
    std::unordered_set<std::string> blockTxids;
    blockTxids.reserve(block.transactions.size());

    for (size_t txIndex = 0; txIndex < block.transactions.size(); ++txIndex)
    {
        const Transaction &receivedTx = block.transactions[txIndex];

        if (receivedTx.txid.empty() || receivedTx.txid.size() != 64 || !isValidHex(receivedTx.txid))
        {
            Logger::log("[validateBlock] ERROR: Invalid transaction ID encoding at index " +
                        std::to_string(txIndex));
            return false;
        }

        Transaction recomputedTx = receivedTx;
        const std::string claimedTxid = receivedTx.txid;
        recomputedTx.computeTxId();

        if (recomputedTx.txid != claimedTxid)
        {
            Logger::log("[validateBlock] ERROR: Transaction ID/content mismatch at index " +
                        std::to_string(txIndex) + ": claimed=" + claimedTxid +
                        ", computed=" + recomputedTx.txid);
            return false;
        }

        // CVE-2012-2459 class defense: the merkle tree must not hide duplicates.
        if (!blockTxids.insert(claimedTxid).second)
        {
            Logger::log(
                "[validateBlock] ERROR: Duplicate transaction ID in block: " +
                claimedTxid);
            return false;
        }

        // BIP30-style live-UTXO collision protection.
        for (size_t outIndex = 0; outIndex < receivedTx.vout.size(); ++outIndex)
        {
            if (outIndex > static_cast<size_t>(
                    std::numeric_limits<uint32_t>::max()))
            {
                Logger::log(
                    "[validateBlock] ERROR: Output index exceeds uint32 range");
                return false;
            }

            UTXO existing;
            if (utxoSet.getUTXO(
                    claimedTxid,
                    static_cast<uint32_t>(outIndex),
                    existing))
            {
                Logger::log(
                    "[validateBlock] ERROR: BIP30-style UTXO collision: " +
                    claimedTxid + ":" + std::to_string(outIndex));
                return false;
            }
        }
    }

    // Step 6: Verify Merkle root
    std::string computedMerkleRoot = computeMerkleRoot(block.transactions);
    if (computedMerkleRoot != block.header.merkleRoot) {
        Logger::log("[validateBlock] ERROR: Merkle root mismatch: computed=" + computedMerkleRoot +
                    ", expected=" + block.header.merkleRoot);
        return false;
    }

    // Step 7: Validate coinbase transaction
    if (!block.transactions[0].isCoinbase) {
        Logger::log("[validateBlock] ERROR: First transaction is not a coinbase");
        return false;
    }
    // FIX(crash): short-circuit deref of vout[0] on an empty coinbase.
    if (block.transactions[0].vout.empty()) {
        Logger::log("[validateBlock] ERROR: Coinbase has no outputs");
        return false;
    }

    // every non-genesis coinbase must commit to the
    // candidate block height in its scriptSig. Coinbase scriptSig IS included
    // in TRU's coinbase txid, so this commitment is merkle-covered today.
    if (block.height > 1) {
        uint64_t committedHeight = 0;
        if (!extractCommittedCoinbaseHeight(
                block.transactions[0], committedHeight) ||
            committedHeight != block.height) {
            Logger::log(
                "[validateBlock] ERROR: Coinbase height commitment mismatch: "
                "block=" + std::to_string(block.height) +
                " committed=" + std::to_string(committedHeight));
            return false;
        }
    }
    // the coinbase amount is NOT validated here any more.
    //
    // The old test was:
    //     if (block.transactions[0].vout[0].amount > calculateSubsidy(height))
    //         reject;
    //
    // At this point in validateBlock the block's transaction fees have not
    // been summed yet (that happens in Step 8), so the coinbase was being
    // compared against the bare subsidy.  getblocktemplate advertises
    // coinbasevalue = subsidy + fees, so every block that carried even one
    // fee-paying transaction was rejected with:
    //
    //     "Invalid coinbase output amount: got=5000010000, expected<=5000000000"
    //
    // That halted block production entirely for as long as the mempool was
    // non-empty: the miner re-included the same transaction in every
    // template and every solved block was thrown away.
    //
    // Step 8b below performs the correct check once totalFees is known:
    //     coinbaseValue <= subsidy + totalFees
    // It also sums ALL coinbase outputs rather than only vout[0], so it is
    // strictly the more complete test.  Do not reintroduce a subsidy-only
    // comparison here.

    // Step 8: Validate all transactions
    std::unordered_set<std::string> spentUTXOs;
    uint64_t totalFees = 0;
    uint64_t blockScriptOps = 0;
    uint64_t blockSigOps = 0;
    uint64_t blockGasUsed = 0;
    std::unordered_set<std::string> touchedStateRoots;
    for (size_t i = 0; i < block.transactions.size(); ++i)
    {
        const Transaction &tx = block.transactions[i];
        Logger::log("[validateBlock] Validating transaction " + std::to_string(i) + ": " + tx.txid);

        if (i == 0)
        {
            // coinbase tx is handled later for value checks
            continue;
        }

        if (tx.isCoinbase)
        {
            Logger::log("[validateBlock] ERROR: Multiple coinbase transactions detected");
            return false;
        }

        uint64_t inSum = 0, outSum = 0;
        uint64_t txScriptOps = 0;
        uint64_t txSigOps = 0;
        uint64_t txGasUsed = 0;
        bool sawStatefulCallInput = false;

        // retain creation classification while validating
        // inputs so consensus can bind the new root to its sole P2PKH creator.
        const auto stateCreation =
            tru_contract_call::ValidateStatefulCreationShape(tx);
        if (!stateCreation.valid) {
            Logger::log(
                "[validateBlock] ERROR: stateful creation classification diverged: " +
                stateCreation.reason);
            return false;
        }

        // Inputs
        for (size_t j = 0; j < tx.vin.size(); ++j)
        {
            const TxIn &vin = tx.vin[j];
            const std::string utxoKey = vin.txid + ":" + std::to_string(vin.vout);

            if (spentUTXOs.count(utxoKey))
            {
                Logger::log("[validateBlock] ERROR: Double-spend detected for UTXO: " + utxoKey);
                return false;
            }

            UTXO utxo;
            if (!utxoSet.getUTXO(vin.txid, vin.vout, utxo))
            {
                Logger::log("[validateBlock] ERROR: Missing UTXO for input: " + utxoKey);
                return false;
            }

            if (stateCreation.hasCreation && j == 0) {
                std::string creatorHash160;
                if (!tru_contract_call::ExtractCanonicalP2PKHHash160Hex(
                        utxo.scriptPubKey, creatorHash160)) {
                    Logger::log(
                        "[validateBlock] ERROR: stateful V1 creator input must be standard P2PKH");
                    return false;
                }
            }

            // Enforce coinbase maturity at consensus
            if (utxo.isCoinbase)
            {
                if (block.height <= utxo.createdAtHeight ||
                    (block.height - utxo.createdAtHeight) < COINBASE_MATURITY)
                {
                    Logger::log("[validateBlock] ERROR: Spending immature coinbase: " + utxoKey);
                    return false;
                }
            }

            //
            // Consensus monetary arithmetic must never rely on uint64_t wraparound.
            // Bound every referenced UTXO and accumulate the input value with an
            // explicit MAX_MONEY check.
            if (utxo.amount > MAX_MONEY)
            {
                Logger::log("[validateBlock] ERROR: Input UTXO exceeds MAX_MONEY: " + utxoKey);
                return false;
            }
            if (inSum > MAX_MONEY - utxo.amount)
            {
                Logger::log("[validateBlock] ERROR: Input sum exceeds MAX_MONEY: " + tx.txid);
                return false;
            }
            inSum += utxo.amount;

            // Script verification.
            std::vector<unsigned char> scriptPubKeyBytes;
            try {
                scriptPubKeyBytes = hexDecode(utxo.scriptPubKey);
            } catch (const std::exception& e) {
                Logger::log(std::string("[validateBlock] ERROR: Invalid scriptPubKey encoding for UTXO: ") +
                            utxoKey + ": " + e.what());
                return false;
            }
            if (scriptPubKeyBytes.empty() ||
                scriptPubKeyBytes.size() > tru_limits::MAX_SCRIPT_BYTES ||
                vin.scriptSig.size() > tru_limits::MAX_SCRIPT_BYTES)
            {
                Logger::log("[validateBlock] ERROR: Script byte limit exceeded for UTXO: " + utxoKey);
                return false;
            }

            // leading OP_RETURN outputs are unspendable.
            // Data-carrier outputs must never be made spendable by attacker-controlled
            // scriptSig stack contents or by OP_RETURN's interpreter termination behavior.
            // This rule is based only on the locking-script prefix and therefore applies
            // identically to push-prefixed and legacy/raw OP_RETURN payload encodings.
            if (scriptPubKeyBytes.front() == static_cast<unsigned char>(OP_RETURN))
            {
                Logger::log("[validateBlock] ERROR: Attempt to spend unspendable OP_RETURN UTXO: " + utxoKey);
                return false;
            }

            ScriptResourceMetrics unlockMetrics, lockMetrics;
            if (!AnalyzeScriptResources(vin.scriptSig, unlockMetrics) ||
                !AnalyzeScriptResources(scriptPubKeyBytes, lockMetrics) ||
                !addScriptMetricsChecked(
                    unlockMetrics, lockMetrics,
                    txScriptOps, txSigOps, blockScriptOps, blockSigOps)) {
                Logger::log("[validateBlock] ERROR: script/sigop budget exceeded for input: " + utxoKey);
                return false;
            }

            // owner-authorized Stateful K/V
            // continuation execution. State is loaded from the stable confirmed
            // root and executed on a disposable scratch copy during validation.
            const auto statefulScan =
                tru_contract_call::ScanStatefulContractScript(scriptPubKeyBytes);
            if (!statefulScan.valid) {
                Logger::log("[validateBlock] ERROR: malformed stateful-script scan for input: " + utxoKey);
                return false;
            }
            if (statefulScan.usesStateDomain) {
                const auto callShape =
                    tru_contract_call::ValidateStatefulCallShape(
                        tx, j, utxo.scriptPubKey, utxo.amount);
                if (!callShape.valid) {
                    Logger::log(
                        "[validateBlock] ERROR: invalid state-anchor call shape for " +
                        utxoKey + ": " + callShape.reason);
                    return false;
                }

                const std::string current =
                    tru_contract_state::BuildCanonicalContractOutpoint(
                        vin.txid, static_cast<uint32_t>(vin.vout));
                tru_contract_state_runtime::ConfirmedStateDomainSnapshot snapshot;
                std::string stateReason;
                if (current.empty() ||
                    !tru_contract_state_runtime::LoadConfirmedStateDomain(
                        dbStorage, current, snapshot, stateReason)) {
                    Logger::log(
                        "[validateBlock] ERROR: confirmed state-domain load failed for " +
                        utxoKey + ": " + stateReason);
                    return false;
                }
                if (!touchedStateRoots.insert(snapshot.root).second) {
                    Logger::log(
                        "[validateBlock] ERROR: more than one Stateful K/V call for root in one block: " +
                        snapshot.root);
                    return false;
                }

                const TxIn& callerVin = tx.vin[callShape.callerInputIndex];
                UTXO callerUtxo;
                if (!utxoSet.getUTXO(callerVin.txid, callerVin.vout, callerUtxo)) {
                    Logger::log(
                        "[validateBlock] ERROR: missing caller funding UTXO for stateful call: " +
                        callerVin.txid + ":" + std::to_string(callerVin.vout));
                    return false;
                }
                std::string callerHash160;
                if (!tru_contract_call::ExtractCanonicalP2PKHHash160Hex(
                        callerUtxo.scriptPubKey, callerHash160)) {
                    Logger::log(
                        "[validateBlock] ERROR: stateful V1 caller input must be standard P2PKH");
                    return false;
                }
                const std::string callerAddress =
                    extractAddressFromScriptPubKey(
                        callerUtxo.scriptPubKey, callerVin.txid,
                        static_cast<uint32_t>(callerVin.vout), this);
                if (callerAddress.empty()) {
                    Logger::log(
                        "[validateBlock] ERROR: unable to derive stateful caller address");
                    return false;
                }

                if (txGasUsed >= tru_limits::MAX_TX_SCRIPT_GAS ||
                    blockGasUsed >= tru_limits::MAX_BLOCK_SCRIPT_GAS) {
                    Logger::log("[validateBlock] ERROR: transaction/block gas budget exhausted");
                    return false;
                }
                const uint64_t inputGasLimit = std::min({
                    tru_limits::MAX_SCRIPT_GAS_PER_INPUT,
                    tru_limits::MAX_TX_SCRIPT_GAS - txGasUsed,
                    tru_limits::MAX_BLOCK_SCRIPT_GAS - blockGasUsed});
                if (inputGasLimit == 0) return false;

                uint64_t stateCallGasUsed = 0;
                std::string stateCallLabel;
                if (snapshot.family.empty()) {
                    if (callerHash160 != snapshot.ownerHash160) {
                        Logger::log(
                            "[validateBlock] ERROR: unauthorized Stateful K/V V1 caller for root " +
                            snapshot.root);
                        return false;
                    }

                    tru_contract_state_runtime::KvCallExecutionResult execResult;
                    if (!tru_contract_state_runtime::ExecuteStatefulKvV1Call(
                            tx, callShape, scriptPubKeyBytes, snapshot, callerAddress,
                            block.header.timestamp, static_cast<uint32_t>(block.height),
                            inputGasLimit, this, execResult, stateReason)) {
                        Logger::log(
                            "[validateBlock] ERROR: Stateful K/V V1 scratch execution failed: " +
                            stateReason);
                        return false;
                    }
                    stateCallGasUsed = execResult.gasUsed;
                    stateCallLabel = "Stateful K/V V1";
                } else if (snapshot.family == "voting_v1") {
                    tru_contract_state_runtime::VotingCallExecutionResult execResult;
                    if (!tru_contract_state_runtime::ExecuteVotingV1Call(
                            tx, callShape, scriptPubKeyBytes, snapshot,
                            callerHash160, callerAddress,
                            block.header.timestamp, static_cast<uint32_t>(block.height),
                            inputGasLimit, this, execResult, stateReason)) {
                        Logger::log(
                            "[validateBlock] ERROR: Voting V1 scratch execution failed: " +
                            stateReason);
                        return false;
                    }
                    stateCallGasUsed = execResult.gasUsed;
                    stateCallLabel = "Voting V1";
                } else if (snapshot.family == "token_issuer_v1") {
                    tru_contract_state_runtime::TokenIssuerCallExecutionResult execResult;
                    if (!tru_contract_state_runtime::ExecuteTokenIssuerV1Call(
                            tx, callShape, scriptPubKeyBytes, snapshot,
                            callerHash160, callerAddress,
                            block.header.timestamp, static_cast<uint32_t>(block.height),
                            inputGasLimit, this, execResult, stateReason)) {
                        Logger::log(
                            "[validateBlock] ERROR: Token Issuer V1 scratch execution failed: " +
                            stateReason);
                        return false;
                    }
                    stateCallGasUsed = execResult.gasUsed;
                    stateCallLabel = "Token Issuer V1";
                } else {
                    Logger::log(
                        "[validateBlock] ERROR: unsupported confirmed stateful family");
                    return false;
                }

                if (stateCallGasUsed >
                        tru_limits::MAX_TX_SCRIPT_GAS - txGasUsed ||
                    stateCallGasUsed >
                        tru_limits::MAX_BLOCK_SCRIPT_GAS - blockGasUsed) {
                    Logger::log(
                        "[validateBlock] ERROR: stateful V1 gas accounting breach");
                    return false;
                }
                txGasUsed += stateCallGasUsed;
                blockGasUsed += stateCallGasUsed;
                sawStatefulCallInput = true;
                spentUTXOs.insert(utxoKey);

                Logger::log(
                    "[validateBlock] " + stateCallLabel +
                    " call validated: root=" +
                    snapshot.root + " current=" + current +
                    " continuationVout=" +
                    std::to_string(callShape.continuationVout) +
                    " callValue=" + std::to_string(callShape.callValue) +
                    " key=" + callShape.logicalKey +
                    " callerHash160=" + callerHash160);
                continue;
            }

            if (txGasUsed >= tru_limits::MAX_TX_SCRIPT_GAS ||
                blockGasUsed >= tru_limits::MAX_BLOCK_SCRIPT_GAS) {
                Logger::log("[validateBlock] ERROR: transaction/block gas budget exhausted");
                return false;
            }
            const uint64_t inputGasLimit = std::min({
                tru_limits::MAX_SCRIPT_GAS_PER_INPUT,
                tru_limits::MAX_TX_SCRIPT_GAS - txGasUsed,
                tru_limits::MAX_BLOCK_SCRIPT_GAS - blockGasUsed});
            if (inputGasLimit == 0) return false;

            // consensus context is built from
            // explicit block/input data. OP_BLOCKTIME now uses the candidate
            // block header timestamp, never the validator node's wall clock.
            const std::vector<unsigned char> inputSighash =
                computeSighash(tx, j, scriptPubKeyBytes);
            const std::string inputSender =
                extractAddressFromScriptPubKey(
                    utxo.scriptPubKey, vin.txid, vin.vout, this);
            const std::string contractIdentity =
                BuildContractIdentity(vin.txid, vin.vout);
            if (contractIdentity.empty()) {
                Logger::log("[validateBlock] ERROR: Cannot derive contract identity for input: " + utxoKey);
                return false;
            }

            // state is scoped by the locking UTXO
            // identity, never by owner/caller. Validation works on a local copy;
            // Patch 14D will define atomic persistence/rollback of successful writes.
            std::unordered_map<std::string, std::vector<unsigned char>> scratchState;
            {
                // NOTE: do NOT lock `mtx` here — validateBlock may already run
                // with `mtx` held by a caller, and re-locking a non-recursive
                // shared_mutex self-deadlocks. Read is best-effort for validation.
                auto csIt = contractStates.find(contractIdentity);
                if (csIt != contractStates.end()) scratchState = csIt->second;
            }

            ScriptExecutionContextSpec ctxSpec;
            ctxSpec.gasLimit = inputGasLimit;
            ctxSpec.tx = &tx;
            ctxSpec.blockTime = block.header.timestamp;
            ctxSpec.medianTimePast = candidateParentMtp;
            ctxSpec.inputIndex = j;
            ctxSpec.scriptPubKey = &scriptPubKeyBytes;
            ctxSpec.sighash = inputSighash;
            ctxSpec.chainCtx = this;
            ctxSpec.execHeight = static_cast<uint32_t>(block.height);
            ctxSpec.sender = inputSender;
            ctxSpec.state = &scratchState;
            ctxSpec.contractAddress = contractIdentity;
            // outputIndex intentionally remains unset until 14E.
            ScriptExecutionContext ctx = BuildScriptExecutionContext(ctxSpec);

            try
            {
                if (!VerifyScripts(vin.scriptSig, scriptPubKeyBytes, ctx))
                {
                    Logger::log("[validateBlock] ERROR: Script verification failed for input: " + utxoKey);
                    return false;
                }
            }
            catch (const std::exception &e)
            {
                Logger::log(std::string("[validateBlock] ERROR: Script execution exception for input ") + utxoKey + ": " + e.what());
                return false;
            }

            if (ctx.gasUsed > inputGasLimit ||
                ctx.gasUsed > tru_limits::MAX_TX_SCRIPT_GAS - txGasUsed ||
                ctx.gasUsed > tru_limits::MAX_BLOCK_SCRIPT_GAS - blockGasUsed) {
                Logger::log("[validateBlock] ERROR: script gas accounting overflow/budget breach");
                return false;
            }
            txGasUsed += ctx.gasUsed;
            blockGasUsed += ctx.gasUsed;

            // Mark spent after successful verification
            spentUTXOs.insert(utxoKey);
        }

        if (stateCreation.hasCallCandidate != sawStatefulCallInput) {
            Logger::log(
                "[validateBlock] ERROR: stateful call envelope/input parity failure for tx " +
                tx.txid);
            return false;
        }

        // Outputs
        // FIX(overflow): bound each output to MAX_MONEY and use checked
        // accumulation so two huge uint64 outputs can't wrap past inSum.
        for (const auto &vout : tx.vout)
        {
            if (vout.amount > MAX_MONEY)
            {
                Logger::log("[validateBlock] ERROR: Output exceeds MAX_MONEY: " + tx.txid);
                return false;
            }
            if (outSum > MAX_MONEY - vout.amount)
            {
                Logger::log("[validateBlock] ERROR: Output sum overflow: " + tx.txid);
                return false;
            }
            outSum += vout.amount;
        }

        if (outSum > inSum)
        {
            Logger::log("[validateBlock] ERROR: Transaction creates money (out > in): " + tx.txid);
            return false;
        }

        //
        // Fee arithmetic is consensus-critical. Keep the per-transaction fee
        // and the running block fee total bounded so neither can wrap.
        const uint64_t txFee = inSum - outSum;
        if (txFee > MAX_MONEY)
        {
            Logger::log("[validateBlock] ERROR: Transaction fee exceeds MAX_MONEY: " + tx.txid);
            return false;
        }
        if (totalFees > MAX_MONEY - txFee)
        {
            Logger::log("[validateBlock] ERROR: Total block fees exceed MAX_MONEY");
            return false;
        }
        totalFees += txFee;
    }

    // ---- Step 8b: Enforce coinbase value <= subsidy + totalFees ----
    //
    // The coinbase transaction was intentionally skipped by the regular
    // transaction-output loop above, so it needs the SAME MAX_MONEY bounds
    // and checked accumulation here. Without this, multiple huge uint64_t
    // outputs can wrap coinbaseValue and bypass the subsidy+fees limit.
    uint64_t coinbaseValue = 0;
    for (const auto &vout : block.transactions[0].vout)
    {
        if (vout.amount > MAX_MONEY)
        {
            Logger::log("[validateBlock] ERROR: Coinbase output exceeds MAX_MONEY");
            return false;
        }
        if (coinbaseValue > MAX_MONEY - vout.amount)
        {
            Logger::log("[validateBlock] ERROR: Coinbase output sum exceeds MAX_MONEY");
            return false;
        }
        coinbaseValue += vout.amount;
    }

    const uint64_t subsidy = calculateSubsidy(block.height);
    if (subsidy > MAX_MONEY)
    {
        Logger::log("[validateBlock] ERROR: Calculated subsidy exceeds MAX_MONEY");
        return false;
    }
    if (totalFees > MAX_MONEY - subsidy)
    {
        Logger::log("[validateBlock] ERROR: Subsidy + fees exceeds MAX_MONEY");
        return false;
    }

    const uint64_t maxCoinbaseValue = subsidy + totalFees;
    if (coinbaseValue > maxCoinbaseValue)
    {
        Logger::log("[validateBlock] ERROR: Coinbase pays too much: coinbase=" +
                    std::to_string(coinbaseValue) + " subsidy=" + std::to_string(subsidy) +
                    " fees=" + std::to_string(totalFees));
        return false;
    }

    // Step 9: block byte size was checked before expensive validation work.
    // Keep the variable live here as a defensive invariant/documentation point.
    if (serializedBlockSize > MAX_BLOCK_BYTES) {
        Logger::log("[validateBlock] ERROR: block size invariant violated");
        return false;
    }

    // Step 10: Validate difficulty bits on EVERY block.
    // FIX(consensus): previously only retarget-height blocks were checked, so at
    // any other height an attacker could set trivial `bits` and mine for free.
    if (block.height > 1) {
        try {
            // difficulty is anchored to THIS block's parent.
            std::string expectedBits =
                calculateExpectedBits(block.header.prevHash, block.height);
            uint32_t exp = std::stoul(expectedBits, nullptr, 16);
            if (block.header.bits != exp) {
                Logger::log("[validateBlock] ERROR: Invalid difficulty bits: expected=" +
                            expectedBits + ", got=" + std::to_string(block.header.bits));
                return false;
            }
        } catch (const std::exception& e) {
            Logger::log(std::string("[validateBlock] ERROR: bad expected bits: ") + e.what());
            return false;
        }
    }

    Logger::log("[validateBlock] Block validated successfully: " + block.blockHash);
    return true;
}

//================================================================================
//                      VERIFY BLOCK TIMES
//================================================================================
uint32_t Blockchain::getCurrentBlockTime() const {
    // Return the current time as a placeholder (adjust based on your needs)
    return static_cast<uint32_t>(std::time(nullptr));
}
//================================================================================
//                      VERIFY BLOCK DIFFICULTY
//================================================================================

/*
bool Blockchain::verifyBlockDifficulty(const Block& blk) const {
    uint64_t target = bitsToTarget(blk.header.bits);
    unsigned char targetVal[32];
    bitsToTargetArrayFree(blk.header.bits, targetVal);
    unsigned char hashVal[32];
    if (!hexToBytes32LE(blk.blockHash, hashVal)) {
        return false;
    }
    return compare256LE(hashVal, targetVal);
}
*/
bool Blockchain::verifyBlockDifficulty(const Block& blk) const {
    ChainWork256 target;
    if (!compactToTarget256Strict(blk.header.bits, target) ||
        target > truPowLimitTarget256()) {
        Logger::log(
            "[verifyBlockDifficulty] ERROR: invalid/non-canonical compact target");
        return false;
    }

    unsigned char targetVal[32];
    target256ToLE32(target, targetVal);

    std::vector<unsigned char> header80 = buildBlockHeader80(blk.header);
    unsigned char hash1[32], hash2[32];

    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, header80.data(), 80);
    SHA256_Final(hash1, &ctx);

    SHA256_Init(&ctx);
    SHA256_Update(&ctx, hash1, 32);
    SHA256_Final(hash2, &ctx);

    uint32_t lastWord = ((uint32_t)hash2[28] << 24) |
                        ((uint32_t)hash2[29] << 16) |
                        ((uint32_t)hash2[30] << 8) |
                        ((uint32_t)hash2[31]);
    lastWord = (lastWord + 0x21E8U) & 0xffffffffU;
    hash2[28] = (unsigned char)((lastWord >> 24) & 0xff);
    hash2[29] = (unsigned char)((lastWord >> 16) & 0xff);
    hash2[30] = (unsigned char)((lastWord >> 8) & 0xff);
    hash2[31] = (unsigned char)(lastWord & 0xff);

    return compare256LE(hash2, targetVal);
}

//================================================================================
//                      BLOCKCHAIN SIZE
//================================================================================
uint64_t Blockchain::getBlockchainSize() const {
    std::shared_lock<std::shared_mutex> lock(mtx);
    uint64_t totalSize = 0;
    for (const auto& block : chain) {
        totalSize += block.serialize().size(); // serialize() is already bytes
    }
    Logger::log("[getBlockchainSize] Calculated blockchain size: " + std::to_string(totalSize) + " bytes");
    return totalSize;
}
//================================================================================
//                      BLOCK  SIZE
//================================================================================
uint64_t Blockchain::getBlockSize(const std::string& blockHash) const {
    std::shared_lock<std::shared_mutex> lock(mtx);
    auto it = blockIndex.find(blockHash);
    if (it == blockIndex.end()) {
        Logger::log("[getBlockSize] Block not found: " + blockHash);
        return 0;
    }
    uint64_t size = it->second.block.serialize().size(); // serialize() is already bytes
    Logger::log("[getBlockSize] Block " + blockHash + " size: " + std::to_string(size) + " bytes");
    return size;
}
//================================================================================
//			Submit Block
//================================================================================
void queueBlock(const Block& blk) {
    {
        std::lock_guard<std::mutex> lock(queueMutex);
        blockQueue.push(blk);
    }
    queueCond.notify_one();
}
//===============================================================================
//			TRUScripts DATA
//===============================================================================
OrdinalData Blockchain::getOrdinalData(const std::string& txid) {
    OrdinalData od{}; // all fields default to zero

    std::string inputTxid;
    int         inputVout = -1;

    {
        std::shared_lock lock(mtx);

        Transaction tx;
        if (!findTransaction(txid, tx)) {
            Logger::log("[getOrdinalData] Transaction not found: " + txid);
            return od;
        }

        // remember the very first input (for TRU atom numbering)
        if (!tx.vin.empty()) {
            inputTxid = tx.vin[0].txid;
            inputVout = tx.vin[0].vout;
        }

        // grab the block timestamp containing this tx
        for (auto const& blk : chain) {
            for (auto const& btx : blk.transactions) {
                if (btx.txid == txid) {
                    od.timestamp = blk.header.timestamp;
                    break;
                }
            }
            if (od.timestamp) break;
        }

        // compute sizeBytes from the first OP_RETURN output (strip "6a")
        for (auto const& vout : tx.vout) {
            const auto& script = vout.scriptPubKey;
            if (script.rfind("6a", 0) == 0) {
                od.sizeBytes = (script.size() - 2) / 2;
                break;
            }
        }
    }

    // ————————————————————————————————————————————————————————————————
    // 2) satNumber = cumulative sum of all UTXO amounts,
    //    in sorted order, until we hit the input being spent
    // ————————————————————————————————————————————————————————————————
    {
        Logger::log("[getOrdinalData] 🔎 Computing satNumber for input " 
            + inputTxid + ":" + std::to_string(inputVout)
        );
        uint64_t cumulative = 0;
        // getAllUTXOs() now returns every live TRU atom in order
        for (auto const& u : utxoSet.getAllUTXOs()) {
            Logger::log("[getOrdinalData]    at UTXO " 
                + u.txid + ":" + std::to_string(u.vout)
                + "   cumulative=" + std::to_string(cumulative)
            );
            if (u.txid == inputTxid && static_cast<int>(u.vout) == inputVout) {
                od.satNumber = cumulative;
                break;
            }
            cumulative += u.amount;
        }
        if (od.satNumber == 0) {
            Logger::log("[getOrdinalData] ⚠️ Did not find the input in the UTXO set!");
        }
    }

    // ————————————————————————————————————————————————————————————————
    // 3) inscriptionIndex = count of existing entries + 1
    // ————————————————————————————————————————————————————————————————
    {
        int count = 0;
        dbStorage.iteratePrefix("tokenMetadata:", [&](auto const& /*key*/, auto const& raw) {
            try {
                auto j = nlohmann::json::parse(raw);
                if (j.value("type","") == "TRUSCRIPT") {
                    ++count;
                }
            } catch (...) {}
        });
        od.inscriptionIndex = static_cast<uint64_t>(count) + 1;
    }

    return od;
}

//================================================================================
//			TRU ISSUED TOTALS
//================================================================================
uint64_t Blockchain::getTotalIssuedTrus() const {
    uint64_t total = 0;
    uint64_t currentReward = 50ULL * 100000000ULL; // Initial reward: 50 TRU in TRU atoms
    uint32_t halvingInterval = 210000;             // Halving every 210,000 blocks
    uint32_t height = bestTipHeight;               // Current block height

    // Iterate through each halving era until all blocks are accounted for
    while (height > 0) {
        // Number of blocks in this era (up to halvingInterval or remaining height)
        uint32_t blocksInThisEra = std::min(halvingInterval, height);
        // Add the total reward for this era
        total += static_cast<uint64_t>(blocksInThisEra) * currentReward;
        // Reduce remaining height
        height -= blocksInThisEra;
        // Halve the reward for the next era
        currentReward >>= 1;
        // Exit early if reward becomes 0 (after ~64 halvings)
        if (currentReward == 0) {
            break;
        }
    }

    return total;
}

//================================================================================
//                      GET NETWORK HASH RATE
//================================================================================
double Blockchain::getNetworkHashrate(int numBlocks) const {
    std::shared_lock<std::shared_mutex> lock(mtx);
    
    int currentHeight = bestTipHeight.load();
    
    if (currentHeight < 2) {
        Logger::log("[getNetworkHashrate] Insufficient blocks (height=" + std::to_string(currentHeight) + ")");
        return 0.0;
    }

    // Calculate reported hash rate from active miners with longer timeout
    double reportedHashrate = 0.0;
    auto now = std::chrono::steady_clock::now();
    
    Logger::log("[getNetworkHashrate] Checking " + std::to_string(minerHashRates.size()) + " registered miners");
    
    for (const auto& [address, rate] : minerHashRates) {
        auto it = minerLastActivity.find(address);
        if (it != minerLastActivity.end()) {
            auto timeSinceActivity = now - it->second;
            // Increased timeout from 1 to 3 minutes for more stable reporting
            if (timeSinceActivity < std::chrono::minutes(2)) {
                reportedHashrate += rate;
                Logger::log("[getNetworkHashrate] Active miner " + address + 
                           ": " + std::to_string(rate) + " H/s");
            } else {
                Logger::log("[getNetworkHashrate] Inactive miner " + address + 
                           " (last activity: " + 
                           std::to_string(std::chrono::duration_cast<std::chrono::seconds>(timeSinceActivity).count()) + "s ago)");
            }
        }
    }
    
    // Calculate theoretical hashrate from blockchain data
    int N = std::min(std::max(numBlocks, 2), std::min(currentHeight, 144));
    std::vector<Block> recentBlocks;
    
    for (int i = currentHeight - N + 1; i <= currentHeight; ++i) {
        auto optionalBlk = getBlockByHeight(i);
        if (!optionalBlk.has_value()) {
            continue;
        }
        recentBlocks.push_back(optionalBlk.value());
    }

    double blockchainHashrate = 0.0;

    if (recentBlocks.size() >= 2)
    {
        uint32_t startTime = recentBlocks.front().header.timestamp;
        uint32_t endTime = recentBlocks.back().header.timestamp;

        if (endTime > startTime)
        {
            double totalTime = static_cast<double>(endTime - startTime);
            int totalBlocks = recentBlocks.size() - 1;

            if (totalTime > 0 && totalBlocks > 0)
            {
                double avgBlockTime = totalTime / totalBlocks;

                // More accurate hashrate calculation
                // Instead of using raw difficulty, calculate based on expected hashes
                // For SHA-256, expected hashes = 2^256 / target
                uint32_t bits = recentBlocks.back().header.bits;

                // Convert bits to actual target value more accurately
                int shift = (bits >> 24) & 0xff;
                uint32_t mantissa = bits & 0x00ffffff;

                // Calculate approximate hashrate based on target
                // This gives a more realistic estimate
                if (shift > 0 && mantissa > 0)
                {
                    // Simplified calculation that gives more reasonable results
                    double targetDifficulty = (0x1d00ffff / static_cast<double>(bits)) * 1000000;
                    blockchainHashrate = targetDifficulty / avgBlockTime;
                }
            }
        }
    }

    // Improved priority logic
    double finalHashrate = 0.0;
    
    if (reportedHashrate > 0) {
        // Use reported hashrate as primary source
        finalHashrate = reportedHashrate;
        
        Logger::log("[getNetworkHashrate] Using reported hashrate: " + std::to_string(reportedHashrate) + " H/s");
        
        // Only blend with blockchain calculation if wildly different AND blockchain rate is reasonable
        if (blockchainHashrate > 0) {
            double ratio = reportedHashrate / blockchainHashrate;
            
            // More reasonable ratio checking (factor of 5 instead of 10)
            if (ratio > 5.0 || ratio < 0.2) {
                Logger::log("[getNetworkHashrate] Large discrepancy detected - ratio: " + std::to_string(ratio));
                
                // Weight reported hashrate more heavily since it's real-time
                finalHashrate = (reportedHashrate * 0.8) + (blockchainHashrate * 0.2);
                
                Logger::log("[getNetworkHashrate] Using weighted average: " + std::to_string(finalHashrate) + " H/s");
            }
        }
    } else if (blockchainHashrate > 0) {
        // No active miners reporting, fall back to blockchain calculation
        finalHashrate = blockchainHashrate;
        Logger::log("[getNetworkHashrate] No active miners, using blockchain hashrate: " + std::to_string(blockchainHashrate) + " H/s");
    } else {
        // No data available
        finalHashrate = 0.0;
        Logger::log("[getNetworkHashrate] No hashrate data available");
    }
    
    // Add minimum threshold to avoid tiny values
    if (finalHashrate < 100.0) { // 1 MH/s minimum
        Logger::log("[getNetworkHashrate] Hashrate below minimum threshold, using blockchain calculation");
        finalHashrate = std::max(blockchainHashrate, 100.0);
    }
    
    Logger::log("[getNetworkHashrate] FINAL RESULT - Total: " + std::to_string(finalHashrate) + 
               " H/s, Reported: " + std::to_string(reportedHashrate) + 
               " H/s, Blockchain: " + std::to_string(blockchainHashrate) + " H/s");
    
    return std::max(0.0, finalHashrate);
}
