void Blockchain::registerMiner(const std::string& minerAddress) {
    std::unique_lock<std::shared_mutex> lock(mtx);
    activeMiners.insert(minerAddress);
    minerLastActivity[minerAddress] = std::chrono::steady_clock::now();
    Logger::log("[Blockchain] Miner registered: " + minerAddress);
}
//================================================================================
//
//================================================================================
void Blockchain::unregisterMiner(const std::string& minerAddress) {
    std::unique_lock<std::shared_mutex> lock(mtx);
    activeMiners.erase(minerAddress);
    minerLastActivity.erase(minerAddress);
    minerHashRates.erase(minerAddress);
    Logger::log("[Blockchain] Miner unregistered: " + minerAddress);
}
//================================================================================
//
//================================================================================
void Blockchain::updateMinerActivity(const std::string& minerAddress, uint64_t hashesTried, double timeTaken) {
    std::unique_lock<std::shared_mutex> lock(mtx);
    
    double hashRate = 0.0;
    
    if (timeTaken > 0.001 && hashesTried > 0) {
        hashRate = static_cast<double>(hashesTried) / timeTaken;
        
        // Increase cap for modern GPU miners (10 TH/s)
        const double MAX_REASONABLE_HASHRATE = 1e13; // 10 TH/s
        if (hashRate > MAX_REASONABLE_HASHRATE) {
            Logger::log("[updateMinerActivity] WARNING: Unreasonable hashrate " + std::to_string(hashRate) + 
                       " H/s for miner " + minerAddress + ", capping to maximum");
            hashRate = MAX_REASONABLE_HASHRATE;
        }
        
        // More conservative moving average (85% new, 15% old)
        if (minerHashRates.find(minerAddress) != minerHashRates.end()) {
            double previousRate = minerHashRates[minerAddress];
            // Only smooth if previous rate exists and is reasonable
            if (previousRate > 0 && previousRate < MAX_REASONABLE_HASHRATE) {
                hashRate = (hashRate * 0.85) + (previousRate * 0.15);
            }
        }
        
        minerHashRates[minerAddress] = hashRate;
        minerLastActivity[minerAddress] = std::chrono::steady_clock::now();
        
        Logger::log("[updateMinerActivity] Miner " + minerAddress + 
                   ": " + std::to_string(hashRate) + " H/s (" + std::to_string(hashesTried) + 
                   " hashes in " + std::to_string(timeTaken) + "s)");
    } else {
        // Don't reset hash rate to 0 immediately, just update timestamp
        minerLastActivity[minerAddress] = std::chrono::steady_clock::now();
        
        // Only reset hash rate if it's been several reports with zero hashes
        static std::unordered_map<std::string, int> zeroHashCount;
        zeroHashCount[minerAddress]++;
        
        if (zeroHashCount[minerAddress] >= 3) { // 3 consecutive zero reports
            minerHashRates[minerAddress] = 0.0;
            zeroHashCount.erase(minerAddress);
            Logger::log("[updateMinerActivity] Reset hash rate for " + minerAddress + " after 3 zero reports");
        } else {
            Logger::log("[updateMinerActivity] Zero hashes for " + minerAddress + 
                       " (count: " + std::to_string(zeroHashCount[minerAddress]) + ")");
        }
    }
    // Never hold the chain lock while signing or relaying an observation.
    lock.unlock();
    node.publishMinerReport(minerAddress,hashRate);
}
//================================================================================
//			GET ACTIVE MINERS COUNT
//================================================================================
int Blockchain::getActiveMinersCount() const {
    std::shared_lock<std::shared_mutex> lock(mtx);
    auto now = std::chrono::steady_clock::now();
    int count = 0;
    
    for (const auto& [address, lastActivity] : minerLastActivity) {
        auto timeSinceActivity = now - lastActivity;
        if (timeSinceActivity < std::chrono::minutes(2)) {
            count++;
        }
    }
    
    return count;
}

//================================================================================
//			CLEAN UP MINER ACTIVITY
//================================================================================
void Blockchain::cleanupInactiveMiners() {
    std::unique_lock<std::shared_mutex> lock(mtx);
    
    auto now = std::chrono::steady_clock::now();
    // Increased timeout to match getNetworkHashrate (3 minutes + 1 minute buffer)
    auto inactiveThreshold = std::chrono::minutes(5);
    
    std::vector<std::string> minersToRemove;
    
    for (auto it = minerLastActivity.begin(); it != minerLastActivity.end();) {
        auto timeSinceActivity = now - it->second;
        
        if (timeSinceActivity > inactiveThreshold) {
            const std::string& minerAddr = it->first;
            minersToRemove.push_back(minerAddr);
            
            Logger::log("[cleanupInactiveMiners] Removing inactive miner: " + minerAddr + 
                       " (inactive for " + 
                       std::to_string(std::chrono::duration_cast<std::chrono::minutes>(timeSinceActivity).count()) + 
                       " minutes)");
            
            // Remove from all collections
            activeMiners.erase(minerAddr);
            minerHashRates.erase(minerAddr);
            it = minerLastActivity.erase(it);
        } else {
            ++it;
        }
    }
    
    if (!minersToRemove.empty()) {
        Logger::log("[cleanupInactiveMiners] Cleaned up " + std::to_string(minersToRemove.size()) + " inactive miners");
    }
}
//================================================================================
//
//================================================================================
std::string Blockchain::extractAddressFromCoinbase(const Transaction& coinbase) const {
    if (!coinbase.isCoinbase || coinbase.vout.empty()) return "";
    
    // Assuming first output pays to miner
    const TxOut& firstOutput = coinbase.vout[0];
    return extractAddressFromScriptPubKey(firstOutput.scriptPubKey, coinbase.txid, 0, this);
}
