//           		 Constructors etc.
//=======================================================================================
Blockchain::Blockchain(const std::string &utxoDB, P2PNode& p2pNode)
    : Blockchain(utxoDB, std::string(tru_network::GENESIS_ADDRESS), p2pNode)
{
}

Blockchain::Blockchain(const std::string &utxoDB, const std::string &genesisAddr, P2PNode& p2pNode)
    : Blockchain(utxoDB, genesisAddr, p2pNode, false)
{
}

Blockchain::Blockchain(const std::string &utxoDB, const std::string &genesisAddr, P2PNode& p2pNode, bool noSeeds)
    : Blockchain(utxoDB, genesisAddr, p2pNode, noSeeds, false)
{
}

Blockchain::Blockchain(const std::string &utxoDB, const std::string &genesisAddr, P2PNode& p2pNode, bool noSeeds, bool validationOnly)
    : node(p2pNode),
      utxoSet(utxoDB, this, !validationOnly),
      dbStorage(utxoDB),
      mempool(std::make_unique<Mempool>(*this)),
      genesisAddress(genesisAddr),
      chainName("TRU"),
      ticker("TRU"),
      version("1.0"),
      networkType("mainnet"),
      maxSupply(21'000'000),
      halvingInterval(210'000),
      targetBlockTime(600),
      p2pPort(tru_network::MAINNET_P2P_PORT),
      rpcPort(tru_network::MAINNET_RPC_PORT),
      //difficulty(0x1d00ffff),
      //difficulty(0x2400ffff),   // OLD: target > 2^256, zero difficulty (nonce 0)
      difficulty(0x1e00ffff),     // ~16.8M hashes/block, real work; retarget climbs to 60s
      blockReward(50ULL * 100000000ULL),
      bestTipHeight(0),
      hashrateHistory(),
      startTime(std::chrono::steady_clock::now()),
      noSeeds_(noSeeds),
      validationOnly_(validationOnly)
{
    std::cout << "[Blockchain Constructor] Called with utxoDB=" << utxoDB << ", genesisAddr=" << genesisAddr << "\n";

    if (validationOnly_) {
        running_.store(false, std::memory_order_release);
        stopProcessing.store(true, std::memory_order_release);
        Logger::log(
            "[Patch08B.3] Constructed validation-only blockchain sandbox at " + utxoDB);
        return;
    }

    // A hard crash/SIGKILL cannot run the normal candidate cleanup lambda.
    // At normal live-chain startup there can be no legitimate in-process
    // sandbox yet, so remove only this datadir's dedicated sandbox root.
    cleanupStaleCandidateSandboxesForDb(dbStorage.path());

    bool loaded = loadChainState();
    Logger::log("[Blockchain Constructor] loadChainState completed. Loaded=" + std::string(loaded ? "true" : "false") + ", Best tip height: " + std::to_string(bestTipHeight));

    std::cout << "[Blockchain Constructor] loadChainState completed. Best tip height: " << bestTipHeight << "\n";

    // TRU CORE RECOVERY CR-01A v1: a direct-tip Phase-5 commit may have
    // durable state + U4 + exact block bytes while best-tip metadata still
    // points to the parent. Recover that authenticated publication gap BEFORE
    // genesis decisions, reorg recovery, or worker-thread startup.
    recoverDirectConnectPendingAtStartup();

    // TRU CORE RECOVERY CR-01B v1: incident-specific, gate-OFF one-time repair
    // for the already-proven pre-CR-01A height-355 contamination. If a partial
    // CR-01B marker exists, ordinary startup is refused until recovery resumes.
    recoverCR01BLegacyHeight355AtStartup();

    loaded = bestTipHeight.load() > 0;

    if (!loaded || bestTipHeight == 0) {
        Logger::log("[Blockchain Constructor] Best tip height is 0 or load failed, initializing Genesis Block...");
        std::cout << "[Blockchain Constructor] Best tip height is 0, initializing Genesis Block...\n";
        initGenesisBlock(genesisAddr);
    } else {
        for (int height = 1; height <= bestTipHeight; ++height) {
            if (!hashrateHistory.count(height)) {
                double hashrate = getNetworkHashrate(10);
                hashrateHistory[height] = hashrate;
                Logger::log("[Blockchain Constructor] Populated hashrate for height " + std::to_string(height) + ": " + std::to_string(hashrate));
            }
        }
        std::cout << "[Blockchain Constructor] Loaded existing blockchain with best tip hash: " << bestTipHash
                  << " at height: " << bestTipHeight << "\n";
    }

    // inspect any durable PREPARED reorg intent before worker
    // threads begin accepting work. 08B.4A has no executor, so a valid
    // PREPARED record is always an abandoned non-mutating intent and is
    // synchronously cleared. Corrupt/unknown records fail startup closed.
    recoverPreparedReorgMarkerAtStartup();

    try {
        blockProcessor = std::thread(&Blockchain::processBlocks, this);
        processorThread_ = std::thread(&Blockchain::processQueue, this);
        acceptedTxRelayThread_ = std::thread(&Blockchain::processAcceptedTransactionRelay, this);
    } catch (...) {
        running_=false;stopProcessing=true;acceptedTxRelay_.close();
        queueCond.notify_all();queueCond_.notify_all();
        if(blockProcessor.joinable())blockProcessor.join();
        if(processorThread_.joinable())processorThread_.join();
        if(acceptedTxRelayThread_.joinable())acceptedTxRelayThread_.join();
        throw;
    }
}

void Blockchain::processQueue() {
    std::size_t consecutiveBusy = 0;

    while (running_) {
        Transaction tx;
        std::size_t queuedSize = 0;
        std::uint8_t busyRetries = 0;

        {
            std::unique_lock<std::mutex> lock(queueMutex_);
            if (!queueCond_.wait_for(
                    lock,
                    std::chrono::seconds(1),
                    [this] { return !txQueue_.empty() || !running_; })) {
                continue;
            }

            if (!running_) break;
            if (txQueue_.empty()) continue;

            if (txQueueSizes_.empty() || txQueueRetries_.empty()) {
                Logger::log(
                    "[processQueue] ERROR: transaction queue accounting mismatch; "
                    "dropping queued entries fail-closed");
                while (!txQueue_.empty()) txQueue_.pop();
                while (!txQueueSizes_.empty()) txQueueSizes_.pop();
                while (!txQueueRetries_.empty()) txQueueRetries_.pop();
                txQueueTxids_.clear();
                txQueueBytes_ = 0;
                continue;
            }

            tx = std::move(txQueue_.front());
            txQueue_.pop();

            queuedSize = txQueueSizes_.front();
            txQueueSizes_.pop();

            busyRetries = txQueueRetries_.front();
            txQueueRetries_.pop();

            if (txQueueBytes_ >= queuedSize) {
                txQueueBytes_ -= queuedSize;
            } else {
                Logger::log(
                    "[processQueue] WARNING: queue byte accounting underflow prevented");
                txQueueBytes_ = 0;
            }
        }

        MempoolAddStatus status = MempoolAddStatus::INVALID;
        try {
            status = mempool->addTransaction(tx);
        } catch (const std::exception& e) {
            Logger::log(
                "[processQueue] ERROR: mempool admission threw; rejecting TX => " +
                tx.txid + ": " + e.what());
        } catch (...) {
            Logger::log(
                "[processQueue] ERROR: unknown mempool admission exception; rejecting TX => " +
                tx.txid);
        }

        if (status == MempoolAddStatus::BUSY) {
            ++consecutiveBusy;
            bool requeued = false;

            {
                std::lock_guard<std::mutex> lock(queueMutex_);

                if (busyRetries < tru_limits::MAX_MEMPOOL_BUSY_RETRIES &&
                    txQueue_.size() < tru_limits::MAX_TX_QUEUE_TXS &&
                    queuedSize <= tru_limits::MAX_TX_QUEUE_BYTES &&
                    txQueueBytes_ <=
                        tru_limits::MAX_TX_QUEUE_BYTES - queuedSize) {

                    txQueue_.push(tx);
                    txQueueSizes_.push(queuedSize);
                    txQueueRetries_.push(
                        static_cast<std::uint8_t>(busyRetries + 1));
                    txQueueBytes_ += queuedSize;
                    // Keep txQueueTxids_ set while the retry remains queued.
                    requeued = true;
                } else {
                    txQueueTxids_.erase(tx.txid);
                }
            }

            if (requeued) {
                Logger::log(
                    "[processQueue] Validation BUSY; requeued TX => " +
                    tx.txid +
                    " retry=" +
                    std::to_string(
                        static_cast<unsigned int>(busyRetries + 1)));
                queueCond_.notify_one();
            } else {
                Logger::log(
                    "[processQueue] Validation BUSY retry budget exhausted; "
                    "dropping queued TX under sustained overload => " +
                    tx.txid);
            }

            // Requeueing to the back already supplies fairness. Back off only
            // after repeated BUSY results demonstrate sustained saturation,
            // avoiding a 50-ms sleep on every individual queued transaction.
            if (consecutiveBusy >=
                tru_limits::MEMPOOL_BUSY_BACKOFF_BATCH) {
                std::this_thread::sleep_for(
                    std::chrono::milliseconds(
                        tru_limits::MEMPOOL_BUSY_RETRY_MILLIS));
                consecutiveBusy = 0;
            }
            continue;
        }

        // Any non-BUSY result means validation capacity became available.
        consecutiveBusy = 0;

        {
            std::lock_guard<std::mutex> lock(queueMutex_);
            txQueueTxids_.erase(tx.txid);
        }

        if (status == MempoolAddStatus::SUCCESS) {
            try {
                invalidateCachesForAcceptedMempoolTransaction(tx);
            } catch (const std::exception& e) {
                Logger::log(
                    "[processQueue] WARNING: accepted-TX cache invalidation failed => " +
                    tx.txid + ": " + e.what());
            } catch (...) {
                Logger::log(
                    "[processQueue] WARNING: accepted-TX cache invalidation threw unknown exception => " +
                    tx.txid);
            }
        }

        switch (status) {
            case MempoolAddStatus::SUCCESS:
                Logger::log(
                    "[processQueue] Mempool accepted queued TX => " + tx.txid);
                break;
            case MempoolAddStatus::DUPLICATE:
                Logger::log(
                    "[processQueue] Queued TX already known => " + tx.txid);
                break;
            case MempoolAddStatus::BUSY:
                break; // handled above
            case MempoolAddStatus::INVALID:
            default:
                Logger::log(
                    "[processQueue] Mempool rejected queued TX => " + tx.txid);
                break;
        }
    }

    Logger::log("[processQueue] Processor thread terminated.");
}

Blockchain::~Blockchain()
{
    if (validationOnly_) {
        running_.store(false, std::memory_order_release);
        stopProcessing.store(true, std::memory_order_release);
        queueCond.notify_all();
        Logger::log("[Patch08B.3] Destroying validation-only blockchain sandbox");
        return;
    }

    running_ = false;
    stopProcessing = true; // Signal thread to stop
    queueCond.notify_all(); // Wake up the thread
    stop();
    if (blockProcessor.joinable()) {
        blockProcessor.join(); // Wait for thread to finish
    }
    if (processorThread_.joinable()) {
        processorThread_.join(); // Wait for queue processor thread to finish
    }
    saveChainStateForShutdown();
    saveChainState();
    std::cout << "[Blockchain] destroyed.\n";
}


