// -----------------------------------------------------------------------------------------------------------
//                                      TOKENS
// -----------------------------------------------------------------------------------------------------------
g_explorerServer.Get("/api/tokens", [this](const httplib::Request& req, httplib::Response& res) {
    try {
        // Parse query parameters
        int start = 0;
        int limit = 10;
        if (req.has_param("start")) {
            start = std::stoi(req.get_param_value("start"));
            if (start < 0) start = 0;
        }
        if (req.has_param("limit")) {
            limit = std::stoi(req.get_param_value("limit"));
            if (limit <= 0 || limit > 100) limit = 10;
        }

        // Structure to hold token data
        struct TokenEntry {
            std::string tokenID;
            std::string type;
            uint64_t amount;
            std::string owner;
            std::string txid;
            uint32_t vout;
            bool burned = false;
            nlohmann::json meta;
        };
        std::vector<TokenEntry> tokens;

        // Iterate over tokenUTXO entries
        std::string prefix = "tokenUTXO:";
        Logger::log("[Explorer /api/tokens] Starting iteration over prefix: " + prefix);
        dbStorage.iteratePrefix(prefix, [&](const std::string& keySansPrefix, const std::string& value) {
            Logger::log("[Explorer /api/tokens] Processing key: " + keySansPrefix);

            // Expected format: <txid>:<vout>
            size_t pos = keySansPrefix.find(':');
            if (pos == std::string::npos || pos != 64) {
                Logger::log("[Explorer /api/tokens] Skipping invalid key format: " + keySansPrefix);
                return;
            }

            std::string txid = keySansPrefix.substr(0, 64);
            std::string voutStr = keySansPrefix.substr(65);
            uint32_t vout;
            try {
                vout = std::stoul(voutStr);
            } catch (const std::exception& e) {
                Logger::log("[Explorer /api/tokens] Invalid vout in key " + keySansPrefix + ": " + e.what());
                return;
            }

            try {
                nlohmann::json tokenUtxoJson = nlohmann::json::parse(value);
                if (!tokenUtxoJson.contains("owner") || !tokenUtxoJson["owner"].is_string()) {
                    Logger::log("[Explorer /api/tokens] Missing or invalid owner in JSON for key: " + keySansPrefix);
                    return;
                }

                TokenEntry entry;
                entry.tokenID = tokenUtxoJson["tokenID"].get<std::string>();
                entry.amount = tokenUtxoJson["amount"].is_string() ? std::stoull(tokenUtxoJson["amount"].get<std::string>()) : tokenUtxoJson["amount"].get<uint64_t>();
                entry.type = tokenUtxoJson["type"].get<std::string>();
                entry.owner = tokenUtxoJson["owner"].get<std::string>();
                entry.burned = tru_token_burn_v1::isBurnAddress(entry.owner);
                entry.txid = txid;
                entry.vout = vout;

                // resolve metadata current-first, issuance-second.
                //
                // The old code looked up ONLY "tokenMetadata:" + <this utxo's
                // txid>. Wallet::… writes a fresh tokenMetadata record under a
                // TRANSFER's txid (wallet.cpp ~2746), but plenty of UTXOs have
                // no such record, and for those the lookup returned nothing.
                // The browser then fell through to its 8-decimal default, so
                // one raw 2100000000 rendered as both 21000000.00 (decimals=2,
                // correct) and 21.00000000 (decimals=8, wrong).
                //
                // Always preferring the issuance record would be equally wrong,
                // since it would show stale metadata for a token whose state
                // has since evolved. So: try this UTXO's own record first, and
                // fall back to the canonical issuance record via
                // tokenIssuance:<tokenID>, the same two-step resolution
                // /api/wallet/tokens already uses.
                std::string metaValue;
                bool haveMeta =
                    dbStorage.getWithDataChecksum("tokenMetadata:" + txid, metaValue);

                if (!haveMeta) {
                    std::string issuanceTxid;
                    if (dbStorage.getWithDataChecksum("tokenIssuance:" + entry.tokenID,
                                                      issuanceTxid)
                        && !issuanceTxid.empty()) {
                        haveMeta = dbStorage.getWithDataChecksum(
                            "tokenMetadata:" + issuanceTxid, metaValue);
                    }
                }

                if (haveMeta) {
                    try {
                        nlohmann::json metaJson = nlohmann::json::parse(metaValue);
                        entry.meta = metaJson.value("meta", nlohmann::json::object());
                        Logger::log("[Explorer /api/tokens] Metadata fetched for token " + entry.tokenID);
                    } catch (const std::exception& e) {
                        Logger::log("[Explorer /api/tokens] Error parsing metadata for token " + entry.tokenID + ": " + e.what());
                        entry.meta = nlohmann::json::object();
                    }
                } else {
                    Logger::log("[Explorer /api/tokens] No metadata found for token " + entry.tokenID);
                    entry.meta = nlohmann::json::object();
                }

                tokens.push_back(entry);
                Logger::log("[Explorer /api/tokens] Added token: tokenID=" + entry.tokenID + ", txid=" + txid);
            } catch (const std::exception& e) {
                Logger::log("[Explorer /api/tokens] Error parsing tokenUTXO JSON for key " + keySansPrefix + ": " + e.what());
            }
        });

        // Log total tokens found
        Logger::log("[Explorer /api/tokens] Total tokens found: " + std::to_string(tokens.size()));

        // honour ?address=. script.js calls
        // /api/tokens?address=<addr> and then filters client side, but this
        // handler ignored the parameter and returned only the first `limit`
        // (default 10) tokenUTXO entries on the entire chain. Any address
        // whose tokens were not in that first 10 showed no holdings at all.
        if (req.has_param("address")) {
            const std::string wanted = req.get_param_value("address");
            if (!this->isValidAddress(wanted)) {
                res.status = 400;
                res.set_content(R"({"error":"Invalid TRU mainnet address"})",
                                "application/json");
                return;
            }

            std::vector<TokenEntry> filtered;
            filtered.reserve(tokens.size());
            for (const auto& t : tokens) {
                if (t.owner == wanted) filtered.push_back(t);
            }
            Logger::log("[Explorer /api/tokens] address=" + wanted + " matched " +
                        std::to_string(filtered.size()) + " of " +
                        std::to_string(tokens.size()) + " token UTXOs");
            tokens.swap(filtered);
        }

        // Apply pagination
        nlohmann::json j = nlohmann::json::array();
        int end = std::min(start + limit, static_cast<int>(tokens.size()));
        for (int i = start; i < end && i < tokens.size(); ++i) {
            const auto& token = tokens[i];
            nlohmann::json tokenJson = {
                {"tokenID", token.tokenID},
                {"type", token.type},
                {"amount", token.amount},
                {"owner", token.owner},
                {"txid", token.txid},
                {"vout", token.vout},
                {"burned", token.burned}
            };
            if (token.burned) {
                tokenJson["status"] = "BURNED";
                tokenJson["burnVersion"] = tru_token_burn_v1::VERSION;
                tokenJson["burnAddress"] = tru_token_burn_v1::BURN_ADDRESS;
            }
            if (!token.meta.is_null() && !token.meta.empty()) {
                tokenJson["meta"] = token.meta;
            }
            j.push_back(tokenJson);
        }

        // Set response
        res.set_content(j.dump(), "application/json");
        Logger::log("[Explorer /api/tokens] Response prepared with " + std::to_string(j.size()) + " items");
    } catch (const std::exception& e) {
        Logger::log("[Explorer /api/tokens] Error: " + std::string(e.what()));
        res.status = 500;
        res.set_content("{\"error\":\"" + std::string(e.what()) + "\"}", "application/json");
    }
});
