g_explorerServer.Get("/api/contracts", [&](const httplib::Request& /*req*/, httplib::Response& res) {
    // allow CORS
    res.set_header("Access-Control-Allow-Origin", "*");
    res.set_header("Content-Type", "application/json");
    Logger::log("[Explorer /api/contracts] Fetching contracts");

    try {
        // grab the JSON
        nlohmann::json data = getContracts();

        // sanity‑check that it really has a "contracts" array
        if (!data.is_object() || !data.contains("contracts") || !data["contracts"].is_array()) {
            throw std::runtime_error("Malformed contracts payload");
        }

        // all good — send it back
        res.status = 200;
        res.set_content(data.dump(2), "application/json");
    }
    catch (const std::exception& e) {
        Logger::log("[Explorer /api/contracts] Error: " + std::string(e.what()));
        res.status = 500;
        // a minimal JSON error body
        res.set_content(R"({"error":"Internal server error"})", "application/json");
    }
});

