g_explorerServer.Get(R"(/api/contracts/(T[1-9A-HJ-NP-Za-km-z]{33})/txs)", [&](const httplib::Request& req, httplib::Response& res) {
    res.set_header("Access-Control-Allow-Origin", "*");
    std::string address = req.matches[1];
    if (!this->isValidAddress(address)) {
        res.status = 400;
        res.set_content("{\"error\":\"Invalid TRU mainnet address\"}", "application/json");
        return;
    }
    nlohmann::json result = {{"address", address}, {"contracts", nlohmann::json::array()}};
    
    try {
        dbStorage.iteratePrefix("contract:" + address + ":", [&](const std::string& key, const std::string& value) {
            try {
                auto contract = nlohmann::json::parse(value);
                result["contracts"].push_back(contract);
            } catch (...) { /* ignore invalid */ }
        });
        res.set_content(result.dump(2), "application/json");
    } catch (const std::exception& e) {
        nlohmann::json err = {{"error", e.what()}};
        res.status = 500;
        res.set_content(err.dump(), "application/json");
    }
});
