//      				               MINERS
// -----------------------------------------------------------------------------------------------------------
// MINER-NETWORK-01: bounded, expiring observations from upgraded connected nodes.
// These values never modify local miner maps, chain history, balances or work.
g_explorerServer.Get("/api/miner-reports", [&](const httplib::Request&, httplib::Response& res) {
    res.set_header("Cache-Control","no-store");
    const auto reports=node.minerReports();
    std::map<std::string,unsigned> sourcesPerAddress;
    for(const auto& r:reports)++sourcesPerAddress[r.address];
    nlohmann::json rows=nlohmann::json::array();
    std::uint64_t total=0;unsigned unique=0,ambiguous=0;
    const auto now=tru_miner_telemetry::wallNow();
    for(const auto& r:reports) {
        const bool duplicate=sourcesPerAddress[r.address]>1;
        if(!duplicate) {total+=r.rate;++unique;} else ++ambiguous;
        rows.push_back({{"address",r.address},{"reporter",r.source},{"hashRate",r.rate},
            {"reportedAt",r.timestamp},{"expiresAt",r.timestamp+tru_miner_telemetry::TTL},
            {"local",r.local},{"ambiguous",duplicate},
            {"advertisedIP",duplicate?std::string{}:r.advertisedIP},
            {"ipSource",!duplicate&&!r.advertisedIP.empty()?"SIGNED_NODE_CONFIG":"UNAVAILABLE"},
            {"ipOwnershipVerified",false}});
    }
    nlohmann::json j={{"version","TRU-MINER-NETWORK-01"},{"generatedAt",now},
        {"reporter",node.minerReporterId()},{"reports",rows},{"reportedHashRate",total},
        {"minerIPVersion","TRU-MINER-IP-01"},
        {"unambiguousReports",unique},{"ambiguousReports",ambiguous},
        {"scope","OBSERVED_UPGRADED_P2P_COMPONENT"},{"hashWorkVerified",false},
        {"rewardAddressOwnershipVerified",false},{"capacity",tru_miner_telemetry::CAPACITY}};
    res.set_content(j.dump(),"application/json");
});

g_explorerServer.Get("/api/miners", [&](const httplib::Request& req, httplib::Response& res) {
    res.set_header("Access-Control-Allow-Origin", "*");
    res.set_header("Content-Type", "application/json");

    try {
        int timeoutMinutes = 2;
        if (req.has_param("timeout")) {
            try {
                timeoutMinutes = std::stoi(req.get_param_value("timeout"));
                timeoutMinutes = std::max(1, std::min(timeoutMinutes, 10));
            } catch (...) { timeoutMinutes = 2; }
        }

        int recentWindowBlocks = 50;
        if (req.has_param("recent")) {
            try {
                recentWindowBlocks = std::stoi(req.get_param_value("recent"));
                recentWindowBlocks = std::max(1, std::min(recentWindowBlocks, 500));
            } catch (...) { recentWindowBlocks = 50; }
        }

        const auto now = std::chrono::steady_clock::now();

        // EXPLORER-MINERS-03 producer cache.
        // The old endpoint rescanned heights 1..tip on every HTTP request. This
        // cache performs one initialization scan per process and thereafter copies
        // only newly connected coinbases. A changed cached anchor triggers a full
        // rebuild from the CURRENT active chain, making the cache reorg-safe. The
        // cache is explorer-derived data only; it never participates in validation,
        // PoW, difficulty, chain selection, rewards, relay or transaction policy.
        struct ProducerObservation {
            int height = 0;
            std::string blockHash;
            bool hasCoinbase = false;
            Transaction coinbase;
        };
        struct ProducerCacheState {
            std::mutex mutex;
            bool initialized = false;
            int tipHeight = 0;
            std::string tipHash;
            std::vector<std::string> producerByHeight{std::string{}}; // index 0 unused
            std::unordered_map<std::string, uint64_t> blockCount;
            std::unordered_map<std::string, int> lastHeight;
        };
        static ProducerCacheState producerCache;

        std::unordered_map<std::string, uint64_t> activeChainBlocks;
        std::unordered_map<std::string, uint64_t> recentChainBlocks;
        std::unordered_map<std::string, int> lastMinedHeight;
        int tipSnapshot = 0;
        std::string tipHashSnapshot;
        std::string cacheMode = "HIT";

        {
            std::lock_guard<std::mutex> cacheGuard(producerCache.mutex);
            std::vector<ProducerObservation> pending;
            bool rebuild = !producerCache.initialized;
            int startHeight = 1;

            {
                std::shared_lock<std::shared_mutex> chainRead(mtx);
                tipSnapshot = bestTipHeight.load();
                tipHashSnapshot = bestTipHash;

                if (!rebuild) {
                    if (producerCache.tipHeight > tipSnapshot) {
                        rebuild = true;
                    } else if (producerCache.tipHeight > 0) {
                        const size_t anchorIndex = static_cast<size_t>(producerCache.tipHeight - 1);
                        if (anchorIndex >= chain.size() ||
                            chain[anchorIndex].blockHash != producerCache.tipHash) {
                            rebuild = true;
                        }
                    }
                }

                startHeight = rebuild ? 1 : producerCache.tipHeight + 1;
                if (startHeight <= tipSnapshot) {
                    pending.reserve(static_cast<size_t>(tipSnapshot - startHeight + 1));
                    for (int h = startHeight; h <= tipSnapshot; ++h) {
                        const size_t idx = static_cast<size_t>(h - 1);
                        if (idx >= chain.size()) break;
                        const Block& b = chain[idx];
                        ProducerObservation obs;
                        obs.height = h;
                        obs.blockHash = b.blockHash;
                        if (!b.transactions.empty() && b.transactions[0].isCoinbase) {
                            obs.hasCoinbase = true;
                            obs.coinbase = b.transactions[0];
                        }
                        pending.push_back(std::move(obs));
                    }
                }
            }

            if (rebuild) {
                producerCache.producerByHeight.assign(1, std::string{});
                producerCache.blockCount.clear();
                producerCache.lastHeight.clear();
                producerCache.tipHeight = 0;
                producerCache.tipHash.clear();
                cacheMode = "FULL_REBUILD";
            } else if (!pending.empty()) {
                cacheMode = "DELTA";
            }

            for (const auto& obs : pending) {
                std::string address;
                if (obs.hasCoinbase) address = extractAddressFromCoinbase(obs.coinbase);
                while (producerCache.producerByHeight.size() <= static_cast<size_t>(obs.height)) {
                    producerCache.producerByHeight.push_back(std::string{});
                }
                producerCache.producerByHeight[static_cast<size_t>(obs.height)] = address;
                if (!address.empty()) {
                    ++producerCache.blockCount[address];
                    producerCache.lastHeight[address] = obs.height;
                }
                producerCache.tipHeight = obs.height;
                producerCache.tipHash = obs.blockHash;
            }

            if (tipSnapshot == 0) {
                producerCache.tipHeight = 0;
                producerCache.tipHash.clear();
            } else if (producerCache.tipHeight == tipSnapshot) {
                producerCache.tipHash = tipHashSnapshot;
            }
            producerCache.initialized = true;

            activeChainBlocks = producerCache.blockCount;
            lastMinedHeight = producerCache.lastHeight;

            const int recentStart = tipSnapshot > 0
                ? std::max(1, tipSnapshot - recentWindowBlocks + 1) : 1;
            for (int h = recentStart; h <= tipSnapshot; ++h) {
                const size_t idx = static_cast<size_t>(h);
                if (idx >= producerCache.producerByHeight.size()) break;
                const std::string& address = producerCache.producerByHeight[idx];
                if (!address.empty()) ++recentChainBlocks[address];
            }
        }

        const int recentStartHeight = tipSnapshot > 0
            ? std::max(1, tipSnapshot - recentWindowBlocks + 1) : 1;

        std::unordered_map<std::string, std::chrono::steady_clock::time_point> activitySnapshot;
        std::unordered_map<std::string, double> rateSnapshot;
        {
            std::shared_lock<std::shared_mutex> lock(mtx);
            activitySnapshot = minerLastActivity;
            rateSnapshot = minerHashRates;
        }

        std::unordered_set<std::string> addresses;
        for (const auto& kv : activeChainBlocks) addresses.insert(kv.first);
        for (const auto& kv : activitySnapshot) addresses.insert(kv.first);

        nlohmann::json j = nlohmann::json::array();
        double totalHashRate = 0.0;
        int localTelemetryActiveCount = 0;
        int recentProducerCount = 0;
        int recentProducerWithoutLocalTelemetryCount = 0;
        const auto timeoutDuration = std::chrono::minutes(timeoutMinutes);

        for (const auto& minerAddr : addresses) {
            const auto actIt = activitySnapshot.find(minerAddr);
            const bool hasLocalTelemetry = actIt != activitySnapshot.end();
            const auto timeSinceActivity = hasLocalTelemetry
                ? now - actIt->second : std::chrono::steady_clock::duration::zero();
            const bool localTelemetryFresh = hasLocalTelemetry && timeSinceActivity < timeoutDuration;

            double hashRate = 0.0;
            const auto rateIt = rateSnapshot.find(minerAddr);
            if (localTelemetryFresh && rateIt != rateSnapshot.end()) {
                hashRate = rateIt->second;
                totalHashRate += hashRate;
                ++localTelemetryActiveCount;
            }

            const uint64_t blocksMined = activeChainBlocks.count(minerAddr) ? activeChainBlocks.at(minerAddr) : 0;
            const uint64_t recentBlocksMined = recentChainBlocks.count(minerAddr) ? recentChainBlocks.at(minerAddr) : 0;
            const bool minedRecently = recentBlocksMined > 0;
            const int minerLastHeight = lastMinedHeight.count(minerAddr) ? lastMinedHeight.at(minerAddr) : 0;

            if (minedRecently) {
                ++recentProducerCount;
                if (!localTelemetryFresh) ++recentProducerWithoutLocalTelemetryCount;
            }

            int64_t lastActivityTimestamp = 0;
            int64_t timeSinceLastActivity = -1;
            if (hasLocalTelemetry) {
                lastActivityTimestamp = std::chrono::duration_cast<std::chrono::seconds>(
                    actIt->second.time_since_epoch()).count();
                timeSinceLastActivity = std::chrono::duration_cast<std::chrono::seconds>(
                    timeSinceActivity).count();
            }

            std::string visibility = "CHAIN_HISTORY_ONLY";
            if (minedRecently && localTelemetryFresh) visibility = "CHAIN_RECENT_LOCAL_TELEMETRY";
            else if (minedRecently) visibility = "CHAIN_RECENT_NO_LOCAL_TELEMETRY";
            else if (localTelemetryFresh) visibility = "LOCAL_TELEMETRY_ONLY";

            if (localTelemetryFresh || blocksMined > 0) {
                j.push_back({
                    {"address", minerAddr},
                    {"hashRate", hashRate},
                    {"isActive", localTelemetryFresh},
                    {"localTelemetryFresh", localTelemetryFresh},
                    {"hasLocalTelemetry", hasLocalTelemetry},
                    {"blocksMined", blocksMined},
                    {"recentBlocksMined", recentBlocksMined},
                    {"minedRecently", minedRecently},
                    {"lastMinedHeight", minerLastHeight},
                    {"lastActivityTimestamp", lastActivityTimestamp},
                    {"timeSinceLastActivity", timeSinceLastActivity},
                    {"telemetrySource", hasLocalTelemetry ? "LOCAL_RPC_TELEMETRY" : "CHAIN_ACTIVE_HISTORY"},
                    {"producerAuthority", blocksMined > 0 ? "ACTIVE_CHAIN_COINBASE" : "NONE"},
                    {"visibility", visibility}
                });
            }
        }

        std::sort(j.begin(), j.end(), [](const nlohmann::json& a, const nlohmann::json& b) {
            const bool ar = a["minedRecently"].get<bool>();
            const bool br = b["minedRecently"].get<bool>();
            if (ar != br) return ar > br;
            const uint64_t arb = a["recentBlocksMined"].get<uint64_t>();
            const uint64_t brb = b["recentBlocksMined"].get<uint64_t>();
            if (arb != brb) return arb > brb;
            const bool at = a["localTelemetryFresh"].get<bool>();
            const bool bt = b["localTelemetryFresh"].get<bool>();
            if (at != bt) return at > bt;
            const uint64_t ab = a["blocksMined"].get<uint64_t>();
            const uint64_t bb = b["blocksMined"].get<uint64_t>();
            if (ab != bb) return ab > bb;
            return a["address"].get<std::string>() < b["address"].get<std::string>();
        });

        nlohmann::json response = {
            {"success", true},
            {"miners", j},
            {"summary", {
                {"totalMiners", j.size()},
                {"activeMiners", localTelemetryActiveCount},
                {"totalHashRate", totalHashRate},
                {"timeoutMinutes", timeoutMinutes},
                {"tipHeight", tipSnapshot},
                {"recentWindowBlocks", recentWindowBlocks},
                {"recentStartHeight", recentStartHeight},
                {"recentProducerCount", recentProducerCount},
                {"recentProducerWithoutLocalTelemetryCount", recentProducerWithoutLocalTelemetryCount},
                {"localTelemetryActiveCount", localTelemetryActiveCount},
                {"remoteHashrateTrusted", false},
                {"minerHistoryAuthority", "ACTIVE_CHAIN_COINBASE"},
                {"recentProducerAuthority", "ACTIVE_CHAIN_COINBASE"},
                {"compatibility", "OBSERVATIONAL_NO_CONSENSUS_CHANGE"},
                {"producerCache", "EXPLORER-MINERS-03"},
                {"producerCacheMode", cacheMode}
            }},
            {"timestamp", std::chrono::duration_cast<std::chrono::seconds>(
                std::chrono::system_clock::now().time_since_epoch()).count()}
        };

        res.set_content(response.dump(), "application/json");
    } catch (const std::exception& e) {
        Logger::log("[Explorer /api/miners] Error => " + std::string(e.what()));
        res.status = 500;
        res.set_content(nlohmann::json({
            {"success", false}, {"error", e.what()}, {"miners", nlohmann::json::array()},
            {"summary", {{"totalMiners", 0}, {"activeMiners", 0}, {"totalHashRate", 0.0},
                         {"recentProducerCount", 0}, {"recentProducerWithoutLocalTelemetryCount", 0}}}
        }).dump(), "application/json");
    }
});
// -----------------------------------------------------------------------------------------------------------
//                                                Hash History
// -----------------------------------------------------------------------------------------------------------
g_explorerServer.Get("/api/hashrate_history", [&](const httplib::Request& req, httplib::Response& res) {
    res.set_header("Access-Control-Allow-Origin", "*");

    int blocks = 100;
    if (req.has_param("blocks")) {
        try {
            blocks = std::stoi(req.get_param_value("blocks"));
            blocks = std::min(std::max(blocks, 10), 500);
        } catch (...) {
            blocks = 100;
        }
    }

    nlohmann::json j = nlohmann::json::array();
    const int bestHeightCopy = bestTipHeight.load();
    if (bestHeightCopy < 2) {
        res.set_content("[]", "application/json");
        return;
    }

    const int startHeight = std::max(1, bestHeightCopy - blocks + 1);

    // EXPLORER-LOCK-02: never hold mtx across the full HTTP history walk.
    // Cache reads/writes get tiny critical sections; block/range helpers retain
    // their own locking. This removes the old reader-starvation pressure on the
    // active-tip writer and removes hundreds of per-height log writes.
    for (int height = startHeight; height <= bestHeightCopy; ++height) {
        double hashrate = 0.0;
        {
            std::shared_lock<std::shared_mutex> statsRead(derivedStatsMutex_);
            auto it = hashrateHistory.find(static_cast<uint32_t>(height));
            if (it != hashrateHistory.end()) {
                hashrate = it->second;
            }
        }

        if (hashrate <= 0.0) {
            const int windowStart = std::max(1, height - 5);
            const int windowEnd = std::min(bestHeightCopy, height + 5);
            if (windowEnd - windowStart >= 2) {
                hashrate = calculateHashrateForRange(windowStart, windowEnd);
                if (hashrate > 0.0) {
                    std::unique_lock<std::shared_mutex> statsWrite(derivedStatsMutex_);
                    hashrateHistory[static_cast<uint32_t>(height)] = hashrate;
                }
            }
        }

        if (hashrate > 0.0) {
            const auto blockOpt = getBlockByHeight(static_cast<uint64_t>(height));
            const uint32_t timestamp = blockOpt ? blockOpt->header.timestamp : 0;
            j.push_back({
                {"height", height},
                {"hashrate", hashrate},
                {"hashrate_gh", hashrate / 1e9},
                {"timestamp", timestamp}
            });
        }
    }

    Logger::log(
        "[Explorer] Returning " + std::to_string(j.size()) +
        " hashrate entries (EXPLORER-LOCK-02)");
    res.set_content(j.dump(), "application/json");
});
