//============================================================================================================
//			Enhanced Feed Endpoint with Post Count
//============================================================================================================
    g_explorerServer.Get(R"(/api/feed/([a-zA-Z0-9:]+))", [&](const httplib::Request& req, httplib::Response& res) {
        res.set_header("Access-Control-Allow-Origin", "*");
        std::string did = req.matches[1];
        nlohmann::json feed = nlohmann::json::array();
        std::string prefix = "social::did::" + did + "::posts::";
        std::string countKey = "social::did::" + did + "::postCount";
        std::string countStr;
        int postCount = 0;

        if (dbStorage.get(countKey, countStr)) {
            postCount = std::stoi(countStr);
        }

        try {
            dbStorage.iteratePrefix(prefix, [&](const std::string& key, const std::string&) {
                size_t lastColon = key.rfind("::");
                if (lastColon != std::string::npos) {
                    std::string txid = key.substr(lastColon + 2);
                    std::string postKey = "social::post::" + txid;
                    std::string postData;
                    if (dbStorage.get(postKey, postData)) {
                        feed.push_back(nlohmann::json::parse(postData));
                    }
                }
            });
            nlohmann::json response = {
                {"did", did},
                {"posts", feed},
                {"postCount", postCount}
            };
            res.set_content(response.dump(2), "application/json");
        } catch (const std::exception& e) {
            Logger::log("[API /api/feed] Error: " + std::string(e.what()));
            res.status = 500;
            res.set_content("{\"error\":\"Internal server error\"}", "application/json");
        }
    });
