    g_explorerServer.Get(R"(/api/did/([a-zA-Z0-9:]+))", [&](const httplib::Request& req, httplib::Response& res) {
        res.set_header("Access-Control-Allow-Origin", "*");
        std::string did = req.matches[1];
        std::string address = resolveDIDToAddress(did);
        if (address.empty()) {
            res.status = 404;
            res.set_content("{\"error\":\"DID not found\"}", "application/json");
            return;
        }
        std::string countKey = "social::did::" + did + "::postCount";
        std::string createdKey = "did::" + did + "::created";
        std::string countStr, createdStr;
        int postCount = 0;
        std::string createdTimestamp = "0";

        if (dbStorage.get(countKey, countStr)) {
            postCount = std::stoi(countStr);
        }
        if (dbStorage.get(createdKey, createdStr)) {
            createdTimestamp = createdStr;
        }

        nlohmann::json j = {
            {"did", did},
            {"address", address},
            {"postCount", postCount},
            {"createdTimestamp", createdTimestamp}
        };
        res.set_content(j.dump(2), "application/json");
    });
//============================================================================================================
//                                             WEB WALLET TOKEN
//============================================================================================================
g_explorerServer.Get(
    R"(/api/wallet/tokens/(T[1-9A-HJ-NP-Za-km-z]{33}))",
    [&](const httplib::Request& req, httplib::Response& res) {
        // WEB_WALLET_PATCH_2: tokenUTXO is the sole CURRENT holding source.
        res.set_header("Access-Control-Allow-Origin", "*");
        const std::string address = req.matches[1];
        if (!this->isValidAddress(address)) {
            res.status = 400;
            res.set_content("{\"error\":\"Invalid TRU mainnet address\"}", "application/json");
            return;
        }

        try {

            // WEB_WALLET_PATCH_2B:
            // One repair pass per address/process. Rebuild missing DERIVED
            // tokenUTXO/tokenOwnerUTXO records only when the controlling UTXO
            // is still live in the confirmed UTXO set.
            static std::mutex web2bRepairMutex;
            static std::unordered_set<std::string> web2bRepairedAddresses;

            bool web2bRunRepair = false;
            {
                std::lock_guard<std::mutex> lk(web2bRepairMutex);
                web2bRunRepair =
                    web2bRepairedAddresses.insert(address).second;
            }

            if (web2bRunRepair) {
                size_t web2bRepaired = 0;

                for (const auto& block : chain) {
                    for (const auto& tx : block.transactions) {
                        for (size_t idx = 0; idx < tx.vout.size(); ++idx) {
                            const auto& out = tx.vout[idx];

                            if (out.amount != 0 ||
                                out.scriptPubKey.rfind("6a", 0) != 0 ||
                                idx + 1 >= tx.vout.size())
                                continue;

                            const uint32_t controlVout =
                                static_cast<uint32_t>(idx + 1);

                            UTXO live;
                            if (!utxoSet.getUTXO(
                                    tx.txid, controlVout, live))
                                continue;

                            ExtendedTokenData tokenData;
                            std::string parsedOwner;

                            if (!parseExtendedTokenScript(
                                    out.scriptPubKey,
                                    tx.txid,
                                    tokenData,
                                    parsedOwner,
                                    this) ||
                                tokenData.type == TokenType::NONE)
                                continue;

                            std::string controlOwner;
                            try {
                                controlOwner =
                                    extractAddressFromScriptPubKey(
                                        tx.vout[controlVout].scriptPubKey,
                                        tx.txid,
                                        controlVout,
                                        this);
                            } catch (...) {
                                controlOwner.clear();
                            }

                            if (controlOwner != address)
                                continue;

                            const std::string tokenKey =
                                "tokenUTXO:" + tx.txid + ":" +
                                std::to_string(controlVout);

                            std::string existing;
                            if (!dbStorage.getWithDataChecksum(
                                    tokenKey, existing)) {

                                nlohmann::json record = {
                                    {"tokenID", tokenData.tokenID},
                                    {"amount",
                                        std::to_string(tokenData.amount)},
                                    {"owner", controlOwner},
                                    {"type",
                                        tokenTypeToString(tokenData.type)},
                                    {"controllingVout", controlVout}
                                };

                                if (dbStorage.putWithDataChecksum(
                                        tokenKey, record.dump())) {
                                    ++web2bRepaired;
                                    Logger::log(
                                        "[WEB2B][token-repair] restored " +
                                        tokenKey);
                                }
                            }

                            const std::string ownerKey =
                                "tokenOwnerUTXO:" +
                                tokenData.tokenID + ":" +
                                controlOwner + ":" +
                                tx.txid + ":" +
                                std::to_string(controlVout);

                            if (!dbStorage.exists(ownerKey)) {
                                dbStorage.putWithDataChecksum(
                                    ownerKey, "1");
                                Logger::log(
                                    "[WEB2B][token-repair] restored " +
                                    ownerKey);
                            }
                        }
                    }
                }

                Logger::log(
                    "[WEB2B][token-repair] address=" + address +
                    " repaired=" + std::to_string(web2bRepaired));
            }

            std::unordered_map<std::string, nlohmann::json> tokenMap;

            dbStorage.iteratePrefix(
                "tokenUTXO:",
                [&](const std::string& key, const std::string& raw) {
                    try {
                        const size_t colon = key.rfind(':');
                        if (colon == std::string::npos) return;

                        const std::string txid = key.substr(0, colon);
                        const uint32_t vout =
                            static_cast<uint32_t>(
                                std::stoul(key.substr(colon + 1)));

                        UTXO live;
                        if (!utxoSet.getUTXO(txid, vout, live))
                            return;

                        const auto t = nlohmann::json::parse(raw);
                        if (t.value("owner", "") != address)
                            return;

                        const std::string tokenID =
                            t.value("tokenID", "");
                        if (tokenID.empty()) return;

                        const uint64_t amount =
                            t["amount"].is_string()
                                ? std::stoull(
                                    t["amount"].get<std::string>())
                                : t["amount"].get<uint64_t>();

                        if (!tokenMap.count(tokenID)) {
                            tokenMap[tokenID] = {
                                {"tokenID", tokenID},
                                {"type", t.value("type", "Unknown")},
                                {"amount", 0ULL},
                                {"owner", address},
                                {"txid", txid},
                                {"vout", vout},
                                {"metadata", nlohmann::json::object()},
                                {"burned", tru_token_burn_v1::isBurnAddress(address)}
                            };
                        }

                        auto& result = tokenMap[tokenID];
                        result["amount"] =
                            result.value("amount", 0ULL) + amount;

                        std::string metaValue;
                        bool haveMeta =
                            dbStorage.getWithDataChecksum(
                                "tokenMetadata:" + txid, metaValue);
                        if (!haveMeta) {
                            std::string issuanceTxid;
                            if (dbStorage.getWithDataChecksum(
                                    "tokenIssuance:" + tokenID,
                                    issuanceTxid)) {
                                haveMeta =
                                    dbStorage.getWithDataChecksum(
                                        "tokenMetadata:" + issuanceTxid,
                                        metaValue);
                            }
                        }

                        if (haveMeta) {
                            try {
                                const auto m =
                                    nlohmann::json::parse(metaValue);
                                result["metadata"] =
                                    m.value(
                                        "meta",
                                        nlohmann::json::object());
                                result["type"] =
                                    m.value(
                                        "type",
                                        result.value("type", "Unknown"));
                            } catch (...) {
                            }
                        }
                    } catch (const std::exception& e) {
                        Logger::log(
                            "[Explorer /api/wallet/tokens][WEB2] " +
                            std::string(e.what()));
                    }
                });

            nlohmann::json tokens = nlohmann::json::array();
            for (auto& [tokenID, token] : tokenMap) {
                int decimals = 0;
                try {
                    const auto& md = token["metadata"];
                    if (md.contains("decimals")) {
                        if (md["decimals"].is_string())
                            decimals =
                                std::stoi(
                                    md["decimals"].get<std::string>());
                        else if (md["decimals"].is_number_integer())
                            decimals = md["decimals"].get<int>();
                    }
                } catch (...) {
                    decimals = 0;
                }

                token["displayAmount"] =
                    static_cast<double>(
                        token.value("amount", 0ULL)) /
                    std::pow(10.0, decimals);
                tokens.push_back(token);
            }

            res.set_content(
                nlohmann::json{
                    {"address", address},
                    {"tokens", tokens}
                }.dump(2),
                "application/json");
        } catch (const std::exception& e) {
            res.status = 500;
            res.set_content(
                nlohmann::json{{"error", e.what()}}.dump(),
                "application/json");
        }
    }
);
