// -----------------------------------------------------------------------------------------------------------
//                                      TOKEN TRANSACTIONS
// -----------------------------------------------------------------------------------------------------------
g_explorerServer.Get(
    R"(/api/wallet/token-transactions/(T[1-9A-HJ-NP-Za-km-z]{33}))",
    [&](const httplib::Request& req, httplib::Response& res) {
        // WEB_WALLET_PATCH_2: correct token issuance/sent/received history.
        res.set_header("Access-Control-Allow-Origin", "*");
        const std::string address = req.matches[1];
        if (!this->isValidAddress(address)) {
            res.status = 400;
            res.set_content("{\"error\":\"Invalid TRU mainnet address\"}", "application/json");
            return;
        }

        try {
            nlohmann::json rows = nlohmann::json::array();
            const int tip = getBestTipHeight();

            for (auto blockIt = chain.rbegin();
                 blockIt != chain.rend();
                 ++blockIt) {

                const Block& block = *blockIt;

                for (auto txIt = block.transactions.rbegin();
                     txIt != block.transactions.rend();
                     ++txIt) {

                    const Transaction& tx = *txIt;
                    std::unordered_map<std::string, std::string>
                        priorOwner;

                    for (const auto& vin : tx.vin) {
                        if (vin.isCoinbase() || vin.vout == 0)
                            continue;

                        Transaction prev;
                        if (!findTransaction(vin.txid, prev))
                            continue;

                        // WEB_WALLET_PATCH_2B:
                        // A token-control input at vout N belongs to the token
                        // OP_RETURN at N-1. Do NOT scan every token output in
                        // the previous transaction; split transfers can contain
                        // multiple owners for the same tokenID.
                        const uint32_t tokenVout = vin.vout - 1;
                        if (tokenVout >= prev.vout.size() ||
                            vin.vout >= prev.vout.size())
                            continue;

                        ExtendedTokenData oldData;
                        std::string oldOwner;

                        if (parseExtendedTokenScript(
                                prev.vout[tokenVout].scriptPubKey,
                                prev.txid,
                                oldData,
                                oldOwner,
                                this) &&
                            oldData.type != TokenType::NONE) {

                            try {
                                const std::string controlOwner =
                                    extractAddressFromScriptPubKey(
                                        prev.vout[vin.vout].scriptPubKey,
                                        prev.txid,
                                        vin.vout,
                                        this);
                                if (!controlOwner.empty())
                                    oldOwner = controlOwner;
                            } catch (...) {
                            }

                            if (!oldData.tokenID.empty() &&
                                !oldOwner.empty()) {
                                priorOwner[oldData.tokenID] = oldOwner;
                            }
                        }
                    }

                    for (const auto& out : tx.vout) {
                        ExtendedTokenData tokenData;
                        std::string tokenOwner;

                        if (!parseExtendedTokenScript(
                                out.scriptPubKey,
                                tx.txid,
                                tokenData,
                                tokenOwner,
                                this) ||
                            tokenData.type == TokenType::NONE)
                            continue;

                        const std::string tokenID = tokenData.tokenID;
                        const auto pit = priorOwner.find(tokenID);
                        const bool transfer =
                            pit != priorOwner.end() &&
                            !pit->second.empty();
                        const std::string from =
                            transfer ? pit->second : tokenOwner;

                        std::string type;
                        if (!transfer) {
                            if (tokenOwner != address) continue;
                            type = "Issued";
                        } else {
                            // Ignore sender's remainder output.
                            if (from == address && tokenOwner == address)
                                continue;

                            if (from == address &&
                                tokenOwner != address)
                                type = tru_token_burn_v1::isBurnAddress(tokenOwner)
                                    ? "Burned"
                                    : "Sent";
                            else if (tokenOwner == address &&
                                     from != address)
                                type = "Received";
                            else
                                continue;
                        }

                        std::string name = "Token_" + tokenID;
                        std::string symbol;
                        int decimals = 0;

                        std::string metaValue;
                        bool haveMeta =
                            dbStorage.getWithDataChecksum(
                                "tokenMetadata:" + tx.txid, metaValue);
                        if (!haveMeta) {
                            std::string issuanceTxid;
                            if (dbStorage.getWithDataChecksum(
                                    "tokenIssuance:" + tokenID,
                                    issuanceTxid)) {
                                haveMeta =
                                    dbStorage.getWithDataChecksum(
                                        "tokenMetadata:" + issuanceTxid,
                                        metaValue);
                            }
                        }

                        if (haveMeta) {
                            try {
                                const auto m =
                                    nlohmann::json::parse(metaValue);
                                const auto md =
                                    m.value(
                                        "meta",
                                        nlohmann::json::object());
                                name = md.value("name", name);
                                symbol = md.value("symbol", "");
                                if (md.contains("decimals")) {
                                    if (md["decimals"].is_string())
                                        decimals =
                                            std::stoi(
                                                md["decimals"]
                                                    .get<std::string>());
                                    else if (
                                        md["decimals"]
                                            .is_number_integer())
                                        decimals =
                                            md["decimals"].get<int>();
                                }
                            } catch (...) {
                            }
                        }

                        rows.push_back({
                            {"txid", tx.txid},
                            {"type", type},
                            {"tokenID", tokenID},
                            {"tokenName", name},
                            {"tokenSymbol", symbol},
                            {"tokenType",
                                tokenTypeToString(tokenData.type)},
                            {"amount", tokenData.amount},
                            {"decimals", decimals},
                            {"from", from},
                            {"to", tokenOwner},
                            {"burned", type == "Burned"},
                            {"burnVersion", type == "Burned"
                                ? tru_token_burn_v1::VERSION
                                : ""},
                            {"timestamp", block.header.timestamp},
                            {"blockHeight", block.height},
                            {"confirmations",
                                tip >= block.height
                                    ? tip - block.height + 1
                                    : 0}
                        });
                    }
                }
            }

            res.set_content(rows.dump(2), "application/json");
        } catch (const std::exception& e) {
            Logger::log(
                "[Explorer /api/wallet/token-transactions][WEB2] " +
                std::string(e.what()));
            res.status = 500;
            res.set_content(
                nlohmann::json{{"error", e.what()}}.dump(),
                "application/json");
        }
    }
);
