g_explorerServer.Get("/api/hashrate", [&](const httplib::Request&, httplib::Response& res) {
    res.set_header("Access-Control-Allow-Origin", "*");
    res.set_header("Content-Type", "application/json");
    
    try {
        // Get network hashrate (last 10 blocks by default)
        double networkHashrate = this->getNetworkHashrate(10);
        
        nlohmann::json response = {
            {"hashrate", networkHashrate},
            {"hashrate_gh", networkHashrate / 1e9},  // Gigahashes/sec
            {"hashrate_th", networkHashrate / 1e12}, // Terahashes/sec
            {"unit", "H/s"},
            {"timestamp", std::chrono::duration_cast<std::chrono::seconds>(
                std::chrono::system_clock::now().time_since_epoch()).count()}
        };
        
        res.set_content(response.dump(), "application/json");
        Logger::log("[Explorer /api/hashrate] Returned hashrate: " + std::to_string(networkHashrate) + " H/s");
        
    } catch (const std::exception& e) {
        Logger::log("[Explorer /api/hashrate] Error: " + std::string(e.what()));
        res.status = 500;
        res.set_content("{\"error\":\"" + std::string(e.what()) + "\"}", "application/json");
    }
});

//============================================================================================================
//                                     SUBMIT BLOCK ENDPOINT
//============================================================================================================
g_explorerServer.Post("/api/submitblock", [&](const httplib::Request& req, httplib::Response& res) {
    res.set_header("Access-Control-Allow-Origin", "*");
    res.set_header("Content-Type", "application/json");
    
    try {
        Logger::log("[Explorer /api/submitblock] Received block submission request");
        
        // Parse request body
        nlohmann::json requestData;
        try {
            requestData = nlohmann::json::parse(req.body);
        } catch (const std::exception& e) {
            Logger::log("[Explorer /api/submitblock] Invalid JSON in request body: " + std::string(e.what()));
            res.status = 400;
            res.set_content("{\"error\":\"Invalid JSON in request body\"}", "application/json");
            return;
        }
        
        // Extract block hex
        std::string blockHex;
        if (requestData.contains("blockHex") && requestData["blockHex"].is_string()) {
            blockHex = requestData["blockHex"].get<std::string>();
        } else if (requestData.contains("hex") && requestData["hex"].is_string()) {
            blockHex = requestData["hex"].get<std::string>();
        } else {
            Logger::log("[Explorer /api/submitblock] Missing 'blockHex' or 'hex' field");
            res.status = 400;
            res.set_content("{\"error\":\"Missing 'blockHex' or 'hex' field\"}", "application/json");
            return;
        }
        
        if (blockHex.empty()) {
            Logger::log("[Explorer /api/submitblock] Empty block hex provided");
            res.status = 400;
            res.set_content("{\"error\":\"Empty block hex\"}", "application/json");
            return;
        }
        
        Logger::log("[Explorer /api/submitblock] Processing block hex of length: " + std::to_string(blockHex.length()));
        
        // Deserialize the block
        Block block;
        try {
            block = Block::deserialize(blockHex);
            Logger::log("[Explorer /api/submitblock] Block deserialized successfully: " + block.blockHash);
        } catch (const std::exception& e) {
            Logger::log("[Explorer /api/submitblock] Block deserialization failed: " + std::string(e.what()));
            res.status = 400;
            res.set_content("{\"error\":\"Invalid block format: " + std::string(e.what()) + "\"}", "application/json");
            return;
        }
        
        // Basic validation checks
        if (block.blockHash.empty()) {
            Logger::log("[Explorer /api/submitblock] Block has empty hash");
            res.status = 400;
            res.set_content("{\"error\":\"Block has empty hash\"}", "application/json");
            return;
        }
        
        if (block.transactions.empty()) {
            Logger::log("[Explorer /api/submitblock] Block has no transactions");
            res.status = 400;
            res.set_content("{\"error\":\"Block has no transactions\"}", "application/json");
            return;
        }
        
        if (!block.transactions[0].isCoinbase) {
            Logger::log("[Explorer /api/submitblock] First transaction is not coinbase");
            res.status = 400;
            res.set_content("{\"error\":\"First transaction must be coinbase\"}", "application/json");
            return;
        }
        
        // Check if block already exists
        {
            std::shared_lock<std::shared_mutex> lock(mtx);
            if (blockIndex.count(block.blockHash)) {
                Logger::log("[Explorer /api/submitblock] Block already exists: " + block.blockHash);
                res.status = 200;
                res.set_content("{\"result\":\"duplicate\",\"message\":\"Block already exists\"}", "application/json");
                return;
            }
        }
        
        // Try to submit the block
        bool success = false;
        std::string errorMessage;
        
        try {
            //
            // Explorer HTTP block submission is untrusted network ingress.
            // Route side blocks through a bounded source bucket rather than
            // the trusted local/miner bucket.
            success = submitBlockFromNetwork(block, "explorer");
            if (success) {
                Logger::log("[Explorer /api/submitblock] Block submitted successfully: " + block.blockHash);
                
                // Broadcast to connected peers when P2P is enabled.
                try {
                    node.broadcastBlock(block);
                    Logger::log("[Explorer /api/submitblock] Block broadcasted to peers");
                } catch (const std::exception& e) {
                    Logger::log("[Explorer /api/submitblock] Failed to broadcast block: " + std::string(e.what()));
                    // Don't fail the submission just because broadcast failed
                }
                
                nlohmann::json response = {
                    {"result", "accepted"},
                    {"message", "Block accepted and added to chain"},
                    {"blockHash", block.blockHash},
                    {"height", block.height},
                    {"timestamp", std::chrono::duration_cast<std::chrono::seconds>(
                        std::chrono::system_clock::now().time_since_epoch()).count()}
                };
                
                res.status = 200;
                res.set_content(response.dump(), "application/json");
            } else {
                errorMessage = "Block validation failed";
                Logger::log("[Explorer /api/submitblock] Block validation failed: " + block.blockHash);
            }
        } catch (const std::exception& e) {
            errorMessage = std::string(e.what());
            Logger::log("[Explorer /api/submitblock] Exception during block submission: " + errorMessage);
        }
        
        if (!success) {
            nlohmann::json errorResponse = {
                {"result", "rejected"},
                {"error", errorMessage.empty() ? "Block submission failed" : errorMessage},
                {"blockHash", block.blockHash}
            };
            res.status = 400;
            res.set_content(errorResponse.dump(), "application/json");
        }
        
    } catch (const std::exception& e) {
        Logger::log("[Explorer /api/submitblock] Unexpected error: " + std::string(e.what()));
        res.status = 500;
        res.set_content("{\"error\":\"Internal server error\"}", "application/json");
    }
});
//============================================================================================================
// 			simple GET
//============================================================================================================
g_explorerServer.Get("/api/submitblock", [&](const httplib::Request&, httplib::Response& res) {
    res.set_header("Access-Control-Allow-Origin", "*");
    res.set_content("{\"message\":\"Use POST to submit blocks\"}", "application/json");
});
